function escapeHtml(str) {
  return String(str ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}
// =========================
// Український номер телефону
// =========================

function getUaPhoneDigits(
  value
) {
  let digits =
    String(value || "")
      .replace(/\D/g, "");

  if (
    digits.startsWith("380")
  ) {
    return digits.slice(
      0,
      12
    );
  }

  if (
    digits.startsWith("0")
  ) {
    digits =
      `38${digits}`;
  } else if (
    digits.length <= 9
  ) {
    digits =
      `380${digits}`;
  }

  return digits.slice(
    0,
    12
  );
}


function formatUaPhone(
  value
) {
  const digits =
    getUaPhoneDigits(
      value
    );

  if (!digits) {
    return "";
  }

  let result = "+";

  result +=
    digits.slice(0, 3);

  if (digits.length > 3) {
    result +=
      ` ${digits.slice(3, 5)}`;
  }

  if (digits.length > 5) {
    result +=
      ` ${digits.slice(5, 8)}`;
  }

  if (digits.length > 8) {
    result +=
      ` ${digits.slice(8, 10)}`;
  }

  if (digits.length > 10) {
    result +=
      ` ${digits.slice(10, 12)}`;
  }

  return result;
}


function isValidUaPhone(
  value
) {
  const digits =
    String(value || "")
      .replace(/\D/g, "");

  return (
    digits.length === 12 &&
    digits.startsWith("380")
  );
}


function bindUaPhoneInput(
  input
) {
  if (
    !input ||
    input.dataset
      .phoneMaskBound === "1"
  ) {
    return;
  }

  input.dataset.phoneMaskBound =
    "1";

  input.setAttribute(
    "maxlength",
    "17"
  );

  input.setAttribute(
    "inputmode",
    "numeric"
  );

  input.addEventListener(
    "keydown",
    (event) => {
      const allowedKeys = [
        "Backspace",
        "Delete",
        "ArrowLeft",
        "ArrowRight",
        "Tab",
        "Home",
        "End",
      ];

      if (
        allowedKeys.includes(
          event.key
        )
      ) {
        return;
      }

      if (
        event.ctrlKey ||
        event.metaKey
      ) {
        return;
      }

      if (
        !/^\d$/.test(
          event.key
        )
      ) {
        event.preventDefault();
      }
    }
  );

  input.addEventListener(
    "paste",
    (event) => {
      event.preventDefault();

      const pasted =
        event.clipboardData
          ?.getData("text") ||
        "";

      input.value =
        formatUaPhone(
          pasted
        );

      input.dispatchEvent(
        new Event(
          "input",
          {
            bubbles: true,
          }
        )
      );
    }
  );

  input.addEventListener(
    "input",
    () => {
      input.value =
        formatUaPhone(
          input.value
        );

      input.setCustomValidity(
        ""
      );
    }
  );

  input.addEventListener(
    "blur",
    () => {
      if (
        input.value &&
        !isValidUaPhone(
          input.value
        )
      ) {
        input.setCustomValidity(
          "Телефон повинен містити рівно 12 цифр у форматі +380 XX XXX XX XX"
        );
      } else {
        input.setCustomValidity(
          ""
        );
      }
    }
  );
}


function initPhoneInputs() {
  [
    "#visitNewOwnerPhone",
    "#staffPhone",
  ].forEach(
    (selector) => {
      bindUaPhoneInput(
        document.querySelector(
          selector
        )
      );
    }
  );
}
const OWNER_PHONE_COUNTRIES =
  Object.freeze({
    UA: {
      dialCode: "380",
      minLength: 9,
      maxLength: 9,
      groups: [2, 3, 2, 2],
      placeholder: "XX XXX XX XX",
      removeTrunkZero: true,
    },

    DE: {
      dialCode: "49",
      minLength: 5,
      maxLength: 11,
      groups: [3, 3, 5],
      placeholder: "XXX XXX XXXXX",
      removeTrunkZero: true,
    },

    AT: {
      dialCode: "43",
      minLength: 7,
      maxLength: 13,
      groups: [3, 3, 3, 4],
      placeholder: "XXX XXX XXX XXXX",
      removeTrunkZero: true,
    },

    PL: {
      dialCode: "48",
      minLength: 9,
      maxLength: 9,
      groups: [3, 3, 3],
      placeholder: "XXX XXX XXX",
      removeTrunkZero: false,
    },

    GB: {
      dialCode: "44",
      minLength: 10,
      maxLength: 10,
      groups: [4, 3, 3],
      placeholder: "XXXX XXX XXX",
      removeTrunkZero: true,
    },

    US: {
      dialCode: "1",
      minLength: 10,
      maxLength: 10,
      groups: [3, 3, 4],
      placeholder: "XXX XXX XXXX",
      removeTrunkZero: false,
    },
  });

function getOwnerPhoneConfig(
  country
) {
  return (
    OWNER_PHONE_COUNTRIES[
      String(country || "").toUpperCase()
    ] ||
    OWNER_PHONE_COUNTRIES.UA
  );
}

function detectOwnerPhoneCountry(
  value
) {
  let digits =
    String(value || "")
      .replace(/\D/g, "");

  if (digits.startsWith("00")) {
    digits =
      digits.slice(2);
  }

  const country =
    Object.keys(
      OWNER_PHONE_COUNTRIES
    ).find((code) => {
      return digits.startsWith(
        OWNER_PHONE_COUNTRIES[
          code
        ].dialCode
      );
    });

  return country || "UA";
}

function getOwnerNationalPhoneDigits(
  value,
  country
) {
  const config =
    getOwnerPhoneConfig(
      country
    );

  const raw =
    String(value || "")
      .trim();

  let digits =
    raw.replace(
      /\D/g,
      ""
    );

  if (raw.startsWith("00")) {
    digits =
      digits.slice(2);
  }

  if (
    (
      raw.startsWith("+") ||
      raw.startsWith("00") ||
      digits.length >
        config.maxLength
    ) &&
    digits.startsWith(
      config.dialCode
    )
  ) {
    digits =
      digits.slice(
        config.dialCode.length
      );
  }

  if (
    config.removeTrunkZero &&
    digits.startsWith("0")
  ) {
    digits =
      digits.slice(1);
  }

  return digits.slice(
    0,
    config.maxLength
  );
}

function formatOwnerNationalPhone(
  value,
  country
) {
  const config =
    getOwnerPhoneConfig(
      country
    );

  const digits =
    getOwnerNationalPhoneDigits(
      value,
      country
    );

  const parts = [];
  let position = 0;

  config.groups.forEach(
    (size) => {
      const part =
        digits.slice(
          position,
          position + size
        );

      if (part) {
        parts.push(part);
      }

      position += size;
    }
  );

  return parts.join(" ");
}

function isValidOwnerPhone(
  value,
  country
) {
  const config =
    getOwnerPhoneConfig(
      country
    );

  const digits =
    getOwnerNationalPhoneDigits(
      value,
      country
    );

  const fullLength =
    config.dialCode.length +
    digits.length;

  return (
    digits.length >=
      config.minLength &&
    digits.length <=
      config.maxLength &&
    fullLength >= 8 &&
    fullLength <= 15
  );
}

function buildOwnerPhone(
  value,
  country
) {
  if (
    !isValidOwnerPhone(
      value,
      country
    )
  ) {
    return "";
  }

  const config =
    getOwnerPhoneConfig(
      country
    );

  const digits =
    getOwnerNationalPhoneDigits(
      value,
      country
    );

  return (
    `+${config.dialCode}` +
    digits
  );
}

function updateOwnerPhonePlaceholder() {
  const countrySelect =
    document.querySelector(
      "#ownerModalPhoneCountry"
    );

  const phoneInput =
    document.querySelector(
      "#ownerModalPhone"
    );

  if (
    !countrySelect ||
    !phoneInput
  ) {
    return;
  }

  const config =
    getOwnerPhoneConfig(
      countrySelect.value
    );

  phoneInput.placeholder =
    config.placeholder;
}

function setOwnerPhoneEditorValue(
  value = ""
) {
  const countrySelect =
    document.querySelector(
      "#ownerModalPhoneCountry"
    );

  const phoneInput =
    document.querySelector(
      "#ownerModalPhone"
    );

  if (
    !countrySelect ||
    !phoneInput
  ) {
    return;
  }

  let country = "UA";

  if (value) {
    country =
      detectOwnerPhoneCountry(
        value
      );
  } else {
    try {
      const savedCountry =
        localStorage.getItem(
          "pug_owner_phone_country"
        );

      if (
        OWNER_PHONE_COUNTRIES[
          savedCountry
        ]
      ) {
        country =
          savedCountry;
      }
    } catch {}
  }

  countrySelect.value =
    country;

  phoneInput.value =
    value
      ? formatOwnerNationalPhone(
          value,
          country
        )
      : "";

  updateOwnerPhonePlaceholder();
}

function bindOwnerInternationalPhoneInput() {
  const countrySelect =
    document.querySelector(
      "#ownerModalPhoneCountry"
    );

  const phoneInput =
    document.querySelector(
      "#ownerModalPhone"
    );

  if (
    !countrySelect ||
    !phoneInput ||
    phoneInput.dataset
      .internationalPhoneBound ===
      "1"
  ) {
    return;
  }

  phoneInput.dataset
    .internationalPhoneBound =
    "1";

  phoneInput.addEventListener(
    "keydown",
    (event) => {
      const allowedKeys = [
        "Backspace",
        "Delete",
        "ArrowLeft",
        "ArrowRight",
        "Tab",
        "Home",
        "End",
      ];

      if (
        allowedKeys.includes(
          event.key
        ) ||
        event.ctrlKey ||
        event.metaKey
      ) {
        return;
      }

      if (
        !/^\d$/.test(
          event.key
        )
      ) {
        event.preventDefault();
      }
    }
  );

  phoneInput.addEventListener(
    "paste",
    (event) => {
      event.preventDefault();

      const pasted =
        event.clipboardData
          ?.getData("text") ||
        "";

      if (
        pasted.trim().startsWith("+") ||
        pasted.trim().startsWith("00")
      ) {
        countrySelect.value =
          detectOwnerPhoneCountry(
            pasted
          );
      }

      phoneInput.value =
        formatOwnerNationalPhone(
          pasted,
          countrySelect.value
        );

      updateOwnerPhonePlaceholder();

      phoneInput.dispatchEvent(
        new Event(
          "input",
          {
            bubbles: true,
          }
        )
      );
    }
  );

  phoneInput.addEventListener(
    "input",
    () => {
      phoneInput.value =
        formatOwnerNationalPhone(
          phoneInput.value,
          countrySelect.value
        );

      phoneInput.setCustomValidity(
        ""
      );
    }
  );

  countrySelect.addEventListener(
    "change",
    () => {
      try {
        localStorage.setItem(
          "pug_owner_phone_country",
          countrySelect.value
        );
      } catch {}

      phoneInput.value =
        formatOwnerNationalPhone(
          phoneInput.value,
          countrySelect.value
        );

      updateOwnerPhonePlaceholder();

      clearOwnerFieldError(
        phoneInput
      );

      phoneInput.focus();
    }
  );

  setOwnerPhoneEditorValue();
}
function normalizeTelegramUsername(value) {
  let telegram =
    String(value || "")
      .trim();

  telegram =
    telegram.replace(
      /^https?:\/\/t\.me\//i,
      ""
    );

  telegram =
    telegram.replace(
      /^@/,
      ""
    );

  telegram =
    telegram.replace(
      /[^a-zA-Z0-9_]/g,
      ""
    );

  return telegram
    ? `@${telegram.slice(0, 32)}`
    : "";
}


function isValidTelegramUsername(value) {
  const telegram =
    normalizeTelegramUsername(
      value
    );

  if (!telegram) {
    return true;
  }

  return /^@[a-zA-Z0-9_]{5,32}$/.test(
    telegram
  );
}


function bindTelegramInput(input) {
  if (
    !input ||
    input.dataset
      .telegramBound === "1"
  ) {
    return;
  }

  input.dataset.telegramBound =
    "1";

  input.setAttribute(
    "maxlength",
    "33"
  );

  input.addEventListener(
    "input",
    () => {
      input.setCustomValidity(
        ""
      );
    }
  );

  input.addEventListener(
    "blur",
    () => {
      input.value =
        normalizeTelegramUsername(
          input.value
        );

      if (
        input.value &&
        !isValidTelegramUsername(
          input.value
        )
      ) {
        input.setCustomValidity(
  translateInterfaceText(
    "owners.form.telegramFormat"
  )
);
      } else {
        input.setCustomValidity(
          ""
        );
      }
    }
  );
}


function initTelegramInputs() {
  [
    "#ownerModalTelegram",
    "#visitNewOwnerTelegram",
  ].forEach(
    (selector) => {
      bindTelegramInput(
        document.querySelector(
          selector
        )
      );
    }
  );
}
function todayISO() {
  const d = new Date();
  const pad = (n) => String(n).padStart(2, "0");
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
}
