let tasksBadgeLoading =
  false;


async function refreshMyTasksBadge() {
  if (tasksBadgeLoading) {
    return;
  }


  const taskMenuItem =
    document.querySelector(
      '#tabs [data-target="tasks"], ' +
      '#tabs [data-route="tasks"]'
    );


  if (!taskMenuItem) {
    return;
  }


  const taskMenuLink =
    taskMenuItem.querySelector(
      "a"
    ) ||
    taskMenuItem;


  let badge =
    taskMenuItem.querySelector(
      ".taskMenuBadge"
    );


  if (!badge) {
    badge =
      document.createElement(
        "span"
      );

    badge.className =
      "taskMenuBadge";

    badge.style.cssText = `
      display:none;
      align-items:center;
      justify-content:center;
      min-width:20px;
      height:20px;
      padding:0 6px;
      margin-left:6px;
      border-radius:999px;
      background:#ff625c;
      color:#fff;
      font-size:11px;
      font-weight:800;
      line-height:1;
      box-shadow:
        0 4px 14px
        rgba(255,98,92,.35);
    `;

    taskMenuLink.appendChild(
      badge
    );
  }


  tasksBadgeLoading =
    true;


  try {
    const params =
      new URLSearchParams({
        scope:
          "mine",

        status:
          "open",
      });


    const response =
      await fetch(
        `/api/tasks?${params.toString()}`,
        {
          method:
            "GET",

          credentials:
            "include",

          cache:
            "no-store",

          headers: {
            Accept:
              "application/json",

            ...getOrgHeaders(),
          },
        }
      );


    const result =
      await response
        .json()
        .catch(
          () => null
        );


    if (
      !response.ok ||
      !result?.ok
    ) {
      throw new Error(
        result?.error ||
        "Не вдалося завантажити задачі."
      );
    }


    const tasks =
      Array.isArray(
        result.data
      )
        ? result.data
        : [];
const currentTaskIds =
  tasks
    .map(
      (task) =>
        String(
          task?.id || ""
        ).trim()
    )
    .filter(
      Boolean
    );


if (!taskNotificationsReady) {
  currentTaskIds.forEach(
    (taskId) => {
      knownMyTaskIds.add(
        taskId
      );
    }
  );

  taskNotificationsReady =
    true;

} else {
  const newTasks =
    tasks.filter(
      (task) => {
        const taskId =
          String(
            task?.id || ""
          ).trim();

        return (
          taskId &&
          !knownMyTaskIds.has(
            taskId
          )
        );
      }
    );


  currentTaskIds.forEach(
    (taskId) => {
      knownMyTaskIds.add(
        taskId
      );
    }
  );


  if (
    newTasks.length
  ) {
    showAssignedTaskToast(
      newTasks[0],
      Math.max(
        0,
        newTasks.length - 1
      )
    );
  }
}

    const openTasks =
      tasks.filter(
        (task) =>
          String(
            task?.status ||
            "open"
          )
            .trim()
            .toLowerCase() !==
          "completed"
      );


    const count =
      openTasks.length;


    if (count > 0) {
      badge.textContent =
        count > 99
          ? "99+"
          : String(count);

      badge.style.display =
        "inline-flex";

    } else {
      badge.textContent =
        "";

      badge.style.display =
        "none";
    }

  } catch (error) {
    console.warn(
      "refreshMyTasksBadge failed:",
      error
    );

  } finally {
    tasksBadgeLoading =
      false;
  }
}


function startTasksBadgePoll() {
  if (tasksBadgePollStarted) {
    return;
  }


  tasksBadgePollStarted =
    true;


  refreshMyTasksBadge();


  setInterval(
    () => {
      refreshMyTasksBadge();
    },
    30000
  );
}

function isOwner() {
  return (
    getCurrentCrmRole() ===
    "owner"
  );
}


function isOwnerOrAdmin() {
  return [
    "owner",
    "admin",
  ].includes(
    getCurrentCrmRole()
  );
}


function canAccessRoute(
  route
) {
  const cleanRoute =
    String(route || "")
      .trim()
      .toLowerCase();

  const role =
    getCurrentCrmRole();

  const allowedRoutes =
    CRM_ROLE_ACCESS[role]
      ?.routes || [];

  return (
    allowedRoutes.includes("*") ||
    allowedRoutes.includes(
      cleanRoute
    )
  );
}


function canManageAllCalendar() {
  return [
    "owner",
    "admin",
    "assistant",
  ].includes(
    getCurrentCrmRole()
  );
}


function canManageCalendarStaff(
  staffId
) {
  if (canManageAllCalendar()) {
    return true;
  }

  const currentStaffId =
    getCurrentStaffId();

  return Boolean(
    currentStaffId &&
    String(staffId || "") ===
      currentStaffId
  );
}


function canOpenStaffProfile(
  staffId
) {
  if (isOwnerOrAdmin()) {
    return true;
  }

  const currentStaffId =
    getCurrentStaffId();

  return Boolean(
    currentStaffId &&
    String(staffId || "") ===
      currentStaffId
  );
}


function getDefaultAllowedRoute() {
  const preferred = [
    "calendar",
    "owners",
    "patients",
    "visits",
  ];

  return (
    preferred.find(
      canAccessRoute
    ) ||
    "owners"
  );
}


function applyRoleAccessUI() {
  document
    .querySelectorAll(
      "#tabs [data-target], " +
      "#tabs [data-route]"
    )
    .forEach((button) => {
      const route =
        button.dataset.target ||
        button.dataset.route ||
        "";

      const allowed =
        canAccessRoute(route);

      button.hidden =
        !allowed;

      button.style.display =
        allowed ? "" : "none";
    });

  document.body.dataset.crmRole =
    getCurrentCrmRole();
}

const TAB_ROUTES = new Set([
  "owners",
  "patients",
  "visits",
  "hospital",
  "services",
  "calendar",
  "tasks",
  "stock",
  "finance",
  "team",
  "audit",
  "settings",
]);

function parseHash() {
  const raw = (location.hash || "").replace("#", "").trim();
  if (!raw) return { route: "owners", id: null };

  const [routeRaw, idRaw] = raw.split(":");
  const route = (routeRaw || "owners").trim() || "owners";
  const id = idRaw != null ? String(idRaw).trim() : null;
  return { route, id };
}

function setHash(route, id = null) {
  const r = String(route || "owners").trim() || "owners";
    if (
    TAB_ROUTES.has(r) &&
    !canAccessRoute(r)
  ) {
    const fallback =
      getDefaultAllowedRoute();

    showCrmNotice({
      icon: "🔒",
      title: "Доступ обмежено",
      text:
        "Ваша роль не має доступу до цього розділу.",
    });

    if (
      location.hash.replace(
        "#",
        ""
      ) !== fallback
    ) {
      location.hash =
        fallback;
    }

    return;
  }
  const next = id ? `${r}:${id}` : r;
  if (location.hash.replace("#", "") !== next) location.hash = next;
}

function setRoute(route) {
  const r = String(route || "owners").trim() || "owners";
  const pageExists = document.querySelector(`.page[data-page="${r}"]`);
  const finalRoute = pageExists ? r : "owners";

  state.route = finalRoute;

  document.body.dataset.currentRoute =
  finalRoute;

const ownersSearchInput =
  document.getElementById(
    "globalSearch"
  );

const ownersSearchWrap =
  ownersSearchInput
    ?.parentElement;

if (ownersSearchWrap) {
  ownersSearchWrap.classList.add(
    "ownersGlobalSearchWrap"
  );

  ownersSearchWrap.hidden =
    finalRoute !== "owners";

  ownersSearchWrap.style.display =
    finalRoute === "owners"
      ? ""
      : "none";
}

if (ownersSearchInput) {
  ownersSearchInput.placeholder =
    translateInterfaceText(
      "owners.search.placeholder"
    );

  ownersSearchInput.setAttribute(
    "aria-label",
    translateInterfaceText(
      "owners.search.label"
    )
  );
}

  // Переключаем секции (в новом HTML они скрыты через display: none)
  Array.from(document.querySelectorAll(".page")).forEach((p) => {
    p.classList.toggle("active", p.dataset.page === finalRoute);
    if (p.dataset.page === finalRoute) {
      p.style.display = "block";
    } else {
      p.style.display = "none";
    }
  });

  // Подсвечиваем активную вкладку в новом боковом меню
  if (TAB_ROUTES.has(finalRoute)) {
    Array.from(document.querySelectorAll("#tabs .menu-item, #tabs .tab")).forEach((btn) => {
      const btnRoute = btn.dataset.target || btn.dataset.route;
      btn.classList.toggle("active", btnRoute === finalRoute);
    });
  }
}

function initTabs() {
  const tabs = document.getElementById("tabs");
  if (!tabs) return;

  tabs.addEventListener("click", (e) => {
    // Ловим клик по новому классу .menu-item
    const btn = e.target.closest(".menu-item") || e.target.closest(".tab");
    if (!btn) return;
    
    // Берем маршрут из нового data-target
    const route = btn.dataset.target || btn.dataset.route;
    if (!TAB_ROUTES.has(route)) return;
    
    setHash(route);
  });

  window.addEventListener("hashchange", routeFromHash);
  routeFromHash();
}

async function routeFromHash() {
  const { route, id } = parseHash();

  startTasksBadgePoll();
  if (
    TAB_ROUTES.has(route) &&
    !canAccessRoute(route)
  ) {
    const fallback =
      getDefaultAllowedRoute();

    showCrmNotice({
      icon: "🔒",
      title: "Доступ обмежено",
      text:
        "Цей розділ недоступний для вашої ролі.",
    });

    setHash(fallback);
    return;
  }
  if (TAB_ROUTES.has(route)) {
    setRoute(route);
    if (
  route === "owners"
) {
  renderOwners();

  await loadOwners();
}
    if (route === "patients") renderPatientsTab();
    if (route === "visits") renderVisitsTab();
if (route === "hospital") renderHospitalTab();
if (route === "services") renderServicesTab();
    if (route === "stock") renderStockTab();
    if (
  route === "finance"
) {
  await renderFinanceTab();
}
    if (route === "team") renderTeamTab();
    if (route === "tasks") {
  await renderTasksTab();
}
    if (route === "audit") {
      await renderAuditTab();
    }
    if (route === "calendar") {
  state.selectedVisitId = null;

  if (
    typeof closeVisitModal ===
    "function"
  ) {
    closeVisitModal();
  }

  await renderCalendarTab();
}
     if (route === "settings") {
       // Поскольку настройки статические, просто инициализируем их UI
       initSettingsUI();
    }
    return;
  }

  if (route === "owner") {
    if (id) openOwner(id, { pushHash: false });
    else setHash("owners");
    return;
  }

  if (route === "patient") {
    if (id) openPatient(id, { pushHash: false });
    else setHash("owners");
    return;
  }

  if (route === "visit") {
    if (id) openVisit(id, { pushHash: false });
    else setHash("owners");
    return;
  }

  if (route === "settings") renderSettingsTab();

  setHash("owners");
}

// ===== API /api/me =====
async function loadMe() {
  if (location.protocol === "file:") {
    state.me = null;
    setApiStatus(false, "API: /api/me ❌ (открыто через file://)");
    setMeLine("Гость • открой через http://localhost:8080");
    return;
  }

  setApiStatus(null, "API: проверяю /api/me …");
  setMeLine("Загрузка профиля…");

  try {
    const res = await fetch("/api/me", { credentials: "include" });
    if (!res.ok) throw new Error("HTTP " + res.status);
    const data = await res.json();

    state.me = data?.user || data?.me || data || null;
    const name = state.me?.name || state.me?.first_name || state.me?.username || "Пользователь";
    const tgId = state.me?.tg_user_id || state.me?.id || state.me?.user_id || null;

    setApiStatus(true, "API: /api/me ✅");
    setMeLine(tgId ? `${name} • tg_id: ${tgId}` : `${name}`);
  } catch {
    state.me = null;
    setApiStatus(false, "API: /api/me ❌ (пока нет бэка — это ок)");
    setMeLine("Гость • подключим бэк позже");
  }
}

