// ===== API: Owners =====
// ===== API: Owners =====
let ownersApiInFlight =
  null;


async function loadOwners(
  force = false
) {
  if (
    ownersApiInFlight &&
    !force
  ) {
    return ownersApiInFlight;
  }


  const cachedOwners =
    Array.isArray(
      state.owners
    ) &&
    state.owners.length
      ? state.owners
      : (
          Array.isArray(
            LS.get(
              OWNERS_KEY,
              []
            )
          )
            ? LS.get(
                OWNERS_KEY,
                []
              )
            : []
        );


  ownersApiInFlight =
    (async () => {
      const attempts = 3;

      const delays = [
        0,
        350,
        900,
      ];


      for (
        let attempt = 0;
        attempt < attempts;
        attempt++
      ) {
        if (
          delays[attempt]
        ) {
          await new Promise(
            (resolve) =>
              setTimeout(
                resolve,
                delays[attempt]
              )
          );
        }


        try {
          const response =
            await fetch(
              "/api/owners",
              {
                method:
                  "GET",

                credentials:
                  "include",

                cache:
                  "no-store",

                headers: {
                  Accept:
                    "application/json",

                  ...getOrgHeaders(),
                },
              }
            );


          const text =
            await response.text();


          let json = null;

          try {
            json =
              text
                ? JSON.parse(
                    text
                  )
                : null;

          } catch (
            parseError
          ) {
            throw new Error(
              "Сервер повернув некоректну відповідь."
            );
          }


          if (
            !response.ok ||
            !json ||
            json.ok !== true
          ) {
            throw new Error(
              json?.error ||
              `HTTP ${response.status}`
            );
          }


          const owners =
            Array.isArray(
              json.data
            )
              ? json.data
              : json.data
                ? [
                    json.data
                  ]
                : [];


          state.owners =
            owners;


          LS.set(
            OWNERS_KEY,
            owners
          );


          if (
            state.route ===
            "owners"
          ) {
            renderOwners();
          }


          if (
            state.route ===
              "owner" &&
            state.selectedOwnerId
          ) {
            await renderOwnerPage(
              state.selectedOwnerId
            );
          }


          return owners;

        } catch (error) {
          console.warn(
            `loadOwners attempt ${
              attempt + 1
            }/${attempts} failed:`,
            error
          );


          if (
            attempt <
            attempts - 1
          ) {
            continue;
          }


          console.error(
            "loadOwners failed after retries:",
            error
          );


          /*
           * ВАЖНО:
           * при временной ошибке
           * НЕ очищаем владельцев.
           */

          state.owners =
            cachedOwners;


          if (
            state.route ===
            "owners"
          ) {
            renderOwners();
          }


          return cachedOwners;
        }
      }


      return cachedOwners;
    })();


  try {
    return await ownersApiInFlight;

  } finally {
    ownersApiInFlight =
      null;
  }
}
// ===== API: Patients =====
let patientsApiInFlight = null;
let patientsApiLoading = false;
let patientsApiLoaded = false;

async function loadPatientsApi() {
  if (patientsApiInFlight) {
    return patientsApiInFlight;
  }

  patientsApiLoading = true;

  if (state.route === "patients") {
    renderPatientsTab();
  }

  patientsApiInFlight =
    loadPatientsApiRequest();

  try {
    return await patientsApiInFlight;
  } finally {
  patientsApiLoaded = true;
  patientsApiLoading = false;
  patientsApiInFlight = null;

  if (state.route === "patients") {
    renderPatientsTab();
  }

  if (state.route === "owners") {
    renderOwners();
  }

  if (
    state.route === "owner" &&
    state.selectedOwnerId
  ) {
    await renderOwnerPage(
      state.selectedOwnerId
    );
  }
}
}

async function loadPatientsApiRequest() {
  Object.assign(SETTINGS_INTERFACE_TEXT, {
    "Не вдалося завантажити пацієнтів.": {
      en: "Could not load patients.",
      de: "Die Patienten konnten nicht geladen werden.",
      pl: "Nie udało się wczytać pacjentów.",
    },
  });

  const cachedPatients = Array.isArray(state.patients)
    ? state.patients
    : [];

  try {
    const response = await fetch("/api/patients", {
      credentials: "include",
      headers: {
        Accept: "application/json",
        ...getOrgHeaders(),
      },
    });

    const responseText = await response.text();
    let json = null;

    try {
      json = responseText
        ? JSON.parse(responseText)
        : null;
    } catch {
      json = null;
    }

    if (!response.ok || json?.ok !== true) {
      throw new Error(
        json?.error ||
        `Patients loading HTTP ${response.status}`
      );
    }

    const patients = Array.isArray(json.data)
      ? json.data
      : json.data
        ? [json.data]
        : [];

    state.patients = patients;
    savePatients(patients);

    if (state.route === "patients") {
      renderPatientsTab();
    }

    if (
      state.route === "owner" &&
      state.selectedOwnerId
    ) {
      await renderOwnerPage(state.selectedOwnerId);
    }

    return patients;
  } catch (error) {
    console.error("Patients loading failed:", error);

    showSettingsMessage(
      getSettingsSafeErrorText(
        error,
        "Не вдалося завантажити пацієнтів."
      )
    );

    state.patients = cachedPatients;

    if (state.route === "patients") {
      renderPatientsTab();
    }

    if (
      state.route === "owner" &&
      state.selectedOwnerId
    ) {
      await renderOwnerPage(state.selectedOwnerId);
    }

    return cachedPatients;
  }
}

