async function loadHospitalizationsApi(
  active = true
) {
  try {
    const url =
      `/api/hospitalizations?active=${
        active ? "true" : "false"
      }`;

    const response = await fetch(url, {
      method: "GET",
      credentials: "include",
      headers: {
        Accept: "application/json",
        ...getOrgHeaders(),
      },
    });

    const text =
      await response.text();

    let json = null;

    try {
      json = text
        ? JSON.parse(text)
        : null;
    } catch {}

    if (
      !response.ok ||
      !json ||
      json.ok !== true
    ) {
      console.error(
        "loadHospitalizationsApi failed:",
        response.status,
        text
      );

      return [];
    }

    return Array.isArray(json.data)
      ? json.data
      : [];
  } catch (error) {
    console.error(
      "loadHospitalizationsApi error:",
      error
    );

    return [];
  }
}


async function createHospitalizationApi(
  payload
) {
  try {
    const response = await fetch(
      "/api/hospitalizations",
      {
        method: "POST",
        credentials: "include",

        headers: {
          "Content-Type":
            "application/json",

          Accept:
            "application/json",

          ...getOrgHeaders(),
        },

        body: JSON.stringify(
          payload || {}
        ),
      }
    );

    const text =
      await response.text();

    let json = null;

    try {
      json = text
        ? JSON.parse(text)
        : null;
    } catch {}

    if (
      !response.ok ||
      !json ||
      json.ok !== true
    ) {
      console.error(
        "createHospitalizationApi failed:",
        response.status,
        text
      );

      showHospitalAlert(
  json?.error ||
  "Не вдалося прийняти пацієнта у стаціонар."
);

      return null;
    }

    return json.data || null;
  } catch (error) {
    console.error(
      "createHospitalizationApi error:",
      error
    );

    showHospitalAlert(
  "Не вдалося з'єднатися із сервером."
);

    return null;
  }
}


