async function dischargeHospitalizationApi(
  hospitalizationId,
  notes = "",
  recommendations = ""
) {
  const currentRole =
    String(
      state.me?.role || ""
    ).toLowerCase();

  if (currentRole === "assistant") {
    openDeleteModal(
      `
        Виписувати пацієнтів зі стаціонару
        можуть ветеринар, адміністратор
        або власник клініки.
      `,
      null,
      "info"
    );

    return null;
  }

  try {
    const response =
      await fetch(
        `/api/hospitalizations/${
          encodeURIComponent(
            String(
              hospitalizationId
            )
          )
        }/discharge`,
        {
          method: "POST",
          credentials: "include",

          headers: {
            "Content-Type":
              "application/json",

            Accept:
              "application/json",

            ...getOrgHeaders(),
          },

                    body:
            JSON.stringify({
              notes:
                String(
                  notes || ""
                ).trim(),

              recommendations:
                String(
                  recommendations || ""
                ).trim(),
            }),
        }
      );

    const text =
      await response.text();

    let json = null;

    try {
      json = text
        ? JSON.parse(text)
        : null;
    } catch {}

    if (
      !response.ok ||
      !json ||
      json.ok !== true
    ) {
      console.error(
        "dischargeHospitalizationApi failed:",
        response.status,
        text
      );

      openDeleteModal(
        `
          ${
            json?.error ||
            "Не вдалося виписати пацієнта."
          }
        `,
        null,
        "info"
      );

      return null;
    }

    return json.data || null;

  } catch (error) {
    console.error(
      "dischargeHospitalizationApi error:",
      error
    );

    openDeleteModal(
      `
        Не вдалося з'єднатися із сервером.
      `,
      null,
      "info"
    );

    return null;
  }
}

async function createServiceApi(payload) {
  try {
    const res = await fetch("/api/services", {
      method: "POST",
      credentials: "include",
      headers: { "Content-Type": "application/json", Accept: "application/json", ...getOrgHeaders() },
      body: JSON.stringify(payload || {}),
    });
    const text = await res.text();
    let json = null;
    try { json = text ? JSON.parse(text) : null; } catch {}

    if (!res.ok || !json || !json.ok) return null;
    return Array.isArray(json.data) ? (json.data[0] || null) : (json.data || null);
  } catch (e) {
    console.error("createServiceApi failed:", e);
    return null;
  }
}

async function updateServiceApi(id, patch) {
  try {
    const res = await fetch(`/api/services?id=${encodeURIComponent(String(id))}`, {
      method: "PUT",
      credentials: "include",
      headers: { "Content-Type": "application/json", Accept: "application/json", ...getOrgHeaders() },
      body: JSON.stringify(patch || {}),
    });
    const text = await res.text();
    let json = null;
    try { json = text ? JSON.parse(text) : null; } catch {}

    if (!res.ok || !json || !json.ok) return null;
    return Array.isArray(json.data) ? (json.data[0] || null) : (json.data || null);
  } catch (e) {
    console.error("updateServiceApi failed:", e);
    return null;
  }
}

async function deleteServiceApi(id) {
  try {
    const res = await fetch(`/api/services?id=${encodeURIComponent(String(id))}`, {
      method: "DELETE",
      credentials: "include",
      headers: { Accept: "application/json", ...getOrgHeaders() },
    });
    const text = await res.text();
    let json = null;
    try { json = text ? JSON.parse(text) : null; } catch {}
    return !!(res.ok && json && json.ok);
  } catch (e) {
    console.error("deleteServiceApi failed:", e);
    return false;
  }
}

async function createPatientApi(payload) {
  try {
    const bodyObj = {
  owner_id:
    payload?.owner_id,

  name:
    String(
      payload?.name || ""
    ).trim(),

  species:
    String(
      payload?.species || ""
    ).trim(),

  breed:
    String(
      payload?.breed || ""
    ).trim(),

  age:
    String(
      payload?.age || ""
    ).trim(),

  weight_kg:
    String(
      payload?.weight_kg || ""
    ).trim(),

  sex:
    String(
      payload?.sex || ""
    ).trim(),

  neutered:
  typeof payload?.neutered ===
    "boolean"
    ? payload.neutered
    : null,


rabies_status:
  String(
    payload?.rabies_status ||
    "unknown"
  ).trim(),


general_vaccination_status:
  String(
    payload?.general_vaccination_status ||
    "unknown"
  ).trim(),


// Старые поля пока оставляем
// до полного перехыода форм.

vaccination_status:
  String(
    payload?.vaccination_status ||
    "unknown"
  ).trim(),

vaccination_date:
  String(
    payload?.vaccination_date ||
    ""
  ).trim(),

vaccination_name:
  String(
    payload?.vaccination_name ||
    ""
  ).trim(),


notes:
    String(
      payload?.notes ||
      payload?.note ||
      ""
    ).trim(),
};

    Object.keys(bodyObj).forEach((k) => {
      if (bodyObj[k] === "" || bodyObj[k] == null) delete bodyObj[k];
    });

    const res = await fetch("/api/patients", {
      method: "POST",
      headers: { "Content-Type": "application/json", Accept: "application/json", ...getOrgHeaders() },
      credentials: "include",
      body: JSON.stringify(bodyObj),
    });

    const text = await res.text();
    let json = null;
    try { json = text ? JSON.parse(text) : null; } catch {}

    if (!res.ok) {
      console.error("API /patients POST HTTP", res.status, text);
      alert(calendarErrorMessage(null, translateInterfaceText("calendar.detail.could.not.create.the.patient")));
      return null;
    }

    if (!json || !json.ok) {
      console.error("API /patients POST bad json", json, text);
      alert(calendarErrorMessage(json?.error, translateInterfaceText("calendar.detail.could.not.create.the.patient")));
      return null;
    }

    const created = Array.isArray(json.data) ? (json.data[0] || null) : (json.data || null);
    if (!created) return null;

    const next = [created, ...(Array.isArray(state.patients) ? state.patients : [])]
      .filter((x, i, a) => i === a.findIndex((y) => String(y?.id) === String(x?.id)));

    state.patients = next;
    savePatients(next);
    return created;
  } catch (err) {
    console.error("createPatientApi failed:", err);
    alert(calendarErrorMessage(null, translateInterfaceText("calendar.detail.could.not.create.the.patient")));
    return null;
  }
}
async function loadPatientWeightsApi(
  patientId,
  retry = true
) {
  try {
    const response =
      await fetch(
        `/api/patients/${
          encodeURIComponent(
            String(patientId)
          )
        }/weights`,
        {
          credentials:
            "include",

          headers: {
            Accept:
              "application/json",

            ...getOrgHeaders(),
          },
        }
      );

    const result =
      await response
        .json()
        .catch(() => null);

    if (
      !response.ok ||
      !result?.ok
    ) {
      throw new Error(
        result?.error ||
        "Не вдалося завантажити історію ваги."
      );
    }

    return Array.isArray(
      result.data
    )
      ? result.data
      : [];

  } catch (error) {

    if (retry) {
      await new Promise(
        (resolve) =>
          setTimeout(
            resolve,
            350
          )
      );

      return loadPatientWeightsApi(
        patientId,
        false
      );
    }

    throw error;
  }
}


