function openOwnerExistsModal(
  owner = {}
) {
  return new Promise(
    (resolve) => {
      const modal =
        $("#ownerExistsModal");

      const nameEl =
        $("#ownerExistsName");

      const phoneEl =
        $("#ownerExistsPhone");

      const confirmBtn =
        $("#ownerExistsConfirm");

      const cancelBtn =
        $("#ownerExistsCancel");

      const closeBtn =
        $("#ownerExistsClose");

      const backdrop =
        modal?.querySelector(
          ".pugOwnerExistsBackdrop"
        );

            if (
        !modal ||
        !nameEl ||
        !phoneEl ||
        !confirmBtn ||
        !cancelBtn ||
        !closeBtn
      ) {
        resolve(false);
        return;
      }

      applyInterfaceTranslations(
        modal
      );

      nameEl.textContent =
        String(
          owner?.name ||
          translateInterfaceText(
            "owners.exists.fallbackName"
          )
        );

      phoneEl.textContent =
        String(
          owner?.phone ||
          "—"
        );

      modal.style.display =
        "flex";

      modal.classList.add(
        "is-open"
      );

      const cleanup = () => {
        modal.classList.remove(
          "is-open"
        );

        modal.style.display =
          "none";

        confirmBtn.onclick =
          null;

        cancelBtn.onclick =
          null;

        closeBtn.onclick =
          null;

        if (backdrop) {
          backdrop.onclick =
            null;
        }

        document.removeEventListener(
          "keydown",
          handleEsc
        );
      };

      const finish = (
        value
      ) => {
        cleanup();
        resolve(value);
      };

      const handleEsc = (
        event
      ) => {
        if (
          event.key === "Escape"
        ) {
          finish(false);
        }
      };

      confirmBtn.onclick =
        () => finish(true);

      cancelBtn.onclick =
        () => finish(false);

      closeBtn.onclick =
        () => finish(false);

      if (backdrop) {
        backdrop.onclick =
          () => finish(false);
      }

      document.addEventListener(
        "keydown",
        handleEsc
      );
    }
  );
}
