function getServiceCategoryIcon(category) {
  const value =
    String(category || "")
      .trim()
      .toLowerCase();

  if (
    value.includes("терап")
  ) {
    return "🩺";
  }

  if (
    value.includes("анал")
  ) {
    return "🧪";
  }

  if (
    value.includes("хіру") ||
    value.includes("хирург")
  ) {
    return "✂️";
  }

  if (
    value.includes("діаг") ||
    value.includes("диаг")
  ) {
    return "🔬";
  }

  if (
    value.includes("виїзд") ||
    value.includes("выезд")
  ) {
    return "🚑";
  }

  if (
    value.includes("вакцин")
  ) {
    return "💉";
  }

  if (
    value.includes("стомат")
  ) {
    return "🦷";
  }

  if (
    value.includes("стаціон") ||
    value.includes("стацион")
  ) {
    return "🏥";
  }

  return "✨";
}


function getServiceCategoryColor(
  category
) {
  const value =
    String(category || "")
      .trim()
      .toLowerCase();

  if (value.includes("терап")) {
    return "#7c5cff";
  }

  if (value.includes("анал")) {
    return "#36c7ff";
  }

  if (
    value.includes("хіру") ||
    value.includes("хирург")
  ) {
    return "#ff6685";
  }

  if (
    value.includes("діаг") ||
    value.includes("диаг")
  ) {
    return "#51df9c";
  }

  if (
    value.includes("виїзд") ||
    value.includes("выезд")
  ) {
    return "#ffb84d";
  }

  if (value.includes("вакцин")) {
    return "#c06cff";
  }

  return "#9f67ff";
}


function getServiceCategories(
  services
) {
  const categories =
    Array.from(
      new Set(
        (services || [])
          .map((service) =>
            String(
              service?.cat ||
              "Інше"
            ).trim()
          )
          .filter(Boolean)
      )
    );

  const preferredOrder = [
    "Терапія",
    "Аналізи",
    "Хірургія",
    "Діагностика",
    "Вакцинація",
    "Стоматологія",
    "Стаціонар",
    "Виїзд",
    "Інше",
  ];

  return categories.sort(
    (a, b) => {
      const indexA =
        preferredOrder.indexOf(a);

      const indexB =
        preferredOrder.indexOf(b);

      return (
        (
          indexA === -1
            ? 999
            : indexA
        ) -
        (
          indexB === -1
            ? 999
            : indexB
        )
      );
    }
  );
}

