function openServiceDeleteConfirm(
  service
) {
  return new Promise(
    (resolve) => {
      document
        .getElementById(
          "serviceDeleteConfirm"
        )
        ?.remove();

      const modal =
        document.createElement(
          "div"
        );

      modal.id =
        "serviceDeleteConfirm";

      modal.className =
        "serviceDeleteOverlay";

      const serviceCategory =
        String(
          service?.cat ||
          "Інше"
        );

      const servicePrice =
        Number(
          service?.price || 0
        );

      modal.innerHTML = `
        <div
          class="serviceDeleteBackdrop"
          data-service-delete-cancel
        ></div>

        <section
          class="serviceDeleteModal"
          role="dialog"
          aria-modal="true"
        >
          <div class="serviceDeleteIcon">
            🗑
          </div>

          <div class="serviceDeleteEyebrow">
            ВИДАЛЕННЯ ПОСЛУГИ
          </div>

          <h2>
            Видалити послугу?
          </h2>

          <p>
            Послуга більше не буде
            доступна у каталозі клініки.
          </p>

          <div class="serviceDeleteService">
            <span>
              ${getServiceCategoryIcon(
                serviceCategory
              )}
            </span>

            <div>
              <strong
                data-services-content
              >
                ${escapeHtml(
                  service?.name ||
                  getServicesInterfaceText(
                    "Послуга"
                  )
                )}
              </strong>

              <small>
                ${escapeHtml(
                  getLocalizedServiceCategory(
                    serviceCategory
                  )
                )}

                ·

                ${servicePrice.toLocaleString(
                  getCalendarLocale()
                )}

                ${getServicesInterfaceText(
                  "грн"
                )}
              </small>
            </div>
          </div>

          <div class="serviceDeleteActions">
            <button
              type="button"
              class="serviceDeleteCancel"
              data-service-delete-cancel
            >
              Скасувати
            </button>

            <button
              type="button"
              class="serviceDeleteSubmit"
              id="serviceDeleteSubmit"
            >
              Видалити
            </button>
          </div>
        </section>
      `;

      localizeServicesElement(
        modal
      );

      document.body.appendChild(
        modal
      );

      const finish = (
        result
      ) => {
        modal.remove();
        resolve(result);
      };

      modal.addEventListener(
        "click",
        (event) => {
          if (
            event.target.closest(
              "[data-service-delete-cancel]"
            )
          ) {
            finish(false);
          }
        }
      );

      modal
        .querySelector(
          "#serviceDeleteSubmit"
        )
        ?.addEventListener(
          "click",
          () => {
            finish(true);
          }
        );
    }
  );
}


function openSpecializationCreateModal() {
  return new Promise((resolve) => {
    const themeColors = {
      purple: "#A855F7",
      black: "#F43F5E",
      white: "#5856D6",
      blue: "#06B6D4",
      green: "#10B981",
    };

    const activeTheme =
      document.body.dataset.theme ||
      "purple";

    const modal =
      document.createElement("div");

    modal.className =
      "specializationEditorOverlay";

    modal.innerHTML = `
      <button
        class="specializationEditorBackdrop"
        type="button"
        aria-label="Закрити"
        data-specialization-cancel
      ></button>

      <section
        class="specializationEditorModal"
        role="dialog"
        aria-modal="true"
        aria-labelledby="specializationEditorTitle"
      >
        <button
          class="specializationEditorClose"
          type="button"
          aria-label="Закрити"
          data-specialization-cancel
        >
          ×
        </button>

        <div class="specializationEditorHeader">
          <div class="specializationEditorIcon">✦</div>

          <div>
            <div class="specializationEditorEyebrow">
              НОВИЙ НАПРЯМ
            </div>

            <h2 id="specializationEditorTitle">
              Додати напрям
            </h2>

            <p>
              Створіть напрям клініки для фільтрації
              співробітників і спеціалізацій.
            </p>
          </div>
        </div>

        <form class="specializationEditorForm">
          <label class="specializationEditorField">
            <span>Назва напряму</span>
            <input
              id="specializationEditorName"
              type="text"
              maxlength="80"
              autocomplete="off"
              placeholder="Наприклад, Хірургія"
              required
            >
          </label>

          <label class="specializationEditorColorField">
            <span>
              <strong>Колір напряму</strong>
              <small>Використовується у списках і профілях</small>
            </span>

            <input
              id="specializationEditorColor"
              type="color"
              value="${themeColors[activeTheme] || themeColors.purple}"
            >
          </label>

          <div
            class="specializationEditorError"
            role="alert"
            aria-live="polite"
          ></div>

          <div class="specializationEditorActions">
            <button
              class="specializationEditorCancel"
              type="button"
              data-specialization-cancel
            >
              Скасувати
            </button>

            <button
              class="specializationEditorSubmit"
              type="submit"
            >
              Додати напрям
            </button>
          </div>
        </form>
      </section>
    `;

    document.body.appendChild(modal);

    const input = modal.querySelector(
      "#specializationEditorName"
    );

    const colorInput = modal.querySelector(
      "#specializationEditorColor"
    );

    const errorBox = modal.querySelector(
      ".specializationEditorError"
    );

    let finished = false;

    const finish = (result) => {
      if (finished) return;
      finished = true;
      document.removeEventListener(
        "keydown",
        handleKeydown
      );
      modal.remove();
      resolve(result);
    };

    const handleKeydown = (event) => {
      if (event.key === "Escape") {
        finish(null);
      }
    };

    document.addEventListener(
      "keydown",
      handleKeydown
    );

    modal
      .querySelectorAll(
        "[data-specialization-cancel]"
      )
      .forEach((button) => {
        button.addEventListener(
          "click",
          () => finish(null)
        );
      });

    modal
      .querySelector(
        ".specializationEditorForm"
      )
      ?.addEventListener(
        "submit",
        (event) => {
          event.preventDefault();

          const name = String(
            input?.value || ""
          ).trim();

          if (!name) {
            if (errorBox) {
              errorBox.textContent =
                "Вкажіть назву напряму.";
            }

            input?.focus();
            return;
          }

          finish({
            name,
            color:
              colorInput?.value ||
              themeColors.purple,
          });
        }
      );

    requestAnimationFrame(() => {
      input?.focus();
    });
  });
}

function getStaffSpecializations(staffRow) {
  return Array.isArray(
    staffRow?.specializations
  )
    ? staffRow.specializations.filter(
        (item) => item?.id && item?.name
      )
    : [];
}

function renderStaffSpecializationTags(
  staffRow,
  className = "premiumSpecTag"
) {
  const specializations =
    getStaffSpecializations(staffRow);

  if (specializations.length) {
    return specializations
      .map(
        (specialization) => `
          <span
            class="${escapeHtml(className)}"
            style="
              --specialization-color:
                ${escapeHtml(
                  specialization.color ||
                  "#7C5CFF"
                )};
            "
          >
            ${escapeHtml(
              specialization.name
            )}
          </span>
        `
      )
      .join("");
  }

  return `
    <span class="${escapeHtml(className)} is-empty">
      ${escapeHtml(
        staffRow?.specialization ||
        translateInterfaceText("calendar.detail.no.specialization.specified")
      )}
    </span>
  `;
}

function getStaffContrastColor(color) {
  const value = String(
    color || ""
  ).trim();

  let red = 124;
  let green = 92;
  let blue = 255;

  const shortHex =
    value.match(
      /^#([0-9a-f]{3})$/i
    );
  const fullHex =
    value.match(
      /^#([0-9a-f]{6})$/i
    );
  const rgbColor =
    value.match(
      /^rgba?\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)/i
    );

  if (shortHex) {
    red = parseInt(
      shortHex[1][0] +
      shortHex[1][0],
      16
    );
    green = parseInt(
      shortHex[1][1] +
      shortHex[1][1],
      16
    );
    blue = parseInt(
      shortHex[1][2] +
      shortHex[1][2],
      16
    );
  } else if (fullHex) {
    red = parseInt(
      fullHex[1].slice(0, 2),
      16
    );
    green = parseInt(
      fullHex[1].slice(2, 4),
      16
    );
    blue = parseInt(
      fullHex[1].slice(4, 6),
      16
    );
  } else if (rgbColor) {
    red = Number(rgbColor[1]);
    green = Number(rgbColor[2]);
    blue = Number(rgbColor[3]);
  } else {
    return "#6f91ad";
  }

  const luminance =
    (
      red * 0.2126 +
      green * 0.7152 +
      blue * 0.0722
    ) / 255;
  const chroma =
    Math.max(red, green, blue) -
    Math.min(red, green, blue);

  if (
    luminance > 0.82 &&
    chroma < 28
  ) {
    return "#6f91ad";
  }

  if (luminance > 0.7) {
    const darken = (channel) =>
      Math.max(
        0,
        Math.min(
          255,
          Math.round(
            channel * 0.62
          )
        )
      )
        .toString(16)
        .padStart(2, "0");

    return `#${darken(red)}${darken(green)}${darken(blue)}`;
  }

  return value;
}
