function normalizeTeamInterfaceText(
  value
) {
  return String(value || "")
    .replace(/\s+/g, " ")
    .trim();
}


function getTeamInterfaceText(
  sourceText
) {
  const language =
    getInterfaceLanguage();

  const normalizedSource =
    normalizeTeamInterfaceText(
      sourceText
    );

  const entry =
    Object.entries(
      TEAM_INTERFACE_TEXT
    ).find(
      ([
        ukrainian,
        translations,
      ]) =>
        [
          ukrainian,
          ...Object.values(
            translations
          ),
        ].some(
          (value) =>
            normalizeTeamInterfaceText(
              value
            ) ===
            normalizedSource
        )
    );

  if (!entry) {
    return String(
      sourceText || ""
    );
  }

  const [
    ukrainian,
    translations,
  ] = entry;

  return language === "uk"
    ? ukrainian
    : (
        translations[language] ||
        ukrainian
      );
}


function localizeTeamElement(
  root
) {
  if (!root) return;

  const walker =
    document.createTreeWalker(
      root,
      NodeFilter.SHOW_TEXT
    );

  const textNodes = [];

  while (walker.nextNode()) {
    textNodes.push(
      walker.currentNode
    );
  }

  textNodes.forEach(
    (node) => {
      if (
        node.parentElement
          ?.closest?.(
            "[data-team-content]"
          )
      ) {
        return;
      }

      const currentText =
        node.nodeValue || "";

      const normalized =
        normalizeTeamInterfaceText(
          currentText
        );

      if (!normalized) return;

      const translated =
        getTeamInterfaceText(
          normalized
        );

      if (
        translated === normalized
      ) {
        return;
      }

      const leadingSpace =
        currentText.match(
          /^\s*/
        )?.[0] || "";

      const trailingSpace =
        currentText.match(
          /\s*$/
        )?.[0] || "";

      node.nodeValue =
        leadingSpace +
        translated +
        trailingSpace;
    }
  );

  const elements = [
    root,
    ...root.querySelectorAll("*"),
  ];

  elements.forEach(
    (element) => {
      if (
        element?.closest?.(
          "[data-team-content]"
        )
      ) {
        return;
      }

      [
        "placeholder",
        "title",
        "aria-label",
      ].forEach(
        (attribute) => {
          if (
            !element?.hasAttribute?.(
              attribute
            )
          ) {
            return;
          }

          const currentValue =
            element.getAttribute(
              attribute
            ) || "";

          const translatedValue =
            getTeamInterfaceText(
              currentValue
            );

          if (
            translatedValue !==
            currentValue
          ) {
            element.setAttribute(
              attribute,
              translatedValue
            );
          }
        }
      );
    }
  );
}


function installTeamLocalization(
  root
) {
  if (!root) return;

  root
    ._teamLocalizationObserver
    ?.disconnect();

  localizeTeamElement(
    root
  );

  const observer =
    new MutationObserver(
      () => {
        localizeTeamElement(
          root
        );
      }
    );

  observer.observe(
    root,
    {
      childList: true,
      subtree: true,
    }
  );

  root._teamLocalizationObserver =
    observer;
}
