function renderTeamProfileTab(
  tab,
  state
) {
  const root =
    document.getElementById(
      "teamProfileContent"
    );

  if (!root) return;

  if (tab === "overview") {
    renderTeamOverviewTab(
      root,
      state
    );

    window.__lastTeamDashboard =
      state.dashboard;

    requestAnimationFrame(
      () => {
        renderStaffProfileCharts(
          state.dashboard,
          6
        );
      }
    );

    return;
  }

  if (tab === "analytics") {
    renderTeamAnalyticsTab(
      root,
      state
    );

    return;
  }

  if (tab === "visits") {
    renderTeamVisitsTab(
      root,
      state
    );

    return;
  }

  if (
    tab === "finance" &&
    !isOwnerOrAdmin()
  ) {
    showTeamNotice({
      icon: "🔒",

      title:
        "Фінанси приховано",

      text:
        "Доступ до фінансових нарахувань має лише керівництво клініки.",
    });

    renderTeamOverviewTab(
      root,
      state
    );

    return;
  }

  if (tab === "finance") {
    renderTeamFinanceTab(
      root,
      state
    );

    return;
  }

  if (
    tab ===
    "achievements"
  ) {
    renderTeamAchievementsTab(
      root,
      state
    );

    return;
  }

  if (tab === "settings") {
    renderTeamSettingsTab(
      root,
      state
    );
  }
}
Object.assign(
  TEAM_INTERFACE_TEXT,
  {
    "Завершено": {
      en: "Completed",
      de: "Abgeschlossen",
      pl: "Zakończono",
    },
  }
);
function getTeamMoneyText(
  value
) {
  return (
    Number(value || 0)
      .toLocaleString(
        getCalendarLocale()
      ) +
    " " +
    getTeamInterfaceText(
      "грн"
    )
  );
}


function getTeamLevelText(
  level
) {
  const value =
    Number(level || 1);

  const language =
    getInterfaceLanguage();

  if (language === "en") {
    return `Level ${value}`;
  }

  if (language === "de") {
    return `Stufe ${value}`;
  }

  if (language === "pl") {
    return `Poziom ${value}`;
  }

  return `Рівень ${value}`;
}


function getTeamNextLevelText(
  xp
) {
  const value =
    Number(xp || 0)
      .toLocaleString(
        getCalendarLocale()
      );

  const language =
    getInterfaceLanguage();

  if (language === "en") {
    return `${value} XP remaining to the next level`;
  }

  if (language === "de") {
    return `${value} XP bis zur nächsten Stufe`;
  }

  if (language === "pl") {
    return `${value} XP do następnego poziomu`;
  }

  return (
    `До наступного рівня ` +
    `залишилось ${value} XP`
  );
}


function getTeamOverviewInsightHtml({
  staffName,
  revenueGrowth,
  visitsGrowth,
  rating,
}) {
  const safeName =
    escapeHtml(
      staffName || ""
    );

  const safeRevenueGrowth =
    escapeHtml(
      String(
        Number(
          revenueGrowth || 0
        )
      )
    );

  const safeVisitsGrowth =
    escapeHtml(
      String(
        Number(
          visitsGrowth || 0
        )
      )
    );

  const safeRating =
    rating
      ? escapeHtml(
          Number(rating)
            .toFixed(2)
        )
      : "—";

  const language =
    getInterfaceLanguage();

  if (language === "en") {
    return `
      ${safeName} has stable performance:
      revenue changed by
      <strong>${safeRevenueGrowth}%</strong>,
      visits changed by
      <strong>${safeVisitsGrowth}%</strong>.
      Current client rating:
      <strong>${safeRating}</strong>.
    `;
  }

  if (language === "de") {
    return `
      ${safeName} zeigt stabile Ergebnisse:
      Der Umsatz hat sich um
      <strong>${safeRevenueGrowth}%</strong>
      verändert, die Anzahl der Termine um
      <strong>${safeVisitsGrowth}%</strong>.
      Aktuelle Kundenbewertung:
      <strong>${safeRating}</strong>.
    `;
  }

  if (language === "pl") {
    return `
      ${safeName} ma stabilne wyniki:
      przychód zmienił się o
      <strong>${safeRevenueGrowth}%</strong>,
      a liczba wizyt o
      <strong>${safeVisitsGrowth}%</strong>.
      Aktualna ocena klientów:
      <strong>${safeRating}</strong>.
    `;
  }

  return `
    ${safeName} має стабільні показники:
    виручка змінилась на
    <strong>${safeRevenueGrowth}%</strong>,
    кількість візитів — на
    <strong>${safeVisitsGrowth}%</strong>.
    Поточний рейтинг клієнтів —
    <strong>${safeRating}</strong>.
  `;
}


