function getTeamVisitStatusKey(
  value
) {
  return String(value || "")
    .trim()
    .toLowerCase()
    .replace(
      /[\s-]+/g,
      "_"
    );
}


function isTeamPlannedVisitStatus(
  value
) {
  const status =
    getTeamVisitStatusKey(
      value
    );

  return [
    "planned",
    "scheduled",
    "plan",
    "заплановано",
    "запланований",
    "запланирован",
    "запланировано",
    "geplant",
    "zaplanowano",
    "zaplanowane",
  ].includes(
    status
  );
}


function getTeamVisitStatusText(
  value
) {
  const original =
    String(value || "")
      .trim();

  const status =
    getTeamVisitStatusKey(
      original
    );

  if (
    [
      "planned",
      "scheduled",
      "plan",
      "заплановано",
      "запланований",
      "запланирован",
      "запланировано",
      "geplant",
      "zaplanowano",
      "zaplanowane",
    ].includes(status)
  ) {
    return getTeamInterfaceText(
      "Заплановано"
    );
  }

  if (
    [
      "completed",
      "complete",
      "done",
      "finished",
      "завершено",
      "завершений",
      "завершен",
      "abgeschlossen",
      "zakończono",
      "zakonczono",
    ].includes(status)
  ) {
    return getTeamInterfaceText(
      "Завершено"
    );
  }

  if (
    [
      "in_progress",
      "active",
      "started",
      "working",
      "в_роботі",
      "в_работе",
      "in_bearbeitung",
      "w_trakcie",
    ].includes(status)
  ) {
    return getTeamInterfaceText(
      "В роботі"
    );
  }

  if (
    [
      "cancelled",
      "canceled",
      "скасовано",
      "отменено",
      "storniert",
      "anulowano",
    ].includes(status)
  ) {
    return getTeamInterfaceText(
      "Скасовано"
    );
  }

  if (
    [
      "draft",
      "чернетка",
      "entwurf",
      "wersja_robocza",
    ].includes(status)
  ) {
    return getTeamInterfaceText(
      "Чернетка"
    );
  }

  return (
    original ||
    getTeamInterfaceText(
      "Завершено"
    )
  );
}


function getTeamVisitOwnerText(
  ownerName
) {
  const name =
    String(ownerName || "")
      .trim() ||
    getTeamInterfaceText(
      "Власник не вказаний"
    );

  const language =
    getInterfaceLanguage();

  if (language === "en") {
    return `Owner: ${name}`;
  }

  if (language === "de") {
    return `Tierhalter: ${name}`;
  }

  if (language === "pl") {
    return `Właściciel: ${name}`;
  }

  return `Власник: ${name}`;
}


function formatTeamVisitDate(
  value
) {
  const rawDate =
    String(value || "")
      .slice(0, 10);

  if (!rawDate) {
    return "—";
  }

  const date =
    new Date(
      `${rawDate}T00:00:00`
    );

  if (
    Number.isNaN(
      date.getTime()
    )
  ) {
    return rawDate;
  }

  return date.toLocaleDateString(
    getCalendarLocale(),
    {
      day: "2-digit",
      month: "2-digit",
      year: "numeric",
    }
  );
}


function renderTeamVisitsTab(
  root,
  state
) {
  const visits = [
    ...(
      state.dashboard
        .live_staff_visits ||
      []
    ),
  ];

  const monthVisits = [
    ...(
      state.dashboard
        .live_month_visits ||
      []
    ),
  ];

  const today =
    typeof todayISO ===
    "function"
      ? todayISO()
      : new Date()
          .toISOString()
          .slice(0, 10);

  const sortedVisits =
    visits.sort(
      (first, second) => {
        const firstDate =
          new Date(
            first.date ||
            first.event_date ||
            first.created_at ||
            0
          );

        const secondDate =
          new Date(
            second.date ||
            second.event_date ||
            second.created_at ||
            0
          );

        return (
          secondDate -
          firstDate
        );
      }
    );

  const sortedMonthVisits = [
    ...monthVisits,
  ].sort(
    (first, second) => {
      const firstDate =
        new Date(
          first.date ||
          first.event_date ||
          first.created_at ||
          0
        );

      const secondDate =
        new Date(
          second.date ||
          second.event_date ||
          second.created_at ||
          0
        );

      return (
        secondDate -
        firstDate
      );
    }
  );

  const todayVisits =
    sortedVisits.filter(
      (visit) => {
        const date =
          String(
            visit.date ||
            visit.event_date ||
            ""
          ).slice(
            0,
            10
          );

        return date === today;
      }
    );

  const plannedVisits =
    sortedVisits.filter(
      (visit) =>
        isTeamPlannedVisitStatus(
          visit.status ||
          visit.calendar_status
        )
    );

  root.innerHTML = `
    <section class="teamSubHero">
      <div>
        <h2>
          ${escapeHtml(
            getTeamInterfaceText(
              "🩺 Прийоми"
            )
          )}
        </h2>

        <p>
          ${escapeHtml(
            getTeamInterfaceText(
              "Історія прийомів, пацієнти та робоча активність співробітника."
            )
          )}
        </p>
      </div>
    </section>

    <section class="teamDashKpis">
      ${renderTeamKpiCard(
        "📋",
        "Усього прийомів",
        sortedVisits.length,
        0
      )}

      ${renderTeamKpiCard(
        "📅",
        "Цього місяця",
        sortedMonthVisits.length,
        0
      )}

      ${renderTeamKpiCard(
        "🎯",
        "Сьогодні",
        todayVisits.length,
        0
      )}

      ${renderTeamKpiCard(
        "⏳",
        "Заплановано",
        plannedVisits.length,
        0
      )}
    </section>

    <div class="teamVisitFilters">
      <button
        class="active"
        type="button"
        data-visit-filter="all"
      >
        ${escapeHtml(
          getTeamInterfaceText(
            "Усі"
          )
        )}
      </button>

      <button
        type="button"
        data-visit-filter="today"
      >
        ${escapeHtml(
          getTeamInterfaceText(
            "Сьогодні"
          )
        )}
      </button>

      <button
        type="button"
        data-visit-filter="month"
      >
        ${escapeHtml(
          getTeamInterfaceText(
            "Місяць"
          )
        )}
      </button>

      <button
        type="button"
        data-visit-filter="planned"
      >
        ${escapeHtml(
          getTeamInterfaceText(
            "Заплановані"
          )
        )}
      </button>
    </div>

    <section class="teamVisitsLayout">
      <div
        class="teamVisitsList"
        id="teamVisitsList"
      >
        ${renderTeamVisitCards(
          sortedVisits
        )}
      </div>

      <div class="teamDashPanel">
        <div class="teamDashPanelHead">
          <h3>
            ${escapeHtml(
              getTeamInterfaceText(
                "📌 Підсумок"
              )
            )}
          </h3>
        </div>

        <div class="teamDashRows">
          <p>
            <span>
              ${escapeHtml(
                getTeamInterfaceText(
                  "Усього прийомів"
                )
              )}
            </span>

            <b>
              ${sortedVisits.length}
            </b>
          </p>

          <p>
            <span>
              ${escapeHtml(
                getTeamInterfaceText(
                  "Сьогодні"
                )
              )}
            </span>

            <b>
              ${todayVisits.length}
            </b>
          </p>

          <p>
            <span>
              ${escapeHtml(
                getTeamInterfaceText(
                  "Цього місяця"
                )
              )}
            </span>

            <b>
              ${sortedMonthVisits.length}
            </b>
          </p>

          <p>
            <span>
              ${escapeHtml(
                getTeamInterfaceText(
                  "Заплановано"
                )
              )}
            </span>

            <b>
              ${plannedVisits.length}
            </b>
          </p>
        </div>
      </div>
    </section>
  `;

  const list =
    root.querySelector(
      "#teamVisitsList"
    );

  root
    .querySelectorAll(
      "[data-visit-filter]"
    )
    .forEach(
      (button) => {
        button.addEventListener(
          "click",
          () => {
            root
              .querySelectorAll(
                "[data-visit-filter]"
              )
              .forEach(
                (item) => {
                  item.classList.remove(
                    "active"
                  );
                }
              );

            button.classList.add(
              "active"
            );

            const filter =
              button.dataset
                .visitFilter;

            let filteredVisits =
              sortedVisits;

            if (
              filter === "today"
            ) {
              filteredVisits =
                todayVisits;
            }

            if (
              filter === "month"
            ) {
              filteredVisits =
                sortedMonthVisits;
            }

            if (
              filter === "planned"
            ) {
              filteredVisits =
                plannedVisits;
            }

            if (list) {
              list.innerHTML =
                renderTeamVisitCards(
                  filteredVisits
                );
            }
          }
        );
      }
    );

  list?.addEventListener(
    "click",
    (event) => {
      const button =
        event.target.closest(
          "[data-open-team-visit]"
        );

      if (!button) return;

      openVisitFromTeam(
        button.dataset
          .openTeamVisit
      );
    }
  );
}


function renderTeamVisitCards(
  visits
) {
  if (
    !Array.isArray(visits) ||
    !visits.length
  ) {
    return `
      <div
        class="
          teamDashPanel
          teamDashFull
        "
      >
        <h3>
          ${escapeHtml(
            getTeamInterfaceText(
              "Прийомів ще немає"
            )
          )}
        </h3>

        <p class="hint">
          ${escapeHtml(
            getTeamInterfaceText(
              "Коли співробітник буде проводити прийоми, вони зʼявляться тут."
            )
          )}
        </p>
      </div>
    `;
  }

  return visits
    .map(
      (visit) => {
        const date =
          formatTeamVisitDate(
            visit.date ||
            visit.event_date ||
            visit.created_at
          );

        const time =
          String(
            visit.time ||
            visit.start_time ||
            ""
          ).slice(
            0,
            5
          ) ||
          "—";

        const total =
          calcServicesTotal(
            visit
          ) +
          calcStockTotal(
            visit
          );

        const petName =
          visit.pet_name ||
          visit.patient_name ||
          visit.pet?.name ||
          getTeamInterfaceText(
            "Пацієнт"
          );

        const ownerName =
          visit.owner_name ||
          visit.client_name ||
          visit.owner?.name ||
          getTeamInterfaceText(
            "Власник не вказаний"
          );

        const status =
          getTeamVisitStatusText(
            visit.status ||
            visit.calendar_status ||
            "Завершено"
          );

        const visitId =
          String(
            visit.id ||
            visit.visit_id ||
            visit._id ||
            ""
          );

        return `
          <div class="teamVisitCard">
            <div class="teamVisitIcon">
              🐾
            </div>

            <div class="teamVisitMain">
              <div
                class="teamVisitTitle"
                data-team-content
              >
                ${escapeHtml(
                  petName
                )}
              </div>

              <div
                class="teamVisitMeta"
                data-team-content
              >
                ${escapeHtml(
                  date
                )}
                ·
                ${escapeHtml(
                  time
                )}
              </div>

              <div
                class="teamVisitOwner"
                data-team-content
              >
                ${escapeHtml(
                  getTeamVisitOwnerText(
                    ownerName
                  )
                )}
              </div>
            </div>

            <div class="teamVisitRight">
              <span
                class="teamVisitStatus"
                data-team-content
              >
                ${escapeHtml(
                  status
                )}
              </span>

              <b data-team-content>
                ${escapeHtml(
                  getTeamMoneyText(
                    total
                  )
                )}
              </b>

              <button
                type="button"
                class="teamVisitOpenBtn"
                data-open-team-visit="${escapeHtml(
                  visitId
                )}"
              >
                ${escapeHtml(
                  getTeamInterfaceText(
                    "Відкрити →"
                  )
                )}
              </button>
            </div>
          </div>
        `;
      }
    )
    .join("");
}


function openVisitFromTeam(
  visitId
) {
  if (!visitId) return;

  const id =
    String(visitId);

  if (
    typeof openVisit ===
    "function"
  ) {
    openVisit(id);
    return;
  }

  if (
    typeof openVisitModalForEdit ===
    "function"
  ) {
    openVisitModalForEdit(
      id
    );

    return;
  }

  alert(
    getTeamInterfaceText(
      "Не вдалося відкрити візит"
    )
  );
}
