function getTeamRevenueShareText(
  percentage
) {
  const value =
    Number(percentage || 0)
      .toLocaleString(
        getCalendarLocale()
      );

  const language =
    getInterfaceLanguage();

  if (language === "en") {
    return `${value}% of revenue`;
  }

  if (language === "de") {
    return `${value}% vom Umsatz`;
  }

  if (language === "pl") {
    return `${value}% przychodu`;
  }

  return `${value}% від виручки`;
}


async function renderTeamFinanceTab(
  root,
  state
) {
  const doc =
    state.doc;

  const visits =
    state.dashboard
      .live_month_visits ||
    [];

  const adjustments =
    await loadStaffAdjustmentsApi(
      doc.id
    );

  const revenue =
    visits.reduce(
      (sum, visit) =>
        sum +
        calcServicesTotal(
          visit
        ) +
        calcStockTotal(
          visit
        ),
      0
    );

  const shiftRate =
    Number(
      doc.shift_rate ||
      0
    );

  const percentRate =
    Number(
      doc.percent_rate ||
      0
    );

  const percentAmount =
    Math.round(
      revenue *
      (
        percentRate /
        100
      )
    );

  const bonuses =
    adjustments
      .filter(
        (item) =>
          item.type ===
          "bonus"
      )
      .reduce(
        (sum, item) =>
          sum +
          Number(
            item.amount ||
            0
          ),
        0
      );

  const penalties =
    adjustments
      .filter(
        (item) =>
          item.type ===
          "penalty"
      )
      .reduce(
        (sum, item) =>
          sum +
          Number(
            item.amount ||
            0
          ),
        0
      );

  const totalToPay =
    Math.max(
      0,
      shiftRate +
      percentAmount +
      bonuses -
      penalties
    );

  root.innerHTML = `
    <section class="teamSubHero">
      <div>
        <h2>
          ${escapeHtml(
            getTeamInterfaceText(
              "💰 Фінанси"
            )
          )}
        </h2>

        <p>
          ${escapeHtml(
            getTeamInterfaceText(
              "Нарахування, ставка, відсоток від виручки, бонуси та штрафи за цей місяць."
            )
          )}
        </p>
      </div>
    </section>

    <section class="teamDashKpis">
      ${renderTeamKpiCard(
        "💵",
        "Виручка",
        getTeamMoneyText(
          revenue
        ),
        0
      )}

      ${renderTeamKpiCard(
        "🏦",
        "Ставка",
        getTeamMoneyText(
          shiftRate
        ),
        0
      )}

      ${renderTeamKpiCard(
        "📈",
        "Відсоток",
        `${percentRate.toLocaleString(
          getCalendarLocale()
        )}%`,
        0
      )}

      ${renderTeamKpiCard(
        "✅",
        "До виплати",
        getTeamMoneyText(
          totalToPay
        ),
        0
      )}
    </section>

    <section class="teamVisitsLayout">
      <div class="teamDashPanel">
        <div class="teamDashPanelHead">
          <h3>
            ${escapeHtml(
              getTeamInterfaceText(
                "🧾 Бонуси та штрафи"
              )
            )}
          </h3>

          <button
            class="teamPrimaryBtn"
            id="btnAddFinanceAdjustment"
            type="button"
          >
            ${escapeHtml(
              getTeamInterfaceText(
                "+ Додати"
              )
            )}
          </button>
        </div>

        <div class="teamFinanceList">
          ${
            adjustments.length
              ? adjustments
                  .map(
                    (adjustment) => {
                      const isBonus =
                        adjustment.type ===
                        "bonus";

                      const typeText =
                        getTeamInterfaceText(
                          isBonus
                            ? "Бонус"
                            : "Штраф"
                        );

                      const reason =
                        String(
                          adjustment.reason ||
                          ""
                        ).trim() ||
                        getTeamInterfaceText(
                          "Без коментаря"
                        );

                      const date =
                        formatTeamVisitDate(
                          adjustment
                            .adjustment_date
                        );

                      return `
                        <div class="teamFinanceRow">
                          <div>
                            <b>
                              ${escapeHtml(
                                typeText
                              )}
                              ·
                              <span data-team-content>
                                ${escapeHtml(
                                  date
                                )}
                              </span>
                            </b>

                            <span data-team-content>
                              ${escapeHtml(
                                reason
                              )}
                            </span>
                          </div>

                          <strong
                            class="${
                              isBonus
                                ? "moneyPlus"
                                : "moneyMinus"
                            }"
                            data-team-content
                          >
                            ${
                              isBonus
                                ? "+"
                                : "-"
                            }${escapeHtml(
                              getTeamMoneyText(
                                adjustment.amount
                              )
                            )}
                          </strong>

                          <button
                            class="financeDeleteBtn"
                            type="button"
                            data-delete-adjustment="${escapeHtml(
                              String(
                                adjustment.id
                              )
                            )}"
                            title="${escapeHtml(
                              getTeamInterfaceText(
                                "Видалити"
                              )
                            )}"
                          >
                            <svg
                              viewBox="0 0 24 24"
                              width="16"
                              height="16"
                              fill="none"
                              aria-hidden="true"
                            >
                              <path
                                d="M8 8L16 16M16 8L8 16"
                                stroke="currentColor"
                                stroke-width="2.5"
                                stroke-linecap="round"
                              />
                            </svg>
                          </button>
                        </div>
                      `;
                    }
                  )
                  .join("")
              : `
                <div class="hint">
                  ${escapeHtml(
                    getTeamInterfaceText(
                      "Поки немає бонусів або штрафів за цей місяць."
                    )
                  )}
                </div>
              `
          }
        </div>
      </div>

      <div class="teamDashPanel">
        <div class="teamDashPanelHead">
          <h3>
            ${escapeHtml(
              getTeamInterfaceText(
                "📌 Розрахунок"
              )
            )}
          </h3>
        </div>

        <div class="teamDashRows">
          <p>
            <span>
              ${escapeHtml(
                getTeamInterfaceText(
                  "Виручка місяця"
                )
              )}
            </span>

            <b>
              ${escapeHtml(
                getTeamMoneyText(
                  revenue
                )
              )}
            </b>
          </p>

          <p>
            <span>
              ${escapeHtml(
                getTeamInterfaceText(
                  "Ставка"
                )
              )}
            </span>

            <b>
              ${escapeHtml(
                getTeamMoneyText(
                  shiftRate
                )
              )}
            </b>
          </p>

          <p>
            <span>
              ${escapeHtml(
                getTeamRevenueShareText(
                  percentRate
                )
              )}
            </span>

            <b>
              ${escapeHtml(
                getTeamMoneyText(
                  percentAmount
                )
              )}
            </b>
          </p>

          <p>
            <span>
              ${escapeHtml(
                getTeamInterfaceText(
                  "Бонуси"
                )
              )}
            </span>

            <b
              class="moneyPlus"
              data-team-content
            >
              +${escapeHtml(
                getTeamMoneyText(
                  bonuses
                )
              )}
            </b>
          </p>

          <p>
            <span>
              ${escapeHtml(
                getTeamInterfaceText(
                  "Штрафи"
                )
              )}
            </span>

            <b
              class="moneyMinus"
              data-team-content
            >
              -${escapeHtml(
                getTeamMoneyText(
                  penalties
                )
              )}
            </b>
          </p>

          <p>
            <span>
              ${escapeHtml(
                getTeamInterfaceText(
                  "До виплати"
                )
              )}
            </span>

            <b>
              ${escapeHtml(
                getTeamMoneyText(
                  totalToPay
                )
              )}
            </b>
          </p>
        </div>
      </div>
    </section>
  `;

  bindFinanceAdjustments(
    root,
    state
  );
}


function bindFinanceAdjustments(
  root,
  state
) {
  root
    .querySelector(
      "#btnAddFinanceAdjustment"
    )
    ?.addEventListener(
      "click",
      () => {
        openFinanceAdjustmentModal(
          root,
          state
        );
      }
    );

  root
    .querySelectorAll(
      "[data-delete-adjustment]"
    )
    .forEach(
      (button) => {
        button.addEventListener(
          "click",
          () => {
            openDeleteModal(
              getTeamInterfaceText(
                "Видалити запис?"
              ),

              async () => {
                try {
                  const id =
                    button.dataset
                      .deleteAdjustment;

                  await deleteStaffAdjustmentApi(
                    id
                  );

                  await renderTeamFinanceTab(
                    root,
                    state
                  );
                } catch (error) {
                  console.error(
                    error
                  );

                  openDeleteModal(
                    getTeamInterfaceText(
                      "Не вдалося видалити запис."
                    ),
                    null,
                    "info"
                  );
                }
              }
            );
          }
        );
      }
    );
}


function openFinanceAdjustmentModal(
  root,
  state
) {
  document
    .querySelector(
      ".financeAdjustModalOverlay"
    )
    ?.remove();

  const modal =
    document.createElement(
      "div"
    );

  modal.className =
    "financeAdjustModalOverlay";

  modal.innerHTML = `
    <div class="financeAdjustModal">
      <button
        class="financeAdjustClose"
        type="button"
        aria-label="Close"
      >
        ×
      </button>

      <div class="financeAdjustHead">
        <div class="financeAdjustIcon">
          💰
        </div>

        <div>
          <h2>
            ${escapeHtml(
              getTeamInterfaceText(
                "Додати нарахування"
              )
            )}
          </h2>

          <p>
            ${escapeHtml(
              getTeamInterfaceText(
                "Додайте бонус або штраф співробітнику за поточний місяць."
              )
            )}
          </p>
        </div>
      </div>

      <div class="financeTypeSwitch">
        <button
          class="active"
          type="button"
          data-adjust-type="bonus"
        >
          ${escapeHtml(
            getTeamInterfaceText(
              "✅ Бонус"
            )
          )}
        </button>

        <button
          type="button"
          data-adjust-type="penalty"
        >
          ${escapeHtml(
            getTeamInterfaceText(
              "⚠️ Штраф"
            )
          )}
        </button>
      </div>

      <label class="financeAdjustField">
        <span>
          ${escapeHtml(
            getTeamInterfaceText(
              "Сума, грн"
            )
          )}
        </span>

        <input
          id="financeAdjustAmount"
          type="number"
          min="1"
          step="1"
          placeholder="${escapeHtml(
            getTeamInterfaceText(
              "Наприклад: 500"
            )
          )}"
        >
      </label>

      <label class="financeAdjustField">
        <span>
          ${escapeHtml(
            getTeamInterfaceText(
              "Причина"
            )
          )}
        </span>

        <input
          id="financeAdjustReason"
          type="text"
          placeholder="${escapeHtml(
            getTeamInterfaceText(
              "Наприклад: запізнення або бонус за результат"
            )
          )}"
        >
      </label>

      <div class="financeQuickReasons">
        <span>
          ${escapeHtml(
            getTeamInterfaceText(
              "Швидкі причини"
            )
          )}
        </span>

        <div>
          ${
            [
              "Запізнення",
              "Пропуск зміни",
              "Бонус за результат",
              "Додаткова зміна",
            ]
              .map(
                (reason) => {
                  const translated =
                    getTeamInterfaceText(
                      reason
                    );

                  return `
                    <button
                      type="button"
                      data-reason="${escapeHtml(
                        translated
                      )}"
                    >
                      ${escapeHtml(
                        translated
                      )}
                    </button>
                  `;
                }
              )
              .join("")
          }
        </div>
      </div>

      <div class="financeAdjustActions">
        <button
          class="teamGhostBtn"
          id="btnCancelAdjust"
          type="button"
        >
          ${escapeHtml(
            getTeamInterfaceText(
              "Скасувати"
            )
          )}
        </button>

        <button
          class="teamPrimaryBtn"
          id="btnSaveAdjust"
          type="button"
        >
          ${escapeHtml(
            getTeamInterfaceText(
              "Додати"
            )
          )}
        </button>
      </div>
    </div>
  `;

  document.body.appendChild(
    modal
  );

  installTeamLocalization(
    modal
  );

  let selectedType =
    "bonus";

  const close = () => {
    modal.remove();
  };

  modal
    .querySelector(
      ".financeAdjustClose"
    )
    ?.addEventListener(
      "click",
      close
    );

  modal
    .querySelector(
      "#btnCancelAdjust"
    )
    ?.addEventListener(
      "click",
      close
    );

  modal
    .querySelectorAll(
      "[data-adjust-type]"
    )
    .forEach(
      (button) => {
        button.addEventListener(
          "click",
          () => {
            selectedType =
              button.dataset
                .adjustType ||
              "bonus";

            modal
              .querySelectorAll(
                "[data-adjust-type]"
              )
              .forEach(
                (item) => {
                  item.classList.remove(
                    "active"
                  );
                }
              );

            button.classList.add(
              "active"
            );
          }
        );
      }
    );

  modal
    .querySelectorAll(
      "[data-reason]"
    )
    .forEach(
      (button) => {
        button.addEventListener(
          "click",
          () => {
            const reasonInput =
              modal.querySelector(
                "#financeAdjustReason"
              );

            if (reasonInput) {
              reasonInput.value =
                button.dataset
                  .reason ||
                "";
            }
          }
        );
      }
    );

  modal
    .querySelector(
      "#btnSaveAdjust"
    )
    ?.addEventListener(
      "click",
      async () => {
        const amount =
          Number(
            modal.querySelector(
              "#financeAdjustAmount"
            )?.value ||
            0
          );

        const reason =
          modal.querySelector(
            "#financeAdjustReason"
          )?.value?.trim() ||
          "";

        if (
          !amount ||
          amount <= 0
        ) {
          alert(
            getTeamInterfaceText(
              "Вкажіть суму."
            )
          );

          return;
        }

        const saveButton =
          modal.querySelector(
            "#btnSaveAdjust"
          );

        if (saveButton) {
          saveButton.disabled =
            true;
        }

        try {
          const result =
            await createStaffAdjustmentApi(
              state.doc.id,
              {
                type:
                  selectedType,

                amount,
                reason,
              }
            );

          if (!result.ok) {
            throw new Error(
              result.error ||
              getTeamInterfaceText(
                "Не вдалося додати запис"
              )
            );
          }

          close();

          await renderTeamFinanceTab(
            root,
            state
          );
        } catch (error) {
          console.error(
            error
          );

          alert(
            error?.message ||
            getTeamInterfaceText(
              "Не вдалося додати запис"
            )
          );

          if (saveButton) {
            saveButton.disabled =
              false;
          }
        }
      }
    );

  modal
    .querySelector(
      "#financeAdjustAmount"
    )
    ?.focus();
}
