function getTeamCareerLevelSummaryText(
  level,
  xp
) {
  const levelText =
    getTeamLevelText(
      level
    );

  const xpText =
    Number(xp || 0)
      .toLocaleString(
        getCalendarLocale()
      );

  return (
    `${levelText} · ` +
    `${xpText} XP`
  );
}


function getTeamClinicRankText(
  rank,
  total
) {
  if (!rank) {
    return "—";
  }

  const rankText =
    Number(rank)
      .toLocaleString(
        getCalendarLocale()
      );

  const totalText =
    Number(total || 0)
      .toLocaleString(
        getCalendarLocale()
      );

  const language =
    getInterfaceLanguage();

  if (language === "en") {
    return (
      `#${rankText} of ` +
      `${totalText}`
    );
  }

  if (language === "de") {
    return (
      `#${rankText} von ` +
      `${totalText}`
    );
  }

  if (language === "pl") {
    return (
      `#${rankText} z ` +
      `${totalText}`
    );
  }

  return (
    `#${rankText} із ` +
    `${totalText}`
  );
}


function getTeamSeasonDescription(
  seasonLabel
) {
  const language =
    getInterfaceLanguage();

  if (language === "en") {
    return (
      `Season ${seasonLabel} · ` +
      "updated every 3 months"
    );
  }

  if (language === "de") {
    return (
      `Saison ${seasonLabel} · ` +
      "Aktualisierung alle 3 Monate"
    );
  }

  if (language === "pl") {
    return (
      `Sezon ${seasonLabel} · ` +
      "aktualizacja co 3 miesiące"
    );
  }

  return (
    `Сезон ${seasonLabel} · ` +
    "оновлення кожні 3 місяці"
  );
}


