function openStaffPasswordResetModal(
  root,
  profileState,
  staffId
) {
  document
    .querySelector(
      ".staffPasswordResetOverlay"
    )
    ?.remove();

  const modal =
    document.createElement(
      "div"
    );

  modal.className =
    "financeAdjustModalOverlay staffPasswordResetOverlay";

  modal.innerHTML = `
    <div class="financeAdjustModal">
      <button
        class="financeAdjustClose"
        type="button"
        aria-label="${escapeHtml(
          getTeamInterfaceText(
            "Закрити"
          )
        )}"
      >
        ×
      </button>

      <div class="financeAdjustHead">
        <div class="financeAdjustIcon">
          🔑
        </div>

        <div>
          <h2>
            ${escapeHtml(
              getTeamInterfaceText(
                "Встановити тимчасовий пароль"
              )
            )}
          </h2>

          <p>
            ${escapeHtml(
              getTeamInterfaceText(
                "Введіть новий пароль для співробітника. Після входу він повинен буде створити постійний пароль."
              )
            )}
          </p>
        </div>
      </div>

      <label class="financeAdjustField">
        <span>
          ${escapeHtml(
            getTeamInterfaceText(
              "Новий тимчасовий пароль"
            )
          )}
        </span>

        <input
          id="staffTemporaryPassword"
          type="password"
          minlength="8"
          autocomplete="new-password"
          placeholder="${escapeHtml(
            getTeamInterfaceText(
              "Мінімум 8 символів"
            )
          )}"
        >
      </label>

      <div class="financeAdjustActions">
        <button
          class="teamGhostBtn"
          id="btnCancelPasswordReset"
          type="button"
        >
          ${escapeHtml(
            getTeamInterfaceText(
              "Скасувати"
            )
          )}
        </button>

        <button
          class="teamPrimaryBtn"
          id="btnSavePasswordReset"
          type="button"
        >
          ${escapeHtml(
            getTeamInterfaceText(
              "Встановити пароль"
            )
          )}
        </button>
      </div>
    </div>
  `;

  document.body.appendChild(
    modal
  );

  installTeamLocalization(
    modal
  );

  const input =
    modal.querySelector(
      "#staffTemporaryPassword"
    );

  const close = () => {
    modal.remove();
  };

  modal
    .querySelector(
      ".financeAdjustClose"
    )
    ?.addEventListener(
      "click",
      close
    );

  modal
    .querySelector(
      "#btnCancelPasswordReset"
    )
    ?.addEventListener(
      "click",
      close
    );

  modal
    .querySelector(
      "#btnSavePasswordReset"
    )
    ?.addEventListener(
      "click",
      async () => {
        const password =
          String(
            input?.value ||
            ""
          );

        if (
          password.trim()
            .length < 8
        ) {
          openDeleteModal(
            getTeamInterfaceText(
              "Пароль повинен містити мінімум 8 символів."
            ),
            null,
            "info"
          );

          return;
        }

        const saveButton =
          modal.querySelector(
            "#btnSavePasswordReset"
          );

        if (saveButton) {
          saveButton.disabled =
            true;
        }

        const result =
          await resetStaffPasswordApi(
            staffId,
            password
          );

        if (!result.ok) {
          openDeleteModal(
            getTeamInterfaceText(
              result.error ||
              "Не вдалося скинути пароль."
            ),
            null,
            "info"
          );

          if (saveButton) {
            saveButton.disabled =
              false;
          }

          return;
        }

        close();

        await renderTeamSettingsTab(
          root,
          profileState
        );

        openDeleteModal(
          getTeamInterfaceText(
            "Тимчасовий пароль встановлено. При наступному вході співробітник повинен створити новий пароль."
          ),
          null,
          "success"
        );
      }
    );

  input?.focus();
}


function bindStaffAccountPanel(
  root,
  profileState,
  accountResult
) {
  const staffId =
    profileState.doc?.id;

  if (!staffId) return;

  const account =
    accountResult?.data ||
    null;

  root
    .querySelector(
      "#btnCreateStaffAccount"
    )
    ?.addEventListener(
      "click",
      async () => {
        const username =
          String(
            root.querySelector(
              "#staffAccountUsername"
            )?.value ||
            ""
          ).trim();

        const role =
          String(
            root.querySelector(
              "#staffAccountRole"
            )?.value ||
            "vet"
          );

        const password =
          String(
            root.querySelector(
              "#staffAccountPassword"
            )?.value ||
            ""
          );

        if (
          username.length < 3
        ) {
          openDeleteModal(
            getTeamInterfaceText(
              "Логін повинен містити мінімум 3 символи."
            ),
            null,
            "info"
          );

          return;
        }

        if (
          password.length < 8
        ) {
          openDeleteModal(
            getTeamInterfaceText(
              "Тимчасовий пароль повинен містити мінімум 8 символів."
            ),
            null,
            "info"
          );

          return;
        }

        const result =
          await createStaffAccountApi(
            staffId,
            {
              username,
              role,
              password,
            }
          );

        if (!result.ok) {
          openDeleteModal(
            getTeamInterfaceText(
              result.error ||
              "Не вдалося створити акаунт."
            ),
            null,
            "info"
          );

          return;
        }

        await renderTeamSettingsTab(
          root,
          profileState
        );

        openDeleteModal(
          getTeamInterfaceText(
            "Передайте співробітнику логін і тимчасовий пароль."
          ),
          null,
          "success"
        );
      }
    );

  root
    .querySelector(
      "#btnSaveStaffAccount"
    )
    ?.addEventListener(
      "click",
      async () => {
        const username =
          String(
            root.querySelector(
              "#staffAccountUsername"
            )?.value ||
            ""
          ).trim();

        const role =
          String(
            root.querySelector(
              "#staffAccountRole"
            )?.value ||
            "vet"
          );

        if (
          username.length < 3
        ) {
          openDeleteModal(
            getTeamInterfaceText(
              "Логін повинен містити мінімум 3 символи."
            ),
            null,
            "info"
          );

          return;
        }

        const result =
          await updateStaffAccountApi(
            staffId,
            {
              username,
              role,
            }
          );

        if (!result.ok) {
          openDeleteModal(
            getTeamInterfaceText(
              result.error ||
              "Не вдалося зберегти зміни."
            ),
            null,
            "info"
          );

          return;
        }

        await renderTeamSettingsTab(
          root,
          profileState
        );

        openDeleteModal(
          getTeamInterfaceText(
            "Налаштування доступу успішно збережено."
          ),
          null,
          "success"
        );
      }
    );

  root
    .querySelector(
      "#btnToggleStaffAccount"
    )
    ?.addEventListener(
      "click",
      () => {
        if (!account) return;

        const nextActive =
          !account.is_active;

        openDeleteModal(
          getTeamInterfaceText(
            nextActive
              ? "Відновити цьому співробітнику доступ до CRM?"
              : "Співробітник більше не зможе увійти до CRM."
          ),

          async () => {
            const result =
              await updateStaffAccountApi(
                staffId,
                {
                  is_active:
                    nextActive,
                }
              );

            if (!result.ok) {
              openDeleteModal(
                getTeamInterfaceText(
                  result.error ||
                  "Не вдалося змінити доступ."
                ),
                null,
                "info"
              );

              return;
            }

            await renderTeamSettingsTab(
              root,
              profileState
            );

            openDeleteModal(
              getTeamInterfaceText(
                nextActive
                  ? "Доступ до CRM увімкнено."
                  : "Доступ до CRM вимкнено."
              ),
              null,
              "success"
            );
          },

          nextActive
            ? "activate"
            : "deactivate"
        );
      }
    );

  root
    .querySelector(
      "#btnResetStaffPassword"
    )
    ?.addEventListener(
      "click",
      () => {
        openStaffPasswordResetModal(
          root,
          profileState,
          staffId
        );
      }
    );
}
