function getStockGroupByCategory(
  category
) {
  const value =
    String(category || "").trim();

  return (
    STOCK_CATEGORY_GROUPS.find(
      (group) =>
        group.categories.includes(
          value
        )
    ) ||
    STOCK_CATEGORY_GROUPS.find(
      (group) =>
        group.id === "other"
    )
  );
}


function getStockGroupLabel(
  item
) {
  const group =
    STOCK_CATEGORY_GROUPS.find(
      (entry) =>
        entry.id ===
        String(
          item?.group ||
          item?.group_id ||
          ""
        )
    ) ||
    getStockGroupByCategory(
      item?.category
    );

  return group?.name || "Інше";
}

