function getStockStatus(item) {
  const quantity =
    Math.max(
      0,
      Number(
        item?.qty || 0
      )
    );

  const minimum =
    Math.max(
      0,
      Number(
        item?.min_qty ??
        item?.minimum_qty ??
        5
      )
    );

  if (quantity <= 0) {
    return {
      key: "empty",

      label:
        getStockInterfaceText(
          "Немає в наявності"
        ),

      shortLabel:
        getStockInterfaceText(
          "Немає"
        ),

      icon: "○",
    };
  }

  if (quantity <= minimum) {
    return {
      key: "critical",

      label:
        getStockInterfaceText(
          "Критичний залишок"
        ),

      shortLabel:
        getStockInterfaceText(
          "Критично"
        ),

      icon: "!",
    };
  }

  if (
    quantity <=
    minimum * 2
  ) {
    return {
      key: "low",

      label:
        getStockInterfaceText(
          "Закінчується"
        ),

      shortLabel:
        getStockInterfaceText(
          "Мало"
        ),

      icon: "↓",
    };
  }

  return {
    key: "good",

    label:
      getStockInterfaceText(
        "Достатній запас"
      ),

    shortLabel:
      getStockInterfaceText(
        "В наявності"
      ),

    icon: "✓",
  };
}


function parseStockDate(value) {
  const match =
    String(value || "")
      .match(
        /^(\d{4})-(\d{2})-(\d{2})$/
      );

  if (!match) return null;

  const parsed =
    new Date(
      Number(match[1]),
      Number(match[2]) - 1,
      Number(match[3])
    );

  return Number.isNaN(
    parsed.getTime()
  )
    ? null
    : parsed;
}


function formatStockDate(value) {
  const parsed =
    parseStockDate(value);

  return parsed
    ? parsed.toLocaleDateString(
        getCalendarLocale()
      )
    : "";
}


function getStockExpiryMeta(
  item,
  now = new Date()
) {
  const expiryDate =
    parseStockDate(
      item?.expiry_date
    );

  if (!expiryDate) {
    return {
      key: "none",
      days: null,
      label: "",
    };
  }

  const today =
    new Date(
      now.getFullYear(),
      now.getMonth(),
      now.getDate()
    );

  const days =
    Math.ceil(
      (
        expiryDate.getTime() -
        today.getTime()
      ) /
      86400000
    );

  if (days < 0) {
    return {
      key: "expired",
      days,

      label:
        getStockInterfaceText(
          "Термін минув"
        ),
    };
  }

  if (days <= 30) {
    return {
      key: "critical",
      days,

      label:
        days === 0
          ? getStockInterfaceText(
              "Останній день"
            )
          : getStockDynamicMessage(
              "expiryDays",
              {
                days,
              }
            ),
    };
  }

  if (days <= 90) {
    return {
      key: "warning",
      days,

      label:
        getStockDynamicMessage(
          "expiryDays",
          {
            days,
          }
        ),
    };
  }

  return {
    key: "good",
    days,

    label:
      getStockDynamicMessage(
        "validUntil",
        {
          formattedDate:
            formatStockDate(
              item.expiry_date
            ),
        }
      ),
  };
}


function buildStockPugInsights(
  items
) {
  const signals = [];

  const attentionItemIds =
    new Set();

  let expiryRiskCount = 0;
  let forecastRiskCount = 0;
  let valueAtRisk = 0;

  (items || [])
    .filter(
      (item) =>
        item?.active !== false
    )
    .forEach(
      (item) => {
        const itemId =
          String(
            item.id || ""
          );

        const quantity =
          Math.max(
            0,
            Number(
              item.qty || 0
            )
          );

        const minimum =
          Math.max(
            0,
            Number(
              item.min_qty || 0
            )
          );

        const cost =
          Math.max(
            0,
            Number(
              item.cost || 0
            )
          );

        const expiry =
          getStockExpiryMeta(
            item
          );

        const estimatedDaysLeft =
          item.estimated_days_left ==
          null
            ? null
            : Math.max(
                0,
                Number(
                  item
                    .estimated_days_left
                )
              );

        if (
          expiry.key ===
            "expired" ||
          expiry.key ===
            "critical"
        ) {
          expiryRiskCount += 1;

          attentionItemIds.add(
            itemId
          );

          valueAtRisk +=
            quantity * cost;

          signals.push({
            priority:
              expiry.key ===
              "expired"
                ? 0
                : 1,

            tone:
              expiry.key ===
              "expired"
                ? "danger"
                : "warning",

            icon:
              expiry.key ===
              "expired"
                ? "!"
                : "◷",

            itemId,

            title:
              getStockDynamicMessage(
                expiry.key ===
                  "expired"
                  ? "expiredTitle"
                  : "expiryTitle",
                {
                  name:
                    item.name,

                  expiryLabel:
                    expiry.label,
                }
              ),

            description:
              quantity > 0
                ? getStockDynamicMessage(
                    "atRisk",
                    {
                      quantity,
                      unit:
                        item.unit,
                    }
                  )
                : getStockDynamicMessage(
                    "checkBeforeUse"
                  ),
          });
        }

        if (quantity <= 0) {
          attentionItemIds.add(
            itemId
          );

          signals.push({
            priority: 0,
            tone: "danger",
            icon: "0",
            itemId,

            title:
              getStockDynamicMessage(
                "emptyTitle",
                {
                  name:
                    item.name,
                }
              ),

            description:
              minimum > 0
                ? getStockDynamicMessage(
                    "recommendedMinimum",
                    {
                      minimum,
                      unit:
                        item.unit,
                    }
                  )
                : getStockDynamicMessage(
                    "unavailable"
                  ),
          });
        } else if (
          quantity <= minimum
        ) {
          attentionItemIds.add(
            itemId
          );

          signals.push({
            priority: 1,
            tone: "warning",
            icon: "↓",
            itemId,

            title:
              getStockDynamicMessage(
                "criticalTitle",
                {
                  name:
                    item.name,
                }
              ),

            description:
              getStockDynamicMessage(
                "criticalDescription",
                {
                  quantity,
                  minimum,
                  unit:
                    item.unit,
                }
              ),
          });
        }

        if (
          estimatedDaysLeft !=
            null &&
          estimatedDaysLeft > 0 &&
          estimatedDaysLeft <=
            14 &&
          quantity > minimum
        ) {
          forecastRiskCount += 1;

          attentionItemIds.add(
            itemId
          );

          signals.push({
            priority:
              estimatedDaysLeft <=
              7
                ? 1
                : 2,

            tone:
              estimatedDaysLeft <=
              7
                ? "warning"
                : "info",

            icon: "↘",
            itemId,

            title:
              getStockDynamicMessage(
                "forecastTitle",
                {
                  name:
                    item.name,

                  days:
                    estimatedDaysLeft,
                }
              ),

            description:
              getStockDynamicMessage(
                "forecastDescription"
              ),
          });
        }
      }
    );

  signals.sort(
    (
      left,
      right
    ) =>
      left.priority -
      right.priority
  );

  return {
    signals,

    attentionCount:
      attentionItemIds.size,

    expiryRiskCount,
    forecastRiskCount,
    valueAtRisk,
  };
}


function normalizeStockItem(item) {
  const category =
    String(
      item?.category ||
      item?.cat ||
      "Інше"
    );

  const group =
    getStockGroupByCategory(
      category
    );

  return {
    ...item,

    id:
      String(
        item?.id ||
        `stk_${Date.now()
          .toString(36)}`
      ),

    name:
      String(
        item?.name ||
        "Позиція"
      ),

    group:
      String(
        item?.group ||
        item?.group_id ||
        group?.id ||
        "other"
      ),

    category,

    form:
      String(
        item?.form ||
        item?.dosage_form ||
        "Інше"
      ),

    route:
      String(
        item?.route ||
        item?.administration_route ||
        "Не застосовується"
      ),

    species:
      String(
        item?.species ||
        item?.target_species ||
        "Універсальний"
      ),

    unit:
      String(
        item?.unit ||
        "шт"
      ),

    qty:
      Math.max(
        0,
        Number(item?.qty || 0)
      ),

    price:
      Math.max(
        0,
        Number(
          item?.price ??
          item?.sell_price ??
          0
        )
      ),

    cost:
      Math.max(
        0,
        Number(
          item?.cost ??
          item?.purchase_price ??
          0
        )
      ),

    min_qty:
      Math.max(
        0,
        Number(
          item?.min_qty ??
          item?.minimum_qty ??
          5
        )
      ),

    expiry_date:
      String(
        item?.expiry_date || ""
      ).trim() || null,

    batch_number:
      String(
        item?.batch_number || ""
      ).trim() || null,

    usage_30d:
      Math.max(
        0,
        Number(
          item?.usage_30d || 0
        )
      ),

    avg_daily_usage:
      Math.max(
        0,
        Number(
          item?.avg_daily_usage || 0
        )
      ),

    estimated_days_left:
      item?.estimated_days_left ==
      null
        ? null
        : Math.max(
            0,
            Number(
              item.estimated_days_left
            )
          ),

    active:
      item?.active !== false,
  };
}


function saveNormalizedStock(items) {
  const normalized =
    (items || []).map(
      normalizeStockItem
    );

  saveStock(normalized);

  return normalized;
}

