function getFinanceClientWord(
  count
) {
  const value = Math.max(
    0,
    Number(count || 0)
  );

  const language =
    getInterfaceLanguage();

  if (language === "en") {
    return value === 1
      ? "client"
      : "clients";
  }

  if (language === "de") {
    return value === 1
      ? "Kunde"
      : "Kunden";
  }

  if (language === "pl") {
    const lastDigit = value % 10;
    const lastTwoDigits = value % 100;

    if (value === 1) {
      return "klient";
    }

    if (
      lastDigit >= 2 &&
      lastDigit <= 4 &&
      !(
        lastTwoDigits >= 12 &&
        lastTwoDigits <= 14
      )
    ) {
      return "klientów";
    }

    return "klientów";
  }

  const lastDigit = value % 10;
  const lastTwoDigits = value % 100;

  if (
    lastDigit === 1 &&
    lastTwoDigits !== 11
  ) {
    return "клієнт";
  }

  if (
    lastDigit >= 2 &&
    lastDigit <= 4 &&
    !(
      lastTwoDigits >= 12 &&
      lastTwoDigits <= 14
    )
  ) {
    return "клієнти";
  }

  return "клієнтів";
}


