function getFinancePatientWord(
  count
) {
  const value = Math.max(
    0,
    Number(count || 0)
  );

  const language =
    getInterfaceLanguage();

  if (language === "en") {
    return value === 1
      ? "patient"
      : "patients";
  }

  if (language === "de") {
    return value === 1
      ? "Patient"
      : "Patienten";
  }

  if (language === "pl") {
    const lastDigit = value % 10;
    const lastTwoDigits = value % 100;

    if (value === 1) {
      return "pacjent";
    }

    if (
      lastDigit >= 2 &&
      lastDigit <= 4 &&
      !(
        lastTwoDigits >= 12 &&
        lastTwoDigits <= 14
      )
    ) {
      return "pacjenci";
    }

    return "pacjentów";
  }

  const lastDigit = value % 10;
  const lastTwoDigits = value % 100;

  if (
    lastDigit === 1 &&
    lastTwoDigits !== 11
  ) {
    return "пацієнт";
  }

  if (
    lastDigit >= 2 &&
    lastDigit <= 4 &&
    !(
      lastTwoDigits >= 12 &&
      lastTwoDigits <= 14
    )
  ) {
    return "пацієнти";
  }

  return "пацієнтів";
}


function getFinanceClientPatientCountText(
  count
) {
  const value = Math.max(
    0,
    Number(count || 0)
  );

  return (
    `${value} ` +
    getFinancePatientWord(
      value
    )
  );
}
