function localizeFinanceElement(
  root
) {
  if (!root) return;

  const walker =
    document.createTreeWalker(
      root,
      NodeFilter.SHOW_TEXT
    );

  const textNodes = [];

  while (walker.nextNode()) {
    textNodes.push(
      walker.currentNode
    );
  }

  textNodes.forEach(
    (node) => {
      if (
        node.parentElement
          ?.closest?.(
            "[data-finance-content]"
          )
      ) {
        return;
      }

      const currentText =
        node.nodeValue || "";

      const normalized =
        normalizeFinanceInterfaceText(
          currentText
        );

      if (!normalized) return;

      const translated =
        getFinanceRenderedText(
          normalized
        );

      if (
        translated === normalized
      ) {
        return;
      }

      const leadingSpace =
        currentText.match(
          /^\s*/
        )?.[0] || "";

      const trailingSpace =
        currentText.match(
          /\s*$/
        )?.[0] || "";

      node.nodeValue =
        leadingSpace +
        translated +
        trailingSpace;
    }
  );

  const elements = [
    root,
    ...root.querySelectorAll("*"),
  ];

  elements.forEach(
    (element) => {
      if (
        element?.closest?.(
          "[data-finance-content]"
        )
      ) {
        return;
      }

      [
        "placeholder",
        "title",
        "aria-label",
      ].forEach(
        (attribute) => {
          if (
            !element?.hasAttribute?.(
              attribute
            )
          ) {
            return;
          }

          const currentValue =
            element.getAttribute(
              attribute
            ) || "";

          const translatedValue =
            getFinanceRenderedText(
              currentValue
            );

          if (
            translatedValue !==
            currentValue
          ) {
            element.setAttribute(
              attribute,
              translatedValue
            );
          }
        }
      );
    }
  );
}
function installFinanceLocalization(
  root
) {
  if (!root) return;

  root
    ._financeLocalizationObserver
    ?.disconnect();

  localizeFinanceElement(
    root
  );

  const observer =
    new MutationObserver(
      () => {
        localizeFinanceElement(
          root
        );
      }
    );

  observer.observe(
    root,
    {
      childList: true,
      subtree: true,
    }
  );

  root._financeLocalizationObserver =
    observer;
}


