function getFinancePurchasePaymentMeta(
  status
) {
  const statuses = {
    unpaid: {
      label: "Не оплачено",
      className: "is-unpaid",
    },

    partial: {
      label: "Оплачено частково",
      className: "is-partial",
    },

    paid: {
      label: "Оплачено",
      className: "is-paid",
    },
  };

  return (
    statuses[
      String(
        status || ""
      ).toLowerCase()
    ] ||
    statuses.unpaid
  );
}

function formatFinancePurchaseDate(
  value
) {
  const cleanDate =
    String(
      value ||
      ""
    ).slice(
      0,
      10
    );

  if (
    !cleanDate
  ) {
    return "—";
  }

  return formatCalendarDate(
    cleanDate,
    {
      day:
        "2-digit",

      month:
        "2-digit",

      year:
        "numeric",
    }
  );
}
