function getFinanceOwnerCompletedText(
  count
) {
  const value = Math.max(
    0,
    Number(count || 0)
  );

  const language =
    getInterfaceLanguage();

  if (language === "en") {
    return (
      `${value} completed`
    );
  }

  if (language === "de") {
    return (
      `${value} abgeschlossen`
    );
  }

  if (language === "pl") {
    return (
      `${value} wykonano`
    );
  }

  return `${value} виконано`;
}


function getFinanceOwnerAttentionText(
  value
) {
  const source =
    normalizeFinanceInterfaceText(
      value
    );

  const language =
    getInterfaceLanguage();

  const lowStockMatch =
    source.match(
      /^(\d+)\s+позицій складу нижче мінімуму$/i
    );

  if (lowStockMatch) {
    const count =
      Number(lowStockMatch[1]);

    if (language === "en") {
      return (
        `${count} inventory ` +
        `${count === 1 ? "item is" : "items are"} ` +
        "below minimum"
      );
    }

    if (language === "de") {
      return (
        `${count} ` +
        `${count === 1 ? "Lagerposition liegt" : "Lagerpositionen liegen"} ` +
        "unter dem Mindestbestand"
      );
    }

    if (language === "pl") {
      return (
        `${count} pozycji magazynowych ` +
        "poniżej minimum"
      );
    }

    return source;
  }

  const overdueMatch =
    source.match(
      /^(\d+)\s+прострочених завдань стаціонару$/i
    );

  if (overdueMatch) {
    const count =
      Number(overdueMatch[1]);

    if (language === "en") {
      return (
        `${count} overdue hospital ` +
        `${count === 1 ? "task" : "tasks"}`
      );
    }

    if (language === "de") {
      return (
        `${count} überfällige ` +
        `${count === 1 ? "Stationsaufgabe" : "Stationsaufgaben"}`
      );
    }

    if (language === "pl") {
      return (
        `${count} zaległych zadań ` +
        "szpitalnych"
      );
    }

    return source;
  }

  const debtMatch =
    source.match(
      /^Заборгованість клієнтів:\s*([0-9.,-]+)\s*грн$/i
    );

  if (debtMatch) {
    const amount =
      Number(
        String(debtMatch[1])
          .replace(",", ".")
      ) || 0;

    const formatted =
      formatVisitFinanceMoney(
        amount
      );

    if (language === "en") {
      return (
        `Outstanding client balance: ${formatted}`
      );
    }

    if (language === "de") {
      return (
        `Offene Kundenforderungen: ${formatted}`
      );
    }

    if (language === "pl") {
      return (
        `Zadłużenie klientów: ${formatted}`
      );
    }

    return source;
  }

  if (
    source ===
    "Критичних відхилень не виявлено"
  ) {
    if (language === "en") {
      return (
        "No critical issues detected"
      );
    }

    if (language === "de") {
      return (
        "Keine kritischen Abweichungen festgestellt"
      );
    }

    if (language === "pl") {
      return (
        "Nie wykryto krytycznych odchyleń"
      );
    }

    return source;
  }

  return getFinanceInterfaceText(
    source
  );
}


function ownerReportDelta(
  value,
  suffix = ""
) {
  const number =
    Number(value || 0);

  const absoluteNumber =
    Math.abs(number);

  const className =
    number > 0
      ? "is-positive"
      : number < 0
        ? "is-negative"
        : "is-neutral";

  const formattedValue =
    String(suffix)
      .trim() === "грн"
      ? formatVisitFinanceMoney(
          absoluteNumber
        )
      : (
          absoluteNumber.toLocaleString(
            getCalendarLocale()
          ) +
          suffix
        );

  const signedValue =
    number > 0
      ? `+${formattedValue}`
      : number < 0
        ? `−${formattedValue}`
        : formattedValue;

  const language =
    getInterfaceLanguage();

  const comparisonText =
    language === "en"
      ? "vs yesterday"
      : language === "de"
        ? "zum Vortag"
        : language === "pl"
          ? "względem wczoraj"
          : "до вчора";

  return `
    <span
      class="
        ownerReportDelta
        ${className}
      "
    >
      ${signedValue}
      ${comparisonText}
    </span>
  `;
}


