function normalizeStockInterfaceText(
  value
) {
  return String(value || "")
    .replace(/\s+/g, " ")
    .trim();
}


function getStockInterfaceText(
  sourceText
) {
  const language =
    getInterfaceLanguage();

  const normalizedSource =
    normalizeStockInterfaceText(
      sourceText
    );

  const entry =
    Object.entries(
      STOCK_INTERFACE_TEXT
    ).find(
      ([ukrainian, translations]) =>
        [
          ukrainian,
          ...Object.values(
            translations
          ),
        ].some(
          (value) =>
            normalizeStockInterfaceText(
              value
            ) ===
            normalizedSource
        )
    );

  if (!entry) {
    return String(
      sourceText || ""
    );
  }

  const [
    ukrainian,
    translations,
  ] = entry;

  return language === "uk"
    ? ukrainian
    : (
        translations[language] ||
        ukrainian
      );
}


function getLocalizedStockText(
  value
) {
  return getStockInterfaceText(
    String(value || "")
  );
}


function getStockCountText(
  count
) {
  const value =
    Math.max(
      0,
      Number(count || 0)
    );

  const language =
    getInterfaceLanguage();

  if (language === "en") {
    return value === 1
      ? "item"
      : "items";
  }

  if (language === "de") {
    return "Artikel";
  }

  if (language === "pl") {
    const lastDigit =
      value % 10;

    const lastTwoDigits =
      value % 100;

    if (value === 1) {
      return "pozycja";
    }

    if (
      lastDigit >= 2 &&
      lastDigit <= 4 &&
      !(
        lastTwoDigits >= 12 &&
        lastTwoDigits <= 14
      )
    ) {
      return "pozycje";
    }

    return "pozycji";
  }

  const lastDigit =
    value % 10;

  const lastTwoDigits =
    value % 100;

  if (
    lastDigit === 1 &&
    lastTwoDigits !== 11
  ) {
    return "позиція";
  }

  if (
    lastDigit >= 2 &&
    lastDigit <= 4 &&
    !(
      lastTwoDigits >= 12 &&
      lastTwoDigits <= 14
    )
  ) {
    return "позиції";
  }

  return "позицій";
}


function getStockAttentionText(
  count
) {
  const value =
    Math.max(
      0,
      Number(count || 0)
    );

  const language =
    getInterfaceLanguage();

  if (language === "en") {
    return `${value} ${
      value === 1
        ? "item requires"
        : "items require"
    } attention`;
  }

  if (language === "de") {
    return `${value} ${
      value === 1
        ? "Artikel benötigt"
        : "Artikel benötigen"
    } Aufmerksamkeit`;
  }

  if (language === "pl") {
    return `${value} ${getStockCountText(
      value
    )} ${
      value === 1
        ? "wymaga"
        : "wymagają"
    } uwagi`;
  }

  return `${value} ${getStockCountText(
    value
  )} ${
    value === 1
      ? "потребує"
      : "потребують"
  } уваги`;
}


function getStockCompactForecastText(
  days
) {
  const value =
    Math.max(
      1,
      Math.round(
        Number(days || 1)
      )
    );

  const language =
    getInterfaceLanguage();

  if (language === "en") {
    return `Forecast ≈ ${value} ${
      value === 1
        ? "day"
        : "days"
    }`;
  }

  if (language === "de") {
    return `Prognose ≈ ${value} ${
      value === 1
        ? "Tag"
        : "Tage"
    }`;
  }

  if (language === "pl") {
    return `Prognoza ≈ ${value} ${
      value === 1
        ? "dzień"
        : "dni"
    }`;
  }

  return `Прогноз ≈ ${value} дн.`;
}


function getStockRenderedText(
  sourceText
) {
  const source =
    normalizeStockInterfaceText(
      sourceText
    );

  if (!source) return "";

  const exactTranslation =
    getStockInterfaceText(
      source
    );

  if (
    exactTranslation !== source
  ) {
    return exactTranslation;
  }

  const attentionMatch =
    source.match(
      /^(\d+)\s+позиці(?:я|ї|й)\s+потребу(?:є|ють)\s+уваги$/i
    );

  if (attentionMatch) {
    return getStockAttentionText(
      Number(attentionMatch[1])
    );
  }

  const countMatch =
    source.match(
      /^(\d+)\s+позиці(?:я|ї|й)$/i
    );

  if (countMatch) {
    const count =
      Number(countMatch[1]);

    return `${count} ${getStockCountText(
      count
    )}`;
  }

  const batchMatch =
    source.match(
      /^Партія\s+(.+)$/i
    );

  if (batchMatch) {
    return `${getStockInterfaceText(
      "Партія"
    )} ${batchMatch[1]}`;
  }

  const forecastMatch =
    source.match(
      /^Прогноз\s*≈\s*(\d+)\s*дн\.?$/i
    );

  if (forecastMatch) {
    return getStockCompactForecastText(
      Number(forecastMatch[1])
    );
  }

  return source;
}


function showStockAlert(
  message
) {
  alert(
    getStockInterfaceText(
      message
    )
  );
}


function localizeStockElement(
  root
) {
  if (!root) return;

  const walker =
    document.createTreeWalker(
      root,
      NodeFilter.SHOW_TEXT
    );

  const textNodes = [];

  while (walker.nextNode()) {
    textNodes.push(
      walker.currentNode
    );
  }

  textNodes.forEach(
    (node) => {
      const parentElement =
        node.parentElement;

      if (
        parentElement?.closest?.(
          [
            ".stockPremiumCard h3",
            ".stockPugSignalCopy strong",
            "#stockEditorPreviewName",
            ".stockAdjustmentItem strong",
            ".stockDeleteItem strong",
            "[data-stock-content]",
          ].join(",")
        )
      ) {
        return;
      }

      const currentText =
        node.nodeValue || "";

      const normalized =
        normalizeStockInterfaceText(
          currentText
        );

      if (!normalized) return;

      const translated =
        getStockRenderedText(
          normalized
        );

      if (
        translated === normalized
      ) {
        return;
      }

      const leadingSpace =
        currentText.match(
          /^\s*/
        )?.[0] || "";

      const trailingSpace =
        currentText.match(
          /\s*$/
        )?.[0] || "";

      node.nodeValue =
        leadingSpace +
        translated +
        trailingSpace;
    }
  );

  const elements = [
    root,
    ...root.querySelectorAll("*"),
  ];

  elements.forEach(
    (element) => {
      if (
        element?.closest?.(
          "[data-stock-content]"
        )
      ) {
        return;
      }

      [
        "placeholder",
        "title",
        "aria-label",
      ].forEach(
        (attribute) => {
          if (
            !element?.hasAttribute?.(
              attribute
            )
          ) {
            return;
          }

          const currentValue =
            element.getAttribute(
              attribute
            ) || "";

          const translatedValue =
            getStockRenderedText(
              currentValue
            );

          if (
            translatedValue !==
            currentValue
          ) {
            element.setAttribute(
              attribute,
              translatedValue
            );
          }
        }
      );
    }
  );
}
