// PATIENTS TAB — ИСПРАВЛЕННЫЙ РЕНДЕР
// =========================
function renderPatientsTab() {
  const page =
    document.querySelector(
      '.page[data-page="patients"]'
    );

  if (!page) {
    return;
  }

  page.innerHTML = `
    <div
      class="glass-card"
      style="
        padding: 24px;
        border-radius: 20px;
        border: 1px solid rgba(255,255,255,0.1);
      "
    >
      <div
        style="
          display: flex;
          justify-content: space-between;
          align-items: center;
          margin-bottom: 24px;
        "
      >
        <h2 style="margin:0;">
          ${escapeHtml(
            translateInterfaceText(
              "patients.page.title"
            )
          )}
        </h2>

        <div class="hint">
          ${escapeHtml(
            translateInterfaceText(
              "patients.page.subtitle"
            )
          )}
        </div>
      </div>

      <div id="patientsTabList"></div>
    </div>
  `;

  const patientListElement =
    document.getElementById(
      "patientsTabList"
    );

  if (!patientListElement) {
    return;
  }

  const patients =
    Array.isArray(
      state.patients
    ) &&
    state.patients.length
      ? state.patients
      : loadPatients();

  const owners =
    Array.isArray(
      state.owners
    ) &&
    state.owners.length
      ? state.owners
      : LS.get(
          OWNERS_KEY,
          []
        );

  const ownerById =
    new Map(
      (owners || []).map(
        (owner) => [
          String(owner.id),
          owner,
        ]
      )
    );

  if (
    !patients.length &&
    (
      patientsApiLoading ||
      !patientsApiLoaded
    )
  ) {
    patientListElement.innerHTML = `
      <div
        class="patientsTabLoading"
        role="status"
        aria-live="polite"
      >
        <div
          class="patientsTabLoadingIcon"
          aria-hidden="true"
        >
          🐾
        </div>

        <strong>
          ${escapeHtml(
            translateInterfaceText(
              "patients.page.loadingTitle"
            )
          )}
        </strong>

        <span>
          ${escapeHtml(
            translateInterfaceText(
              "patients.page.loadingText"
            )
          )}
        </span>

        <div
          class="patientsTabLoadingDots"
          aria-hidden="true"
        >
          <i></i>
          <i></i>
          <i></i>
        </div>
      </div>
    `;

    return;
  }

  if (!patients.length) {
    patientListElement.innerHTML = `
      <div
        class="hint"
        style="
          text-align: center;
          padding: 40px;
          opacity: 0.5;
        "
      >
        ${escapeHtml(
          translateInterfaceText(
            "patients.page.empty"
          )
        )}
      </div>
    `;

    return;
  }

  const weightUnit =
    getInterfaceLanguage() ===
    "uk"
      ? "кг"
      : "kg";

  patientListElement.innerHTML =
    "";

  patients
    .slice()
    .sort(
      (first, second) =>
        String(
          second.id
        ).localeCompare(
          String(first.id)
        )
    )
    .forEach(
      (patient) => {
        const owner =
          ownerById.get(
            String(
              patient.owner_id
            )
          );

        const ownerName =
          String(
            owner?.name || ""
          ).trim();

        const patientName =
          String(
            patient.name || ""
          ).trim() ||
          translateInterfaceText(
            "calendar.detail.unnamed"
          );

        const meta = [
          speciesLabel(
            patient.species
          ),

          patient.breed
            ? getCalendarBreedLabel(
                patient.breed
              )
            : "",

          patient.age || "",

          patient.weight_kg
            ? `${patient.weight_kg} ${weightUnit}`
            : "",

          ownerName
            ? `👤 ${ownerName}`
            : "",
        ]
          .filter(Boolean)
          .map(
            (value) =>
              escapeHtml(
                String(value)
              )
          )
          .join(" • ");

        const element =
          document.createElement(
            "div"
          );

        element.className =
          "glass-card";

        element.style.cssText =
          "padding:16px;margin-bottom:12px;display:flex;justify-content:space-between;align-items:center;border-radius:12px;background:rgba(255,255,255,0.03);border:1px solid rgba(255,255,255,0.05);cursor:pointer;transition:0.2s;";

        element.dataset.openPet =
          String(patient.id);

        element.innerHTML = `
          <div style="flex:1;">
            <div
              style="
                font-size: 1.2rem;
                font-weight: 600;
              "
            >
              🐾 ${escapeHtml(
                patientName
              )}
            </div>

            <div
              style="
                font-size: 0.9rem;
                opacity: 0.6;
                margin-top: 4px;
              "
            >
              ${meta}
            </div>
          </div>

          <div class="patientActionsCell">
            <button
              class="
                iconBtn
                patientActionBtn
                patientEditBtn
              "
              type="button"
              title="${escapeHtml(
                translateInterfaceText(
                  "owners.profile.editPatient"
                )
              )}"
              aria-label="${escapeHtml(
                translateInterfaceText(
                  "owners.profile.editPatient"
                )
              )}"
              data-edit-pet="${escapeHtml(
                String(patient.id)
              )}"
            >
              <svg
                viewBox="0 0 24 24"
                width="16"
                height="16"
                fill="none"
                stroke="currentColor"
                stroke-width="1.8"
                stroke-linecap="round"
                stroke-linejoin="round"
                aria-hidden="true"
              >
                <path d="M12 20h9"></path>
                <path
                  d="
                    M16.5 3.5
                    a2.1 2.1 0 0 1 3 3
                    L8 18
                    l-4 1
                    1-4Z
                  "
                ></path>
              </svg>
            </button>

            <button
              class="
                iconBtn
                patientActionBtn
                patientDeleteBtn
              "
              type="button"
              title="${escapeHtml(
                translateInterfaceText(
                  "owners.profile.deletePatient"
                )
              )}"
              aria-label="${escapeHtml(
                translateInterfaceText(
                  "owners.profile.deletePatient"
                )
              )}"
              data-del-pet="${escapeHtml(
                String(patient.id)
              )}"
            >
              <svg
                viewBox="0 0 24 24"
                width="16"
                height="16"
                fill="none"
                stroke="currentColor"
                stroke-width="1.8"
                stroke-linecap="round"
                stroke-linejoin="round"
                aria-hidden="true"
              >
                <path d="M3 6h18"></path>
                <path d="M8 6V4h8v2"></path>
                <path d="M19 6l-1 14H6L5 6"></path>
                <path d="M10 11v5"></path>
                <path d="M14 11v5"></path>
              </svg>
            </button>
          </div>
        `;

        patientListElement.appendChild(
          element
        );
      }
    );

  patientListElement.onclick =
    async (event) => {
      const editButton =
        event.target.closest(
          "[data-edit-pet]"
        );

      if (editButton) {
        event.preventDefault();
        event.stopPropagation();

        const petId =
          editButton.dataset
            .editPet;

        const pet =
          (
            state.patients || []
          ).find(
            (item) =>
              String(item.id) ===
              String(petId)
          );

        if (!pet) {
          showCrmNotice({
            icon:
              "🐾",

            title:
              translateInterfaceText(
                "calendar.detail.patient.not.found"
              ),
          });

          return;
        }

        openAddPetModal(
          pet.owner_id,
          pet
        );

        return;
      }

      const deleteButton =
        event.target.closest(
          "[data-del-pet]"
        );

      if (deleteButton) {
        event.preventDefault();
        event.stopPropagation();

        const petId =
          deleteButton.dataset
            .delPet;

        if (petId) {
          await deletePatientEverywhere(
            petId
          );
        }

        return;
      }

      const openZone =
        event.target.closest(
          "[data-open-pet]"
        );

      if (!openZone) {
        return;
      }

      const petId =
        openZone.dataset
          .openPet;

      if (petId) {
        openPatient(
          petId
        );
      }
    };
}
