const backButton =
  root.querySelector(
    "#btnBackToProfile"
  );

if (backButton) {
  backButton.onclick =
    () => {
      window.location.hash =
        "#patients";
    };
}

const addVisitButton =
  root.querySelector(
    "#btnAddVisit"
  );

if (addVisitButton) {
  addVisitButton.onclick =
    () => {
      state.selectedPet =
        pet || null;

      state.selectedPetId =
        pet?.id ||
        pet?._id ||
        null;

      if (
        typeof openVisitModalForCreate ===
        "function"
      ) {
        openVisitModalForCreate(
          pet
        );

        return;
      }

      showCrmNotice({
        icon:
          "⚠️",

        title:
          translateInterfaceText(
            "patients.card.visitUnavailable"
          ),
      });
    };
}

root
