const statusButton =
  root.querySelector(
    "[data-patient-status-toggle]"
  );

if (statusButton) {
  statusButton.style.cursor =
    "pointer";

  statusButton.addEventListener(
    "click",
    () => {
      document
        .querySelector(
          ".patientStatusMenu"
        )
        ?.remove();

      const menu =
        document.createElement(
          "div"
        );

      menu.className =
        "patientStatusMenu";

      menu.innerHTML = `
        <button
          type="button"
          data-patient-status-value="active"
        >
          ● ${escapeHtml(
            translateInterfaceText(
              "patients.card.statusActive"
            )
          )}
        </button>

        <button
          type="button"
          data-patient-status-value="archived"
        >
          📦 ${escapeHtml(
            translateInterfaceText(
              "patients.card.statusArchived"
            )
          )}
        </button>

        <button
          type="button"
          data-patient-status-value="deceased"
        >
          † ${escapeHtml(
            translateInterfaceText(
              "patients.card.statusDeceased"
            )
          )}
        </button>
      `;

      statusButton.insertAdjacentElement(
        "afterend",
        menu
      );

      menu.addEventListener(
        "click",
        async (event) => {
          const button =
            event.target.closest(
              "[data-patient-status-value]"
            );

          if (!button) {
            return;
          }

          const nextStatus =
            button.dataset
              .patientStatusValue;

          if (
            nextStatus ===
            "deceased"
          ) {
            const deceasedDate =
              await openAppPrompt({
                title:
                  translateInterfaceText(
                    "patients.card.deathDate"
                  ),
                text:
                  translateInterfaceText(
                    "patients.card.deathDateText"
                  ),
                label:
                  translateInterfaceText(
                    "patients.card.date"
                  ),
                placeholder:
                  "2026-08-17",
                defaultValue:
                  todayISO(),
                confirmText:
                  translateInterfaceText(
                    "patients.card.confirm"
                  ),
                cancelText:
                  translateInterfaceText(
                    "patients.card.cancel"
                  ),
                required:
                  true,
              });

            if (!deceasedDate) {
              menu.remove();
              return;
            }

            try {
              const updatedPatient =
                await updatePatientStatusApi(
                  pet.id,
                  {
                    patient_status:
                      "deceased",
                    deceased_at:
                      deceasedDate,
                  }
                );

              pet.patient_status =
                updatedPatient
                  .patient_status;

              pet.deceased_at =
                updatedPatient
                  .deceased_at ||
                deceasedDate;

              await renderPatientTab(
                "overview",
                pet
              );
            } catch (error) {
              console.error(
                "PATIENT DECEASED UPDATE FAILED:",
                error
              );

              showCrmNotice({
                icon: "⚠️",
                title:
                  translateInterfaceText(
                    "patients.card.statusUpdateFailed"
                  ),
                text:
                  translateInterfaceText(
                    "patients.card.refreshTryAgain"
                  ),
              });
            }

            menu.remove();
            return;
          }

          if (
            nextStatus === "active" ||
            nextStatus === "archived"
          ) {
            try {
              const updatedPatient =
                await updatePatientStatusApi(
                  pet.id,
                  {
                    patient_status:
                      nextStatus,
                  }
                );

              pet.patient_status =
                updatedPatient
                  .patient_status;

              pet.deceased_at =
                updatedPatient
                  .deceased_at ||
                null;

              await renderPatientTab(
                "overview",
                pet
              );
            } catch (error) {
              console.error(
                "PATIENT STATUS UPDATE FAILED:",
                error
              );

              showCrmNotice({
                icon: "⚠️",
                title:
                  translateInterfaceText(
                    "patients.card.statusUpdateFailed"
                  ),
                text:
                  translateInterfaceText(
                    "patients.card.refreshTryAgain"
                  ),
              });
            }
          }

          menu.remove();
        }
      );
    }
  );
}

