function getPatientDocumentVisitLabel(
  visit
) {
  const ui =
    getPatientDocumentsUi();

  const parsed =
    typeof parseVisitNote ===
    "function"
      ? parseVisitNote(
          visit?.note ||
          ""
        )
      : {
          dx: "",
        };

  const diagnosis =
    String(
      visit?.dx ||
      parsed.dx ||
      ""
    ).trim();

  const serviceNames =
    typeof expandServiceLines ===
    "function"
      ? expandServiceLines(
          visit
        )
          .slice(
            0,
            2
          )
          .map(
            (line) =>
              line.name
          )
          .filter(
            Boolean
          )
      : [];

  const description =
    diagnosis ||
    serviceNames.join(
      ", "
    ) ||
    ui.visitFallback;

  return [
    formatPatientDocumentDate(
      visit?.date ||
      visit?.created_at
    ),

    description,
  ].join(
    " — "
  );
}

async function loadPatientHospitalizationsApi(
  patientId
) {
  try {
    const response = await fetch(
      `/api/hospitalizations?patient_id=${encodeURIComponent(
        String(patientId)
      )}`,
      {
        credentials: "include",
        headers: {
          Accept: "application/json",
          ...getOrgHeaders(),
        },
      }
    );

    const result =
      await response
        .json()
        .catch(() => null);

    if (
      !response.ok ||
      !result?.ok
    ) {
      return [];
    }

    return Array.isArray(result.data)
      ? result.data
      : [];
  } catch (error) {
    console.error(
      "loadPatientHospitalizationsApi failed:",
      error
    );

    return [];
  }
}

function renderPatientDocumentCard({
  type,
  icon,
  title,
  description,
  badge,
  options,
  selectLabel,
  emptyText,
  disabled = false,
}) {
  const ui =
    getPatientDocumentsUi();

  const available =
    Array.isArray(
      options
    ) &&
    options.length > 0;

  return `
    <article
      class="patientDocumentCard ${
        disabled
          ? "is-disabled"
          : ""
      }"
    >
      <div
        class="patientDocumentCardTop"
      >
        <span
          class="patientDocumentIcon"
        >
          ${icon}
        </span>

        <span
          class="patientDocumentBadge"
        >
          ${escapeHtml(
            badge
          )}
        </span>
      </div>

      <h3>
        ${escapeHtml(
          title
        )}
      </h3>

      <p>
        ${escapeHtml(
          description
        )}
      </p>

      ${
        disabled
          ? `
            <div
              class="patientDocumentNotice"
            >
              ${escapeHtml(
                ui.templateNotice
              )}
            </div>
          `
          : available
            ? `
              <label
                class="patientDocumentSelectLabel"
              >
                <span>
                  ${escapeHtml(
                    selectLabel
                  )}
                </span>

                <select
                  class="patientDocumentSelect"
                  data-patient-document-source="${escapeHtml(
                    type
                  )}"
                >
                  ${options
                    .map(
                      (
                        option
                      ) => `
                        <option
                          value="${escapeHtml(
                            String(
                              option.value
                            )
                          )}"
                        >
                          ${escapeHtml(
                            option.label
                          )}
                        </option>
                      `
                    )
                    .join("")}
                </select>
              </label>

              <button
                type="button"
                class="patientDocumentCreate"
                data-create-patient-document="${escapeHtml(
                  type
                )}"
              >
                <span>
                  ↓
                </span>

                ${escapeHtml(
                  ui.generatePdf
                )}
              </button>
            `
            : `
              <div
                class="patientDocumentEmpty"
              >
                ${escapeHtml(
                  emptyText
                )}
              </div>
            `
      }
    </article>
  `;
}

async function renderPatientDocumentsTab(
  root,
  pet
) {
  if (
    !root ||
    !pet
  ) {
    return;
  }

  const ui =
    getPatientDocumentsUi();

  root.innerHTML = `
    <div
      class="patientDocumentsLoading"
    >
      ${escapeHtml(
        ui.loading
      )}
    </div>
  `;

  const visits =
    await loadVisitsApi({
      pet_id:
        pet.id,
    });

  const hospitalizations =
    await loadPatientHospitalizationsApi(
      pet.id
    );

  const patientVisits =
    (
      Array.isArray(
        visits
      )
        ? visits
        : []
    ).sort(
      (a, b) =>
        String(
          b.date ||
          b.created_at ||
          ""
        ).localeCompare(
          String(
            a.date ||
            a.created_at ||
            ""
          )
        )
    );

  const completedHospitalizations =
    (
      Array.isArray(
        hospitalizations
      )
        ? hospitalizations
        : []
    )
      .filter(
        (item) =>
          item?.is_active ===
            false ||
          Boolean(
            item?.discharged_at
          )
      )
      .sort(
        (a, b) =>
          String(
            b.discharged_at ||
            b.admitted_at ||
            ""
          ).localeCompare(
            String(
              a.discharged_at ||
              a.admitted_at ||
              ""
            )
          )
      );

  const visitOptions =
    patientVisits.map(
      (visit) => ({
        value:
          visit.id,

        label:
          getPatientDocumentVisitLabel(
            visit
          ),
      })
    );

  const hospitalOptions =
    completedHospitalizations.map(
      (item) => ({
        value:
          item.id,

        label: [
          formatPatientDocumentDate(
            item.admitted_at
          ),

          "—",

          formatPatientDocumentDate(
            item.discharged_at
          ),

          item.diagnosis
            ? `· ${
                item.diagnosis
              }`
            : "",
        ]
          .filter(
            Boolean
          )
          .join(
            " "
          ),
      })
    );

  const consentOptions =
    Object.keys(
      PATIENT_CONSENT_TYPES
    ).map(
      (value) => ({
        value,

        label:
          getPatientConsentShortTitle(
            value
          ),
      })
    );

  const availableSources =
    patientVisits.length +
    completedHospitalizations
      .length;

  root.innerHTML = `
    <section
      class="patientDocumentsPage"
    >
      <header
        class="patientDocumentsHead"
      >
        <div>
          <div
            class="patientDocumentsKicker"
          >
            ${escapeHtml(
              ui.kicker
            )}
          </div>

          <h2>
            ${escapeHtml(
              ui.title
            )}
          </h2>

          <p>
            ${escapeHtml(
              ui.description
            )}
          </p>
        </div>

        <div
          class="patientDocumentsSummary"
        >
          <span>
            ${escapeHtml(
              ui.availableSources
            )}
          </span>

          <strong>
            ${availableSources}
          </strong>

          <small>
            ${patientVisits.length}
            ${escapeHtml(
              ui.visits
            )}
            ·
            ${
              completedHospitalizations
                .length
            }
            ${escapeHtml(
              ui.discharges
            )}
          </small>
        </div>
      </header>

      <div
        class="patientDocumentsGrid"
      >
        ${renderPatientDocumentCard({
          type:
            "visit",

          icon:
            "🩺",

          title:
            ui.visitTitle,

          description:
            ui.visitDescription,

          badge:
            ui.visitBadge,

          options:
            visitOptions,

          selectLabel:
            ui.selectVisit,

          emptyText:
            ui.noVisits,
        })}

        ${renderPatientDocumentCard({
          type:
            "hospital",

          icon:
            "🏥",

          title:
            ui.hospitalTitle,

          description:
            ui.hospitalDescription,

          badge:
            ui.hospitalBadge,

          options:
            hospitalOptions,

          selectLabel:
            ui.selectHospital,

          emptyText:
            ui.noHospital,
        })}

        ${renderPatientDocumentCard({
          type:
            "prescriptions",

          icon:
            "💊",

          title:
            ui.prescriptionsTitle,

          description:
            ui.prescriptionsDescription,

          badge:
            ui.ownerBadge,

          options:
            visitOptions,

          selectLabel:
            ui.selectVisit,

          emptyText:
            ui.createVisitFirst,
        })}

        ${renderPatientDocumentCard({
          type:
            "finance",

          icon:
            "🧾",

          title:
            ui.financeTitle,

          description:
            ui.financeDescription,

          badge:
            ui.financeBadge,

          options:
            visitOptions,

          selectLabel:
            ui.selectVisit,

          emptyText:
            ui.noFinanceVisits,
        })}

        ${renderPatientDocumentCard({
          type:
            "consent",

          icon:
            "✍️",

          title:
            ui.consentTitle,

          description:
            ui.consentDescription,

          badge:
            ui.consentBadge,

          options:
            consentOptions,

          selectLabel:
            ui.selectDocumentType,

          emptyText:
            ui.templatesUnavailable,
        })}
      </div>

      <div
        class="patientDocumentsHint"
      >
        <span>
          ⓘ
        </span>

        ${escapeHtml(
          ui.hint
        )}
      </div>
    </section>
  `;

  root
    .querySelectorAll(
      "[data-create-patient-document]"
    )
    .forEach(
      (button) => {
        button.addEventListener(
          "click",
          async () => {
            const type =
              button.dataset
                .createPatientDocument;

            const select =
              root.querySelector(
                `[data-patient-document-source="${type}"]`
              );

            const sourceId =
              select?.value ||
              "";

            if (!sourceId) {
              return;
            }

            const original =
              button.innerHTML;

            button.disabled =
              true;

            button.textContent =
              ui.generating;

            try {
              let consentData =
                null;

              if (
                type ===
                "consent"
              ) {
                consentData =
                  await openPatientConsentModal({
                    consentType:
                      sourceId,

                    pet,

                    visits:
                      patientVisits,
                  });

                if (
                  !consentData
                ) {
                  return;
                }
              }

              await createPatientDocumentPdf({
                type,
                sourceId,
                pet,

                visits:
                  patientVisits,

                hospitalizations:
                  completedHospitalizations,

                consentData,
              });
            } catch (error) {
              console.error(
                "createPatientDocumentPdf failed:",
                error
              );

              alert(
                ui.createFailed
              );
            } finally {
              button.disabled =
                false;

              button.innerHTML =
                original;
            }
          }
        );
      }
    );
}

async function getPatientDocumentClinic() {
  let org =
    state.clinicProfile ||
    null;

  if (
    !org &&
    typeof loadClinicProfileApi ===
      "function"
  ) {
    org =
      await loadClinicProfileApi();
  }

  return org || {};
}

function patientConsentLocalDateTime(
  value = new Date()
) {
  const date =
    value instanceof Date
      ? value
      : new Date(value);

  if (Number.isNaN(date.getTime())) {
    return "";
  }

  const offset =
    date.getTimezoneOffset() *
    60000;

  return new Date(
    date.getTime() - offset
  )
    .toISOString()
    .slice(0, 16);
}

function getPatientConsentVisitDefaults(
  visit
) {
  if (!visit) {
    return {
      diagnosis: "",
      subject: "",
      notes: "",
    };
  }

  const parsedNote =
    typeof parseVisitNote ===
      "function"
      ? parseVisitNote(
          visit.note || ""
        )
      : {};

  const services =
    typeof expandServiceLines ===
      "function"
      ? expandServiceLines(visit)
      : [];

  return {
    diagnosis:
      String(
        visit.dx ||
        parsedNote.dx ||
        ""
      ).trim(),
    subject:
      services
        .map((line) => line.name)
        .filter(Boolean)
        .join(", "),
    notes: "",
  };
}
