function renderPatientDocumentSection(
  title,
  value,
  soft = false
) {
  const normalizedValue =
    String(value || "").trim() ||
    "—";

  let separated = false;

  const content =
    normalizedValue
      .split(/\r?\n/)
      .map((line) => {
        const text =
          String(line || "").trim();

        if (!text) {
          separated = true;
          return "";
        }

        const bulletMatch =
          text.match(
            /^(?:•|●|▪|-)\s*(.+)$/
          );

        const spacingClass =
          separated
            ? " is-spaced"
            : "";

        separated = false;

        if (bulletMatch) {
          return `
            <div class="disModernTextLine disModernTextBullet${spacingClass}">
              <span aria-hidden="true">•</span>
              <span>${escapeHtml(
                bulletMatch[1]
              )}</span>
            </div>
          `;
        }

        return `
          <div class="disModernTextLine${spacingClass}">
            ${escapeHtml(text)}
          </div>
        `;
      })
      .join("");

  return `
    <div class="disModernSection">
      <div class="disModernSectionTitle">
        ${escapeHtml(title)}
      </div>

      <div class="disModernText ${
        soft
          ? "disModernTextSoft"
          : ""
      }">
        ${content}
      </div>
    </div>
  `;
}

function getPatientDocumentDoctorName(
  visit
) {
  const staff =
    (Array.isArray(state.staff)
      ? state.staff
      : []
    ).find(
      (item) =>
        String(item?.id || "") ===
        String(
          visit?.staff_id ||
          visit?.doctor_id ||
          ""
        )
    );

  return (
    visit?.doctor_name ||
    visit?.staff_name ||
    staff?.name ||
    "Ветеринарний лікар"
  );
}

async function createVisitBasedDocumentHtml({
  type,
  visit,
  pet,
  owner,
  clinic,
}) {
  const parsedNote =
    parseVisitNote(
      visit?.note || ""
    );

  const parsedTreatment =
    parseVisitRx(
      visit?.rx || ""
    );

  const parsedLegacyTreatment =
    typeof parseRxCombined ===
      "function"
      ? parseRxCombined(
          visit?.rx || ""
        )
      : {
          rx: "",
          recs: "",
          follow: "",
        };

  const diagnosis =
    visit?.dx ||
    parsedNote.dx ||
    "";

  const complaint =
    parsedNote.complaint ||
    visit?.note ||
    "";

  const hasModernTreatmentFormat =
    String(
      visit?.rx || ""
    ).includes(
      "\n\nРекомендації власнику:\n"
    );

  const treatment =
    (
      hasModernTreatmentFormat
        ? parsedTreatment.rx
        : parsedLegacyTreatment.rx
    ) ||
    visit?.rx ||
    "";

  const recommendation =
    parsedTreatment.recommendation ||
    parsedLegacyTreatment.recs ||
    "";

  const follow =
    parsedLegacyTreatment.follow ||
    "";

  const services =
    expandServiceLines(visit);

  const stock =
    expandStockLines(visit);

  const doctorName =
    getPatientDocumentDoctorName(
      visit
    );

  let title =
    "Виписка за візитом";

  let body = "";

  if (type === "visit") {
    const procedures =
      services.length
        ? services
            .map(
              (line) =>
                `• ${line.name}${
                  Number(line.qty || 1) > 1
                    ? ` — ${line.qty}`
                    : ""
                }`
            )
            .join("\n")
        : "—";

    const materials =
      stock.length
        ? stock
            .map(
              (line) =>
                `• ${line.name} — ${
                  line.qty
                } ${line.unit || "шт"}`
            )
            .join("\n")
        : "—";

    body = [
      renderPatientDocumentSection(
        "Скарги та анамнез",
        complaint
      ),
      renderPatientDocumentSection(
        "Встановлений діагноз",
        diagnosis
      ),
      renderPatientDocumentSection(
        "Проведені процедури",
        procedures
      ),
      renderPatientDocumentSection(
        "Використані препарати та матеріали",
        materials
      ),
      renderPatientDocumentSection(
        "Призначення лікаря",
        treatment,
        true
      ),
      renderPatientDocumentSection(
        "Рекомендації власнику",
        recommendation
      ),
      renderPatientDocumentSection(
        "Контроль та повторний огляд",
        follow
      ),
    ].join("");
  } else if (
    type === "prescriptions"
  ) {
    title =
      "Лист призначень і рекомендацій";

    body = [
      renderPatientDocumentSection(
        "Діагноз",
        diagnosis
      ),
      renderPatientDocumentSection(
        "Призначене лікування",
        treatment,
        true
      ),
      renderPatientDocumentSection(
        "Рекомендації з догляду",
        recommendation
      ),
      renderPatientDocumentSection(
        "Контроль та повторний огляд",
        follow
      ),
    ].join("");
  } else if (type === "finance") {
    title =
      "Фінансова виписка";

    let finance = null;

    try {
      finance =
        await loadVisitFinanceApi(
          visit.id
        );
    } catch (error) {
      console.warn(
        "Finance document fallback:",
        error
      );
    }

    const rows = [
      ...services.map((line) => ({
        name: line.name || "Послуга",
        type: "Послуга",
        qty: line.qty || 1,
        unit: "",
        price: line.price || 0,
        total: line.lineTotal || 0,
      })),
      ...stock.map((line) => ({
        name:
          line.name ||
          "Препарат",
        type:
          "Препарат / матеріал",
        qty: line.qty || 1,
        unit: line.unit || "шт",
        price: line.price || 0,
        total: line.lineTotal || 0,
      })),
    ];

    const subtotal =
      Number(
        finance?.subtotal ??
        rows.reduce(
          (sum, row) =>
            sum +
            Number(row.total || 0),
          0
        )
      ) || 0;

    const discount =
      Number(
        finance?.discount || 0
      ) || 0;

    const total =
      Number(
        finance?.total ??
        Math.max(
          0,
          subtotal - discount
        )
      ) || 0;

    const paid =
      Number(
        finance?.paid || 0
      ) || 0;

    const remaining =
      Number(
        finance?.remaining ??
        Math.max(0, total - paid)
      ) || 0;

    const financeAvailable =
      Boolean(finance);

    const statusLabels = {
      unpaid: "Не оплачено",
      partial:
        "Оплачено частково",
      paid: "Оплачено",
      refunded: "Повернено",
      cancelled: "Скасовано",
    };

    const methodLabels = {
      cash: "Готівка",
      card: "Картка",
      terminal: "Термінал",
      transfer: "Переказ",
      other: "Інше",
    };

    const paymentMethods =
      Array.from(
        new Set(
          (finance?.transactions || [])
            .filter(
              (transaction) =>
                transaction?.status ===
                "completed"
            )
            .map(
              (transaction) =>
                methodLabels[
                  transaction
                    ?.payment_method
                ] ||
                transaction
                  ?.payment_method
            )
            .filter(Boolean)
        )
      ).join(", ") || "—";

    const rowsHtml =
      rows.length
        ? rows
            .map(
              (row) => `
                <tr>
                  <td>${escapeHtml(
                    row.name
                  )}</td>
                  <td>${escapeHtml(
                    row.type
                  )}</td>
                  <td>
                    ${escapeHtml(
                      String(row.qty)
                    )}
                    ${escapeHtml(
                      row.unit
                    )}
                  </td>
                  <td>
                    ${formatPatientMoney(
                      row.price
                    )}
                  </td>
                  <td>
                    ${formatPatientMoney(
                      row.total
                    )}
                  </td>
                </tr>
              `
            )
            .join("")
        : `
          <tr>
            <td
              colspan="5"
              class="disModernEmpty"
            >
              Послуги та препарати
              не додані
            </td>
          </tr>
        `;

    body = `
      <div class="disModernSection disModernFinanceSection">
        <div class="disModernFinanceHead">
          <div>
            <div class="disModernSectionTitle">
              Надані послуги та використані препарати
            </div>
            <div class="disModernSectionSub">
              Деталізація візиту без медичних нотаток
            </div>
          </div>

          <div class="disModernGrandTotalBadge">
            ${formatPatientMoney(total)}
          </div>
        </div>

        <div class="disModernTableWrap">
          <table class="disModernTable">
            <thead>
              <tr>
                <th>Назва</th>
                <th>Тип</th>
                <th>К-сть</th>
                <th>Ціна</th>
                <th>Сума</th>
              </tr>
            </thead>
            <tbody>${rowsHtml}</tbody>
          </table>
        </div>

        <div class="disModernFinanceSummary">
          <div class="disModernFinanceMini">
            <span>Підсумок</span>
            <b>${formatPatientMoney(
              subtotal
            )}</b>
          </div>

          <div class="disModernFinanceMini">
            <span>Знижка</span>
            <b>${formatPatientMoney(
              discount
            )}</b>
          </div>

          <div class="disModernFinanceMini disModernFinanceMiniTotal">
            <span>До сплати</span>
            <b>${formatPatientMoney(
              total
            )}</b>
          </div>
        </div>
      </div>

      <div class="disModernInfoGrid">
        <div class="disModernCard">
          <div class="disModernCardTitle">
            Стан оплати
          </div>
          <div class="disModernCardMain">
            ${escapeHtml(
              statusLabels[
                finance
                  ?.financial_status
              ] ||
              finance
                ?.financial_status ||
              (
                financeAvailable
                  ? "Не оплачено"
                  : "Статус недоступний"
              )
            )}
          </div>
          <div class="disModernInfoRows">
            <div class="disModernInfoRow">
              <span>Оплачено</span>
              <b>${formatPatientMoney(
                paid
              )}</b>
            </div>
            <div class="disModernInfoRow">
              <span>Залишок</span>
              <b>${formatPatientMoney(
                remaining
              )}</b>
            </div>
          </div>
        </div>

        <div class="disModernCard">
          <div class="disModernCardTitle">
            Оплата
          </div>
          <div class="disModernCardMain">
            ${escapeHtml(
              financeAvailable
                ? paymentMethods
                : "Недоступно для поточної ролі"
            )}
          </div>
          <div class="disModernInfoRows">
            <div class="disModernInfoRow">
              <span>Операцій</span>
              <b>${
                (
                  finance
                    ?.transactions ||
                  []
                ).length
              }</b>
            </div>
          </div>
        </div>
      </div>
    `;
  }

  return renderPatientDocumentShell({
    title,
    number: String(
      visit?.id || ""
    )
      .slice(0, 8)
      .toUpperCase(),
    dateLabel:
      `Дата візиту: ${
        formatPatientDocumentDate(
          visit?.date ||
          visit?.created_at
        )
      }`,
    pet: {
      ...pet,
      weight_kg:
        visit?.weight_kg ||
        pet?.weight_kg,
    },
    owner,
    doctorName,
    clinic,
    body,
  });
}

async function createHospitalDocumentHtml({
  hospitalization,
  pet,
  owner,
  clinic,
}) {
  const tasks =
    await loadHospitalTasksApi(
      hospitalization.id
    );

  const completedTasks =
    (tasks || []).filter(
      (task) =>
        task?.status ===
        "completed"
    );

  const taskText =
    completedTasks.length
      ? completedTasks
          .map((task) => {
            const parts = [
              `• ${
                task.title ||
                "Призначення"
              }`,
            ];

            if (task.instructions) {
              parts.push(
                task.instructions
              );
            }

            if (task.completed_at) {
              parts.push(
                `виконано ${
                  formatPatientDocumentDate(
                    task.completed_at,
                    true
                  )
                }`
              );
            }

            return parts.join(" — ");
          })
          .join("\n")
      : "Виконані призначення не зафіксовані.";

  const body = [
    renderPatientDocumentSection(
      "Період госпіталізації",
      `${
        formatPatientDocumentDate(
          hospitalization.admitted_at,
          true
        )
      } — ${
        formatPatientDocumentDate(
          hospitalization.discharged_at,
          true
        )
      }`
    ),
    renderPatientDocumentSection(
      "Діагноз",
      hospitalization.diagnosis
    ),
    renderPatientDocumentSection(
      "Виконані процедури та призначення",
      taskText,
      true
    ),
    renderPatientDocumentSection(
      "Стан та примітка до виписки",
      hospitalization.notes
    ),
    renderPatientDocumentSection(
      "Рекомендації власнику",
      hospitalization.recommendations
    ),
  ].join("");

  return renderPatientDocumentShell({
    title:
      "Виписка зі стаціонару",
    number: String(
      hospitalization?.id || ""
    )
      .slice(0, 8)
      .toUpperCase(),
    dateLabel:
      `Дата виписки: ${
        formatPatientDocumentDate(
          hospitalization
            ?.discharged_at
        )
      }`,
    pet:
      hospitalization?.patient ||
      pet,
    owner:
      hospitalization?.owner ||
      owner,
    doctorName:
      hospitalization
        ?.doctor_name ||
      getPatientDocumentDoctorName(
        hospitalization
      ),
    clinic,
    body,
  });
}

