function getPatientFileCategoryMeta(
  category
) {
  const ui =
    getPatientFilesUi();

  const labels = {
    all:
      ui.categoryAll,
    xray:
      ui.categoryXray,
    ultrasound:
      ui.categoryUltrasound,
    media:
      ui.categoryMedia,
    document:
      ui.categoryDocument,
    other:
      ui.categoryOther,
  };

  const source =
    PATIENT_FILE_CATEGORIES[
      category
    ] ||
    PATIENT_FILE_CATEGORIES
      .other;

  return {
    ...source,

    label:
      labels[category] ||
      ui.categoryOther,
  };
}
