async function loadSpecializationsApi() {
  try {
    const res = await fetch("/api/specializations");
    const json = await res.json();
    if (!json.ok) throw new Error(json.error || "Cannot load specializations");
    return Array.isArray(json.data) ? json.data : [];
  } catch (e) {
    console.error("loadSpecializationsApi failed:", e);
    return [];
  }
}

async function createSpecializationApi(payload) {
  Object.assign(SETTINGS_INTERFACE_TEXT, {
    "Не вдалося створити спеціалізацію.": {
      en: "Could not create the specialization.",
      de: "Das Fachgebiet konnte nicht angelegt werden.",
      pl: "Nie udało się utworzyć specjalizacji.",
    },
  });

  try {
    const response = await fetch(
      "/api/specializations",
      {
        method: "POST",
        credentials: "include",
        headers: {
          "Content-Type": "application/json",
          Accept: "application/json",
          ...getOrgHeaders(),
        },
        body: JSON.stringify(payload || {}),
      }
    );

    const responseText = await response.text();
    let json = null;

    try {
      json = responseText
        ? JSON.parse(responseText)
        : null;
    } catch {
      json = null;
    }

    if (!response.ok || json?.ok !== true) {
      throw new Error(
        json?.error ||
        `Specialization creation HTTP ${response.status}`
      );
    }

    return Array.isArray(json.data)
      ? json.data[0] || null
      : json.data || null;
  } catch (error) {
    console.error(
      "Specialization creation failed:",
      error
    );

    showSettingsMessage(
      getSettingsSafeErrorText(
        error,
        "Не вдалося створити спеціалізацію."
      )
    );

    return null;
  }
}

async function deleteSpecializationApi(specializationId) {
  const cleanId = String(
    specializationId || ""
  ).trim();

  if (!cleanId) {
    return {
      ok: false,
      error: "Не вказано напрям.",
    };
  }

  try {
    const response = await fetch(
      `/api/specializations/${encodeURIComponent(cleanId)}`,
      {
        method: "DELETE",
        credentials: "include",
        headers: {
          Accept: "application/json",
        },
      }
    );

    const json = await response.json();

    if (!response.ok || !json?.ok) {
      return {
        ok: false,
        error:
          json?.error ||
          "Не вдалося видалити напрям.",
      };
    }

    return { ok: true };
  } catch (error) {
    console.error(
      "deleteSpecializationApi failed:",
      error
    );

    return {
      ok: false,
      error:
        "Помилка з'єднання під час видалення напряму.",
    };
  }
}

