function addMinutesToTime(time, minutes) {
  const [h, m] = String(time || "00:00").split(":").map(Number);
  const d = new Date();
  d.setHours(h || 0, m || 0, 0, 0);
  d.setMinutes(d.getMinutes() + Number(minutes || 60));
  return String(d.getHours()).padStart(2, "0") + ":" + String(d.getMinutes()).padStart(2, "0");
}



const patientLabsApiCache =
  new Map();

function normalizePatientLabFromApi(
  lab
) {
  return {
    id:
      String(lab?.id || ""),

    pet_id:
      String(
        lab?.patient_id ||
        lab?.pet_id ||
        ""
      ),

    visit_id:
      lab?.visit_id || null,

    type:
      String(
        lab?.lab_type ||
        lab?.type ||
        ""
      ),

    date:
      String(
        lab?.performed_at ||
        lab?.date ||
        ""
      ),

    laboratory:
      String(
        lab?.laboratory || ""
      ),

        comment:
      String(
        lab?.comment || ""
      ),

    owner_explanation:
      String(
        lab?.owner_explanation || ""
      ),

    values:
      (
        lab?.values &&
        typeof lab.values === "object"
      )
        ? lab.values
        : {},

    refs:
      (
        lab?.refs &&
        typeof lab.refs === "object"
      )
        ? lab.refs
        : {},

    created_at:
      lab?.created_at || null,

    updated_at:
      lab?.updated_at || null,
  };
}

async function requestPatientLabs(
  patientId
) {
  const normalizedPatientId =
    String(
      patientId || ""
    ).trim();

  if (!normalizedPatientId) {
    throw new Error(
      "patient_id required"
    );
  }

  const response = await fetch(
    `/api/patients/${
      encodeURIComponent(
        normalizedPatientId
      )
    }/labs`,
    {
      method: "GET",
      credentials: "include",
      cache: "no-store",
      headers: {
        Accept:
          "application/json",

        ...getOrgHeaders(),
      },
    }
  );

  const text =
    await response.text();

  let payload = null;

  try {
    payload =
      text
        ? JSON.parse(text)
        : null;
  } catch {
    payload = null;
  }

  if (
    !response.ok ||
    payload?.ok !== true
  ) {
    throw new Error(
      payload?.error ||
      `HTTP ${response.status}`
    );
  }

  const items =
    Array.isArray(
      payload?.data?.items
    )
      ? payload.data.items
      : [];

  const normalizedItems =
    items.map(
      normalizePatientLabFromApi
    );

  patientLabsApiCache.set(
    normalizedPatientId,
    normalizedItems
  );

  return normalizedItems;
}

function getCachedPatientLabs(
  patientId
) {
  return (
    patientLabsApiCache.get(
      String(patientId || "")
    ) || []
  );
}

async function readPatientLabApiResponse(
  response
) {
  const text =
    await response.text();

  let payload = null;

  try {
    payload =
      text
        ? JSON.parse(text)
        : null;
  } catch {
    payload = null;
  }

  if (
    !response.ok ||
    payload?.ok !== true
  ) {
    throw new Error(
      payload?.error ||
      `HTTP ${response.status}`
    );
  }

  return payload.data || {};
}

async function requestCreatePatientLab(
  patientId,
  lab
) {
  const normalizedPatientId =
    String(
      patientId || ""
    ).trim();

  const response = await fetch(
    `/api/patients/${
      encodeURIComponent(
        normalizedPatientId
      )
    }/labs`,
    {
      method: "POST",
      credentials: "include",
      headers: {
        "Content-Type":
          "application/json",

        Accept:
          "application/json",

        ...getOrgHeaders(),
      },
      body: JSON.stringify({
        type:
          lab?.type || "",

        date:
          lab?.date || "",

        laboratory:
          lab?.laboratory || "",

                comment:
          lab?.comment || "",

        owner_explanation:
          lab?.owner_explanation || "",

        values:
          lab?.values || {},

        refs:
          lab?.refs || {},
      }),
    }
  );

  const data =
    await readPatientLabApiResponse(
      response
    );

  const createdLab =
    normalizePatientLabFromApi(
      data.item || {}
    );

  const currentLabs =
    getCachedPatientLabs(
      normalizedPatientId
    );

  patientLabsApiCache.set(
    normalizedPatientId,
    [
      createdLab,
      ...currentLabs.filter(
        (item) =>
          String(item.id) !==
          String(createdLab.id)
      ),
    ]
  );

  return createdLab;
}

async function requestUpdatePatientLab(
  patientId,
  labId,
  lab
) {
  const normalizedPatientId =
    String(
      patientId || ""
    ).trim();

  const normalizedLabId =
    String(
      labId || ""
    ).trim();

  const response = await fetch(
    `/api/patients/${
      encodeURIComponent(
        normalizedPatientId
      )
    }/labs/${
      encodeURIComponent(
        normalizedLabId
      )
    }`,
    {
      method: "PUT",
      credentials: "include",
      headers: {
        "Content-Type":
          "application/json",

        Accept:
          "application/json",

        ...getOrgHeaders(),
      },
      body: JSON.stringify({
        type:
          lab?.type || "",

        date:
          lab?.date || "",

        laboratory:
          lab?.laboratory || "",

                comment:
          lab?.comment || "",

        owner_explanation:
          lab?.owner_explanation || "",

        values:
          lab?.values || {},

        refs:
          lab?.refs || {},
      }),
    }
  );

  const data =
    await readPatientLabApiResponse(
      response
    );

  const updatedLab =
    normalizePatientLabFromApi(
      data.item || {}
    );

  const currentLabs =
    getCachedPatientLabs(
      normalizedPatientId
    );

  patientLabsApiCache.set(
    normalizedPatientId,
    currentLabs.map(
      (item) =>
        String(item.id) ===
        normalizedLabId
          ? updatedLab
          : item
    )
  );

  return updatedLab;
}

async function requestDeletePatientLab(
  patientId,
  labId
) {
  const normalizedPatientId =
    String(
      patientId || ""
    ).trim();

  const normalizedLabId =
    String(
      labId || ""
    ).trim();

  const response = await fetch(
    `/api/patients/${
      encodeURIComponent(
        normalizedPatientId
      )
    }/labs/${
      encodeURIComponent(
        normalizedLabId
      )
    }`,
    {
      method: "DELETE",
      credentials: "include",
      headers: {
        Accept:
          "application/json",

        ...getOrgHeaders(),
      },
    }
  );

  await readPatientLabApiResponse(
    response
  );

  const currentLabs =
    getCachedPatientLabs(
      normalizedPatientId
    );

  patientLabsApiCache.set(
    normalizedPatientId,
    currentLabs.filter(
      (item) =>
        String(item.id) !==
        normalizedLabId
    )
  );

  return true;
}
function getPugAiLanguage() {
  const supportedLanguages =
    new Set([
      "uk",
      "en",
      "pl",
      "es",
      "de",
    ]);

  const selectedLanguage =
    String(
      LS.get(
        "docpug_clinic_lang",
        "uk"
      ) || "uk"
    )
      .trim()
      .toLowerCase();

  return supportedLanguages.has(
    selectedLanguage
  )
    ? selectedLanguage
    : "uk";
}

document.documentElement.lang =
  getPugAiLanguage();

