// ===== Переход на страницу конкретного визита =====
async function openVisit(visitId, opts = { pushHash: true }) {
  const vid = String(visitId || "").trim();
  if (!vid) return;

  let visit = getVisitByIdSync(vid);

  if (!visit) {
    try {
      const arr = await loadVisitsApi({ id: vid });
      visit = arr?.[0] || null;
    } catch {}
  }

    if (!visit) {
    alert(
  getVisitWorkspaceText(
    "Візит не знайдено"
  )
);
    setHash("visits");
    return;
  }

  /*
   * Каталог мог ещё не загрузиться,
   * если визит открыли из карточки пациента.
   */
  if (
    !Array.isArray(
      state.services
    ) ||
    state.services.length === 0
  ) {
    await loadServicesApi();
  }

  ensureVisitServicesShape(
    visit
  );

  ensureVisitStockShape(
    visit
  );

try {
  const calendarEvents =
    await loadCalendarApi();

  const linkedCalendarEvent =
    (
      Array.isArray(
        calendarEvents
      )
        ? calendarEvents
        : []
    ).find(
      (event) =>
        String(
          event?.visit_id || ""
        ).trim() ===
        String(
          vid || ""
        ).trim()
    ) || null;

  visit.calendar_event_id =
    linkedCalendarEvent?.id ||
    visit.calendar_event_id ||
    null;

  visit.calendar_status =
    String(
      linkedCalendarEvent?.status ||
      visit.calendar_status ||
      ""
    )
      .trim()
      .toLowerCase();

  cacheVisits([
    visit,
  ]);
} catch (error) {
  console.warn(
    "Не вдалося визначити статус календарного запису:",
    error
  );

  visit.calendar_event_id =
    visit.calendar_event_id ||
    null;

  visit.calendar_status =
    String(
      visit.calendar_status ||
      ""
    )
      .trim()
      .toLowerCase();

  cacheVisits([
    visit,
  ]);
}


state.selectedVisitId =
  vid;

  const patients = Array.isArray(state.patients) && state.patients.length ? state.patients : loadPatients();
  const pet = (patients || []).find((p) => String(p.id) === String(visit.pet_id)) || null;

  if (pet) {
    state.selectedPet = pet;
    state.selectedPetId = String(pet.id);
    state.selectedOwnerId = pet.owner_id || state.selectedOwnerId;
  }

  renderVisitPage(visit, pet);
  if (typeof renderVisitFiles === "function") renderVisitFiles(vid);
  initVisitUI();
  setRoute("visit");

  if (opts.pushHash) setHash("visit", vid);
}

// =========================
// Отрисовка страницы приёма и медицинских блоков
// =========================
async function syncCalendarEventStatusByVisitId(
  visitId,
  nextStatus
) {
  const cleanVisitId =
    String(
      visitId || ""
    ).trim();

  const cleanStatus =
    String(
      nextStatus || ""
    )
      .trim()
      .toLowerCase();

  if (!cleanVisitId) {
    throw new Error(
      "Не вказано ID медичного візиту."
    );
  }

  if (!cleanStatus) {
    throw new Error(
      "Не вказано новий статус календаря."
    );
  }

  const calendarEvents =
    await loadCalendarApi();

  const allEvents =
    Array.isArray(
      calendarEvents
    )
      ? calendarEvents
      : [];

  const cachedVisit =
    getVisitByIdSync(
      cleanVisitId
    );

  const cachedCalendarEventId =
    String(
      cachedVisit
        ?.calendar_event_id ||
      ""
    ).trim();

  let linkedEvents =
    allEvents.filter(
      (event) =>
        String(
          event?.visit_id || ""
        ).trim() ===
        cleanVisitId
    );

  if (
    !linkedEvents.length &&
    cachedCalendarEventId
  ) {
    linkedEvents =
      allEvents.filter(
        (event) =>
          String(
            event?.id || ""
          ).trim() ===
          cachedCalendarEventId
      );
  }

  if (!linkedEvents.length) {
    console.error(
      "Не знайдено календарний запис для візиту:",
      {
        visitId:
          cleanVisitId,

        cachedCalendarEventId,

        calendarEvents:
          allEvents,
      }
    );

    throw new Error(
      (
        "Медичні дані збережено, " +
        "але календарний запис, " +
        "пов’язаний із візитом, " +
        "не знайдено."
      )
    );
  }

  const updatedEvents =
    [];

  for (
    const linkedEvent
    of linkedEvents
  ) {
    const updated =
      await updateCalendarEventApi(
        linkedEvent.id,
        {
          title:
            linkedEvent.title ||
            "Прийом",

          event_date:
            linkedEvent.event_date,

          start_time:
            linkedEvent.start_time,

          end_time:
            linkedEvent.end_time,

          staff_id:
            linkedEvent.staff_id,

          patient_id:
            linkedEvent.patient_id ||
            null,

          owner_id:
            linkedEvent.owner_id ||
            null,

          visit_id:
            cleanVisitId,

          location:
            linkedEvent.location ||
            "",

          note:
            linkedEvent.note ||
            "",

          status:
            cleanStatus,
        }
      );

    if (!updated?.id) {
      throw new Error(
        (
          "Сервер не підтвердив " +
          "оновлення календарного запису."
        )
      );
    }

    const returnedStatus =
      String(
        updated.status || ""
      )
        .trim()
        .toLowerCase();

    if (
      returnedStatus !==
      cleanStatus
    ) {
      console.error(
        "Calendar status was not saved:",
        {
          expected:
            cleanStatus,

          returned:
            returnedStatus,

          event:
            updated,
        }
      );

      throw new Error(
        (
          "Сервер повернув календарний запис, " +
          "але не зберіг статус «Завершено»."
        )
      );
    }

    updatedEvents.push(
      updated
    );
  }

  const primaryEvent =
    updatedEvents.find(
      (event) =>
        String(
          event.id || ""
        ) ===
        cachedCalendarEventId
    ) ||
    updatedEvents[0];

  const mergedVisit = {
    ...(cachedVisit || {}),

    calendar_event_id:
      primaryEvent?.id ||
      cachedCalendarEventId ||
      null,

    calendar_status:
      cleanStatus,
  };

  cacheVisits([
    mergedVisit,
  ]);

  console.log(
    "Календарні записи синхронізовано:",
    {
      visitId:
        cleanVisitId,

      status:
        cleanStatus,

      updatedEventIds:
        updatedEvents.map(
          (event) =>
            event.id
        ),
    }
  );

  return primaryEvent;
}
function renderVisitAiConsultItems(
  title,
  items,
  extraClass = ""
) {
  const normalizedItems =
    (
      Array.isArray(items)
        ? items
        : []
    )
      .map(
        (item) =>
          String(
            item || ""
          ).trim()
      )
      .filter(Boolean);

  if (!normalizedItems.length) {
    return "";
  }

  return `
    <section
      class="
        visitAiConsultSection
        ${extraClass}
      "
    >
      <h4>
        ${escapeHtml(title)}
      </h4>

      <ul>
        ${
          normalizedItems
            .map(
              (item) => `
                <li>
                  ${escapeHtml(item)}
                </li>
              `
            )
            .join("")
        }
      </ul>
    </section>
  `;
}

function renderVisitAiConsultAnswer(
  consultation,
  meta = {},
  {
    compact = false,
  } = {}
) {
  const normalizedConsultation =
    (
      consultation &&
      typeof consultation ===
        "object"
    )
      ? consultation
      : {};

  const directAnswer =
    String(
      normalizedConsultation
        .direct_answer ||
      "Відповідь не сформовано."
    ).trim();

  /*
   * Every follow-up is rendered as a
   * normal chat message without report
   * sections, coloured cards, or metadata.
   */
  if (compact) {
    return `
      <div
        class="
          visitAiConsultAnswer
          is-compact
          is-chat-reply
        "
      >
        <div
          class="visitAiConsultAnswerLabel"
        >
          PUG AI
        </div>

       <div
  class="visitAiConsultDirectAnswer"
>${escapeHtml(
  directAnswer
)}</div>
      </div>
    `;
  }

  /*
   * Only the first assistant response
   * receives the full clinical layout.
   */
  const confidenceLabels = {
    low:
      "Низька впевненість",
    medium:
      "Середня впевненість",
    high:
      "Висока впевненість",
  };

  const confidence =
    String(
      normalizedConsultation
        .confidence ||
      "low"
    );

  const durationMs =
    Number(
      meta?.duration_ms
    );

  const durationSeconds =
    Number.isFinite(
      durationMs
    ) &&
    durationMs > 0
      ? (
          durationMs / 1000
        ).toFixed(1)
      : null;

  return `
    <div
      class="
        visitAiConsultAnswer
        is-full
      "
    >
      <div
        class="visitAiConsultAnswerLabel"
      >
        PUG AI
      </div>

      <div
  class="visitAiConsultDirectAnswer"
>${escapeHtml(
  directAnswer
)}</div>

      ${renderVisitAiConsultItems(
        "Першочергові дії",
        normalizedConsultation
          .suggested_next_steps,
        "visitAiConsultPriority"
      )}

      ${renderVisitAiConsultItems(
        "Факти з картки",
        normalizedConsultation
          .record_facts
      )}

      ${renderVisitAiConsultItems(
        "Клінічні міркування",
        normalizedConsultation
          .clinical_considerations
      )}

      ${renderVisitAiConsultItems(
        "Що потрібно уточнити",
        normalizedConsultation
          .missing_information
      )}

      ${renderVisitAiConsultItems(
        "Важливо перевірити",
        normalizedConsultation
          .safety_flags,
        "visitAiConsultSafety"
      )}

      <div
        class="visitAiConsultMeta"
      >
        <span>
          ${escapeHtml(
            confidenceLabels[
              confidence
            ] ||
            confidenceLabels.low
          )}
        </span>

                ${
          durationSeconds
            ? `
              <span>
                ${escapeHtml(
                  getVisitWorkspaceText(
                    "Відповідь за"
                  )
                )}
                ${escapeHtml(
                  durationSeconds
                )} s
              </span>
            `
            : ""
        }

        <span>
          AI нічого не змінив
          у медичній картці
        </span>
      </div>
    </div>
  `;
}

function renderVisitAiConsultMessage(
  message,
  {
    firstAssistant = false,
  } = {}
) {
  const normalizedMessage =
    (
      message &&
      typeof message ===
        "object"
    )
      ? message
      : {};

  const role =
    String(
      normalizedMessage.role ||
      ""
    )
      .trim()
      .toLowerCase();

  const content =
    String(
      normalizedMessage.content ||
      ""
    ).trim();

  if (role === "user") {
    if (!content) {
      return "";
    }

    return `
      <div
        class="
          visitAiConsultMessage
          is-user
        "
        data-ai-consult-message=
          "user"
      >
        <div
          class="visitAiConsultMessageRole"
        >
          Ви
        </div>

        <div
  class="visitAiConsultUserBubble"
>${escapeHtml(
  content
)}</div>
      </div>
    `;
  }

  if (role !== "assistant") {
    return "";
  }

  const consultation =
    (
      normalizedMessage
        .consultation &&
      typeof normalizedMessage
        .consultation ===
        "object"
    )
      ? normalizedMessage
          .consultation
      : {};

  const hasConsultation =
    Boolean(
      Object.keys(
        consultation
      ).length
    );

  return `
    <div
      class="
        visitAiConsultMessage
        is-assistant
      "
      data-ai-consult-message=
        "assistant"
    >
      ${
        hasConsultation
          ? renderVisitAiConsultAnswer(
              consultation,
              normalizedMessage.meta ||
                {},
              {
                compact:
                  !firstAssistant,
              }
            )
          : `
              <div
                class="
                  visitAiConsultAnswer
                  is-compact
                "
              >
                <div
                  class="
                    visitAiConsultAnswerLabel
                  "
                >
                  PUG AI
                </div>

                <div
  class="
    visitAiConsultDirectAnswer
  "
>${escapeHtml(
  content ||
  (
    "Відповідь не " +
    "сформовано."
  )
)}</div>
              </div>
            `
      }
    </div>
  `;
}


function renderVisitAiConsultHistory(
  messages
) {
  const normalizedMessages =
    Array.isArray(messages)
      ? messages
      : [];

  let assistantWasRendered =
    false;

  return normalizedMessages
    .map(
      (message) => {
        const role =
          String(
            message?.role || ""
          )
            .trim()
            .toLowerCase();

        const firstAssistant =
          (
            role === "assistant" &&
            !assistantWasRendered
          );

        if (role === "assistant") {
          assistantWasRendered =
            true;
        }

        return (
          renderVisitAiConsultMessage(
            message,
            {
              firstAssistant,
            }
          )
        );
      }
    )
    .filter(Boolean)
    .join("");
}


function scrollVisitAiConsultToBottom(
  resultNode
) {
  if (!resultNode) {
    return;
  }

  requestAnimationFrame(
    () => {
      resultNode.scrollTop =
        resultNode.scrollHeight;
    }
  );
}
