function parseVisitNote(note) {
  const t =
    String(
      note || ""
    );

  const dxMatch =
    t.match(
      /Діагноз:\s*(.*?)(\n|$)/i
    );

  const dx =
    (
      dxMatch?.[1] || ""
    ).trim();

  const compMatch =
    t.match(
      /Скарги\/анамнез:\s*([\s\S]*)/i
    );

  const complaint =
    (
      compMatch?.[1] || ""
    ).trim();

  return {
    dx:
      dx || "",

    complaint:
      complaint ||
      (
        !dx
          ? t.trim()
          : ""
      ),
  };
}


function parseVisitRx(value) {
  const text = String(value || "").trim();

  const marker =
    "\n\nРекомендації власнику:\n";

  const markerIndex =
    text.indexOf(marker);

  if (markerIndex === -1) {
    return {
      rx: text,
      recommendation: "",
    };
  }

  return {
    rx: text
      .slice(0, markerIndex)
      .replace(/^Лікування:\s*/i, "")
      .trim(),

    recommendation: text
      .slice(markerIndex + marker.length)
      .trim(),
  };
}


function buildVisitRx(
  rx,
  recommendation
) {
  const treatment =
    String(rx || "").trim();

  const clientRecommendation =
    String(recommendation || "").trim();

  if (!clientRecommendation) {
    return treatment;
  }

  return [
    treatment
      ? `Лікування:\n${treatment}`
      : "Лікування:\n—",

    `Рекомендації власнику:\n${clientRecommendation}`,
  ].join("\n\n");
}
