function fillDischargeForm(
  visit,
  existing
) {
  const ex =
    existing || {};

  const parsed =
    parseVisitNote(
      visit?.note || ""
    );

  const parsedRx =
    typeof parseRxCombined ===
    "function"
      ? parseRxCombined(
          visit?.rx || ""
        )
      : {
          rx:
            visit?.rx || "",
          recs: "",
          follow: "",
        };

  const clinicalData =
    (
      visit?.clinical_data &&
      typeof (
        visit.clinical_data
      ) === "object" &&
      !Array.isArray(
        visit.clinical_data
      )
    )
      ? visit.clinical_data
      : {};

  const firstNonEmpty =
    (...values) => {
      for (const value of values) {
        const text =
          String(
            value ?? ""
          ).trim();

        if (text) {
          return text;
        }
      }

      return "";
    };

  const clinicalComplaint = [
    clinicalData
      .reason_for_visit,

    clinicalData
      .anamnesis,
  ]
    .map(
      (value) =>
        String(
          value || ""
        ).trim()
    )
    .filter(Boolean)
    .join("\n\n");

  const complaint =
    firstNonEmpty(
      ex.complaint,
      ex.disComplaint,
      clinicalComplaint,
      parsed.complaint
    );

  const dx =
    firstNonEmpty(
      ex.dx,
      ex.disDx,
      clinicalData.diagnosis,
      parsed.dx
    );

  const rx =
    firstNonEmpty(
      ex.rx,
      ex.disRx,
      clinicalData.prescriptions,
      parsedRx.rx
    );

  const recs =
    firstNonEmpty(
      ex.recs,
      ex.disRecs,
      clinicalData
        .home_recommendations,
      parsedRx.recs
    );

  const follow =
    firstNonEmpty(
      ex.follow,
      ex.disFollow,
      clinicalData.follow_up,
      parsedRx.follow
    );

  const c =
    document.getElementById(
      "disComplaint"
    );

  const d =
    document.getElementById(
      "disDx"
    );

  const r =
    document.getElementById(
      "disRx"
    );

  const re =
    document.getElementById(
      "disRecs"
    );

  const f =
    document.getElementById(
      "disFollow"
    );

  if (c) {
    c.value = complaint;
  }

  if (d) {
    d.value = dx;
  }

  if (r) {
    r.value = rx;
  }

  if (re) {
    re.value = recs;
  }

  if (f) {
    f.value = follow;
  }
}

