function initOwnerUI() {
  $("#btnAddPet")
    ?.addEventListener(
      "click",
      () => {
        const ownerId =
          state.selectedOwnerId;

        if (!ownerId) {
          showCrmNotice({
            icon:
              "🐾",

            title:
              translateInterfaceText(
                "owners.profile.selectOwner"
              ),
          });

          return;
        }

        openAddPetModal(
          ownerId
        );
      }
    );

  $("#petsList")
    ?.addEventListener(
      "click",
      async (event) => {
        const editButton =
          event.target.closest(
            "[data-edit-owner-pet]"
          );

        if (editButton) {
          event.preventDefault();
          event.stopPropagation();

          const petId =
            editButton.dataset
              .editOwnerPet;

          if (!petId) {
            return;
          }

          const pet =
            (
              state.patients || []
            ).find(
              (item) =>
                String(item.id) ===
                String(petId)
            );

          if (!pet) {
            openDeleteModal(
              translateInterfaceText(
                "calendar.detail.patient.not.found"
              ),
              null,
              "info"
            );

            return;
          }

          openAddPetModal(
            pet.owner_id,
            pet
          );

          return;
        }

        const deleteButton =
          event.target.closest(
            "[data-del-pet]"
          );

        if (deleteButton) {
          event.preventDefault();
          event.stopPropagation();

          const petId =
            deleteButton.dataset
              .delPet;

          if (!petId) {
            return;
          }

          const pet =
            (
              state.patients || []
            ).find(
              (item) =>
                String(item.id) ===
                String(petId)
            );

          const petName =
            pet?.name ||
            translateInterfaceText(
              "patients.delete.thisPatient"
            );

          openDeleteModal(
            `
              <b>
                ${escapeHtml(
                  petName
                )}
              </b>

              <br><br>

              ${escapeHtml(
                translateInterfaceText(
                  "owners.delete.confirmText"
                )
              )}
            `,
            async () => {
              const deleted =
                await deletePatientApi(
                  petId
                );

              if (!deleted) {
                openDeleteModal(
                  translateInterfaceText(
                    "patients.delete.failed"
                  ),
                  null,
                  "info"
                );

                return;
              }

              await loadPatientsApi();

              if (
                String(
                  state.selectedPetId ||
                  ""
                ) ===
                String(petId)
              ) {
                state.selectedPetId =
                  null;

                state.selectedPet =
                  null;
              }

              if (
                state.selectedOwnerId
              ) {
                await renderOwnerPage(
                  state.selectedOwnerId
                );
              }
            }
          );

          return;
        }

        const openZone =
          event.target.closest(
            "[data-open-pet]"
          );

        if (!openZone) {
          return;
        }

        const petId =
          openZone.dataset
            .openPet;

        if (petId) {
          openPatient(
            petId
          );
        }
      }
    );
}
