function initVisitsTabUI() {
  const page =
    document.querySelector(
      '.page[data-page="visits"]'
    );

  if (
    !page ||
    page.dataset
      .visitsUiBound === "1"
  ) {
    return;
  }

  page.dataset.visitsUiBound =
    "1";

  page.onclick =
    async (event) => {
      const openButton =
        event.target.closest(
          "[data-open-visit]"
        );

      if (!openButton) {
        return;
      }

      event.preventDefault();
      event.stopPropagation();

      const visitId =
        openButton.dataset
          .openVisit;

      if (visitId) {
        openVisit(
          visitId
        );
      }
    };
}

function closeVisitModal() {
  const modal = $("#visitModal");

  if (!modal) return;

  const activeElement =
    document.activeElement;

  if (
    activeElement &&
    modal.contains(activeElement)
  ) {
    activeElement.blur();
  }

  modal.classList.remove("open");

  modal.setAttribute(
    "aria-hidden",
    "true"
  );

  modal.style.display = "none";

  delete modal.dataset.visitId;
  delete modal.dataset.openSource;
  delete modal.dataset.patientId;

  state.selectedPet = null;
  state.selectedPetId = null;

  const patientSelect =
    $("#visitPatientSelect");

  if (patientSelect) {
    patientSelect.value = "";
  }

  const patientSearch =
    $("#visitPatientSearch");

  if (patientSearch) {
    patientSearch.value = "";
  }

  const patientResults =
    $("#visitPatientResults");

  if (patientResults) {
    patientResults.innerHTML = "";
  }

  const modalSub =
    $("#visitModalSub");

  if (modalSub) {
    modalSub.textContent =
      translateInterfaceText("calendar.detail.select.a.patient");
  }

  const patientBlock =
    $("#visitPatientBlock");

  if (patientBlock) {
    patientBlock.style.display =
      "block";
  }

  const newPatientBox =
    $("#visitNewPatientBox");

  if (newPatientBox) {
    newPatientBox.style.display =
      "none";
  }

  [
    "#visitNewOwnerName",
    "#visitNewOwnerPhone",
    "#visitNewOwnerNote",
    "#visitNewPetName",
    "#visitNewPetSpecies",
    "#visitNewPetBreed",
    "#visitNewPetAge",
    "#visitNewPetWeight",
  ].forEach((selector) => {
    const element =
      $(selector);

    if (!element) return;

    if (
      element.tagName ===
      "SELECT"
    ) {
      element.selectedIndex = 0;
    } else {
      element.value = "";
    }
  });

  document.body.classList.remove(
    "medcardModalIsOpen"
  );
  delete modal.dataset
  .initialState;
}

