// =========================
// Спецификации видов животных и нормализаторы
// =========================
function normalizeSpecies(
  value
) {
  const species =
    String(value || "")
      .toLowerCase()
      .trim();

  if (
    species === "dog" ||
    species.includes("пес") ||
    species.includes("соб") ||
    species.includes("hund")
  ) {
    return "dog";
  }

  if (
    species === "cat" ||
    species.includes("кот") ||
    species.includes("кіт") ||
    species.includes("кіш") ||
    species.includes("katz")
  ) {
    return "cat";
  }

  if (!species) {
    return "";
  }

  return "other";
}

function speciesLabel(
  value
) {
  const species =
    normalizeSpecies(
      value
    );

  if (species === "cat") {
    return translateInterfaceText(
      "calendar.detail.cat"
    );
  }

  if (species === "dog") {
    return translateInterfaceText(
      "calendar.detail.dog"
    );
  }

  if (species === "other") {
    return translateInterfaceText(
      "patients.form.otherSpecies"
    );
  }

  return "—";
}

function formatOwnerVisitCount(
  count
) {
  const number =
    Number(count) || 0;

  const forms = {
    uk: {
      one: "візит",
      few: "візити",
      many: "візитів",
      other: "візиту",
    },

    en: {
      one: "visit",
      other: "visits",
    },

    de: {
      one: "Besuch",
      other: "Besuche",
    },

    pl: {
      one: "wizyta",
      few: "wizyty",
      many: "wizyt",
      other: "wizyty",
    },
  }[getInterfaceLanguage()];

  const category =
    new Intl.PluralRules(
      getCalendarLocale()
    ).select(number);

  return `${number} ${
    forms[category] ||
    forms.other
  }`;
}

function askSpecies(current = "dog") {
  const cur = normalizeSpecies(current);

  const raw = prompt(
    "Вид пацієнта:\n1 — пес\n2 — кіт",
    cur === "cat" ? "2" : "1"
  );

  if (raw === null) {
    return null;
  }

  const value = String(raw)
    .trim()
    .toLowerCase();

  if (
    value === "2" ||
    value === "cat" ||
    value.includes("кот") ||
    value.includes("кіт")
  ) {
    return "cat";
  }

  return "dog";
}


// =========================
// Вспомогательные функции модального окна визитов
// =========================
async function openVisitModalForCreate(
  pet = null
) {
  const modal = $("#visitModal");

    await loadAppointmentTemplatesApi();

  const visitTemplateInput =
    document.getElementById(
      "visitTemplateId"
    );

  if (visitTemplateInput) {
    visitTemplateInput.value = "";
  }

  const templateClearButton =
    document.getElementById(
      "appointmentTemplateClear"
    );

  if (templateClearButton) {
    templateClearButton.hidden = true;
  }

  renderAppointmentTemplatePicker();
  updateAppointmentTemplateSelector();
  bindAppointmentTemplatePicker();
  bindAppointmentTemplateDrawer();

  delete modal.dataset.visitId;

  const openedFromPatient = Boolean(
    pet?.id || pet?._id
  );

  const petId =
    pet?.id ||
    pet?._id ||
    null;

  modal.dataset.openSource =
    openedFromPatient
      ? "patient"
      : "calendar";

  modal.dataset.patientId =
    petId
      ? String(petId)
      : "";

  // Базовые поля нового визита
  const dateInput = $("#visitDate");
  const noteInput = $("#visitNote");
  const dxInput = $("#visitDx");
  const weightInput = $("#visitWeight");
  const rxInput = $("#visitRx");
  const startTimeInput = $("#visitStartTime");
  const durationInput = $("#visitDuration");

  if (dateInput) {
    dateInput.value = todayISO();
  }

  if (noteInput) {
    noteInput.value = "";
  }

  if (dxInput) {
    dxInput.value = "";
  }

  if (weightInput) {
    weightInput.value =
      pet?.weight_kg ||
      pet?.weight ||
      "";
  }

  if (rxInput) {
    rxInput.value = "";
  }

  if (startTimeInput && !startTimeInput.value) {
    startTimeInput.value = "10:00";
  }

  if (durationInput && !durationInput.value) {
    durationInput.value = "60";
  }

  // Пациент
  const patientSelect =
    $("#visitPatientSelect");

  const patientSearch =
    $("#visitPatientSearch");

  const patientResults =
    $("#visitPatientResults");

  const modalSub =
    $("#visitModalSub");

  const patientBlock =
    $("#visitPatientBlock");

  if (openedFromPatient) {
    state.selectedPet = pet;
    state.selectedPetId =
      String(petId);

    if (patientSelect) {
      patientSelect.value =
        String(petId);
    }

    if (patientSearch) {
      patientSearch.value =
        pet?.name || "";
    }

    if (patientResults) {
      patientResults.innerHTML = "";
    }

    if (modalSub) {
      modalSub.textContent =
        `${escapeHtml(translateInterfaceText("calendar.detail.patient.2"))} ${pet?.name || "—"}`;
    }

    if (patientBlock) {
      patientBlock.style.display = "none";
    }
  } else {
    state.selectedPet = null;
    state.selectedPetId = null;

    if (patientSelect) {
      patientSelect.value = "";
    }

    if (patientSearch) {
      patientSearch.value = "";
    }

    if (patientResults) {
      patientResults.innerHTML = "";
    }

    if (modalSub) {
      modalSub.textContent =
        translateInterfaceText("calendar.detail.select.a.patient");
    }

    if (patientBlock) {
      patientBlock.style.display = "block";
    }
  }

  // Быстрое создание пациента
    const quickBox =
    $("#visitNewPatientBox");

  if (quickBox) {
    quickBox.style.display =
      "none";
  }

  const btnCreatePatientFromVisit =
    $("#btnCreatePatientFromVisit");

  if (btnCreatePatientFromVisit) {
    btnCreatePatientFromVisit.onclick =
      () => {
        const box =
          $("#visitNewPatientBox");

        if (!box) {
          console.error(
            "Не знайдено #visitNewPatientBox"
          );

          return;
        }

        const isHidden =
          box.style.display ===
            "none" ||
          !box.style.display;

        box.style.display =
          isHidden
            ? "block"
            : "none";

        if (isHidden) {
          bindUaPhoneInput(
            $("#visitNewOwnerPhone")
          );

          setTimeout(
            () => {
              $("#visitNewOwnerName")
                ?.focus();
            },
            50
          );
        }
      };
  }

  const visitNewPatientSave =
  $("#visitNewPatientCreate");

  if (visitNewPatientSave) {
    visitNewPatientSave.onclick =
      async (event) => {
        event.preventDefault();
        event.stopPropagation();

        const ownerName =
  String(
    $("#visitNewOwnerName")
      ?.value || ""
  ).trim();

const ownerPhone =
  String(
    $("#visitNewOwnerPhone")
      ?.value || ""
  ).trim();

const ownerNote =
  String(
    $("#visitNewOwnerNote")
      ?.value || ""
  ).trim();

const petName =
  String(
    $("#visitNewPetName")
      ?.value || ""
  ).trim();

        const species =
          String(
            $("#visitNewPetSpecies")
              ?.value || ""
          ).trim();

        const breed =
          String(
            getCalendarBreedValue($("#visitNewPetBreed")
              ?.value) || ""
          ).trim();

        const age =
          String(
            $("#visitNewPetAge")
              ?.value || ""
          ).trim();

        const weight =
          String(
            $("#visitNewPetWeight")
              ?.value || ""
          ).trim();

        if (!ownerName) {
          alert(
            translateInterfaceText("calendar.detail.enter.the.owner.s.full.name")
          );

          $("#visitNewOwnerName")
            ?.focus();

          return;
        }

        if (!ownerPhone) {
          alert(
            translateInterfaceText("calendar.detail.enter.the.owner.s.phone.number")
          );

          $("#visitNewOwnerPhone")
            ?.focus();

          return;
        }

        if (
          !isValidUaPhone(
            ownerPhone
          )
        ) {
          alert(
            translateInterfaceText("calendar.detail.the.phone.number.must.contain.exactly.12.digits.in.the.format.380.xx.xxx.xx.xx")
          );

          $("#visitNewOwnerPhone")
            ?.focus();

          return;
        }

        if (!petName) {
          alert(
            translateInterfaceText("calendar.detail.enter.the.patient.s.name")
          );

          $("#visitNewPetName")
            ?.focus();

          return;
        }

        if (!species) {
          alert(
            translateInterfaceText("calendar.detail.select.the.animal.species")
          );

          $("#visitNewPetSpecies")
            ?.focus();

          return;
        }

        const oldText =
          visitNewPatientSave
            .textContent ||
          translateInterfaceText("calendar.detail.create.patient");

        visitNewPatientSave.disabled =
          true;

        visitNewPatientSave.textContent =
          translateInterfaceText("calendar.detail.creating.2");

        try {
          const owner =
            await createOwner({
              name:
                ownerName,

              phone:
                formatUaPhone(
                  ownerPhone
                ),

              email:
                "",

              telegram:
                "",

              note:
                ownerNote,
            });

          if (!owner?.id) {
            throw new Error(
              translateInterfaceText("calendar.detail.the.owner.was.not.created")
            );
          }

          const patient =
  await createPatientApi({
    owner_id:
      owner.id,

    name:
      petName,

    species,

    breed,

    age,

    weight_kg:
      weight,

    sex,

    neutered,

    vaccination_status:
      vaccinationStatus,

    notes:
      "",
  });

          if (!patient?.id) {
            throw new Error(
              translateInterfaceText("calendar.detail.the.patient.was.not.created")
            );
          }

          state.selectedPet =
            patient;

          state.selectedPetId =
            String(
              patient.id
            );

          const patientSelect =
            $("#visitPatientSelect");

          if (patientSelect) {
            let option =
              patientSelect.querySelector(
                `option[value="${CSS.escape(
                  String(patient.id)
                )}"]`
              );

            if (!option) {
              option =
                document.createElement(
                  "option"
                );

              option.value =
                String(patient.id);

              option.textContent =
                `${patient.name} · ${owner.name}`;

              patientSelect.appendChild(
                option
              );
            }

            patientSelect.value =
              String(patient.id);
          }

          const searchInput =
            $("#visitPatientSearch");

          if (searchInput) {
            searchInput.value =
              `${patient.name} · ${owner.name}`;
          }

          const modalSub =
            $("#visitModalSub");

          if (modalSub) {
            modalSub.textContent =
              `${escapeHtml(translateInterfaceText("calendar.detail.patient.2"))} ${patient.name}`;
          }

          await loadOwners();
          await loadPatientsApi();

          const box =
            $("#visitNewPatientBox");

          if (box) {
            box.style.display =
              "none";
          }

          [
            "#visitNewOwnerName",
            "#visitNewOwnerPhone",
            "#visitNewOwnerNote",
            "#visitNewPetName",
            "#visitNewPetBreed",
            "#visitNewPetAge",
            "#visitNewPetWeight",
          ].forEach(
            (selector) => {
              const input =
                $(selector);

              if (input) {
                input.value =
                  "";
              }
            }
          );

          const speciesInput =
            $("#visitNewPetSpecies");

          if (speciesInput) {
            speciesInput.value =
              "";
          }

          alert(
  owner._existingPhoneMatch
    ? (
        (translateInterfaceText("calendar.detail.the.phone.number.was.already.in.the.database") + " ") +
        translateInterfaceText("calendar.detail.the.patient.has.been.added.to.the.existing.owner")
      )
    : (
        (translateInterfaceText("calendar.detail.the.owner.and.patient.have.been.created") + " ") +
        translateInterfaceText("calendar.detail.now.fill.in.the.appointment.details.and.save.the.visit")
      )
);
        } catch (error) {
          console.error(
            "Помилка швидкого створення пацієнта:",
            error
          );

          alert(
            calendarErrorMessage(error?.message, translateInterfaceText("calendar.detail.could.not.create.the.patient"))
          );
        } finally {
          visitNewPatientSave.disabled =
            false;

          visitNewPatientSave.textContent =
            oldText;
        }
      };
  }

  // Ветеринар
    // Ветеринар — только врачи,
  // работающие в выбранное время
  const staffSelect =
    $("#visitStaff");

  const allStaff =
    await loadStaffApi();

  const availableDoctors =
    (
      Array.isArray(allStaff)
        ? allStaff
        : []
    ).filter((doctor) => {
      if (
        doctor?.is_active === false
      ) {
        return false;
      }

      const role =
        String(
          doctor?.role || ""
        )
          .trim()
          .toLowerCase();

      return ![
        "assistant",
        "admin",
      ].includes(role);
    });

  const visitTimeToMinutes =
    (value) => {
      const parts =
        String(value || "")
          .slice(0, 5)
          .split(":")
          .map(Number);

      if (
        parts.length !== 2 ||
        !Number.isFinite(parts[0]) ||
        !Number.isFinite(parts[1])
      ) {
        return null;
      }

      return (
        parts[0] * 60 +
        parts[1]
      );
    };

  let staffRefreshRequestId = 0;

  const refreshVisitStaffSelect =
    async (
      showAll = false
    ) => {
      if (!staffSelect) {
        return;
      }

      const requestId =
        ++staffRefreshRequestId;

      const previousStaffId =
        String(
          staffSelect.value || ""
        ).startsWith("__")
          ? ""
          : String(
              staffSelect.value || ""
            );

      const selectedDate =
        String(
          dateInput?.value ||
          todayISO()
        ).trim();

      const selectedStartTime =
        String(
          startTimeInput?.value ||
          "10:00"
        ).trim();

      const selectedDuration =
        Math.max(
          1,
          Number(
            durationInput?.value ||
            60
          ) || 60
        );

      const appointmentStart =
        visitTimeToMinutes(
          selectedStartTime
        );

      const appointmentEnd =
        appointmentStart === null
          ? null
          : (
              appointmentStart +
              selectedDuration
            );

      staffSelect.disabled = true;

      staffSelect.innerHTML = `
        <option value="">
          ${escapeHtml(translateInterfaceText("calendar.detail.loading.schedule"))}
        </option>
      `;

      const schedule =
        await loadStaffScheduleApi(
          selectedDate
        );

      if (
        requestId !==
        staffRefreshRequestId
      ) {
        return;
      }

      const scheduleByStaff =
        new Map(
          (
            Array.isArray(schedule)
              ? schedule
              : []
          ).map((row) => [
            String(row.staff_id),
            row,
          ])
        );

      const doctorsWithSchedule =
        availableDoctors.map(
          (doctor) => {
            const scheduleRow =
              scheduleByStaff.get(
                String(doctor.id)
              ) || null;

            const shiftStart =
              String(
                scheduleRow
                  ?.start_time ||
                ""
              ).slice(0, 5);

            const shiftEnd =
              String(
                scheduleRow
                  ?.end_time ||
                ""
              ).slice(0, 5);

            const shiftStartMinutes =
              visitTimeToMinutes(
                shiftStart
              );

            const shiftEndMinutes =
              visitTimeToMinutes(
                shiftEnd
              );

            const isOnShift =
              Boolean(
                scheduleRow &&
                scheduleRow
                  .is_active !== false &&
                appointmentStart !==
                  null &&
                appointmentEnd !==
                  null &&
                appointmentEnd <=
                  24 * 60 &&
                shiftStartMinutes !==
                  null &&
                shiftEndMinutes !==
                  null &&
                appointmentStart >=
                  shiftStartMinutes &&
                appointmentEnd <=
                  shiftEndMinutes
              );

            return {
              doctor,
              shiftStart,
              shiftEnd,
              isOnShift,
            };
          }
        );

      const visibleDoctors =
        showAll
          ? doctorsWithSchedule
          : doctorsWithSchedule.filter(
              (item) =>
                item.isOnShift
            );

      const canShowAll =
        typeof isOwnerOrAdmin ===
          "function" &&
        isOwnerOrAdmin();

      staffSelect.innerHTML = `
        <option value="">
          ${
            visibleDoctors.length
              ? translateInterfaceText("calendar.detail.select.a.veterinarian")
              : (
                  showAll
                    ? translateInterfaceText("calendar.detail.no.veterinarians.found")
                    : translateInterfaceText("calendar.detail.no.veterinarians.are.on.shift.at.this.time")
                )
          }
        </option>

        ${visibleDoctors
          .map((item) => {
            const doctor =
              item.doctor;

            const shiftLabel =
              item.shiftStart &&
              item.shiftEnd
                ? (
                    `${item.shiftStart}` +
                    `–${item.shiftEnd}`
                  )
                : translateInterfaceText("calendar.detail.off.shift.2");

            return `
              <option
                value="${escapeHtml(
                  String(doctor.id)
                )}"
              >
                ${escapeHtml(
                  doctor.name ||
                  translateInterfaceText("calendar.detail.veterinarian")
                )}
                ·
                ${escapeHtml(
                  shiftLabel
                )}
              </option>
            `;
          })
          .join("")}

        ${
          canShowAll &&
          !showAll
            ? `
              <option
                value="__show_all__"
              >
                ${escapeHtml(translateInterfaceText("calendar.detail.show.all.veterinarians"))}
              </option>
            `
            : ""
        }
      `;

      const previousDoctorExists =
        visibleDoctors.some(
          (item) =>
            String(
              item.doctor.id
            ) === previousStaffId
        );

      staffSelect.value =
        previousDoctorExists
          ? previousStaffId
          : "";

      staffSelect.disabled = false;

      staffSelect.onchange =
        () => {
          if (
            staffSelect.value ===
            "__show_all__"
          ) {
            refreshVisitStaffSelect(
              true
            );
          }
        };
    };

  const refreshDoctorsByVisitTime =
    () => {
      refreshVisitStaffSelect(
        false
      );
    };

  if (dateInput) {
    dateInput.onchange =
      refreshDoctorsByVisitTime;
  }

  if (startTimeInput) {
    startTimeInput.onchange =
      refreshDoctorsByVisitTime;
  }

  if (durationInput) {
    durationInput.onchange =
      refreshDoctorsByVisitTime;
  }

  await refreshVisitStaffSelect(
    false
  );


  // Закрытие модального окна
  const closeThisVisitModal = () => {
    document.removeEventListener(
      "keydown",
      handleEscClose
    );

    closeVisitModal();
  };

  const handleEscClose = (event) => {
    if (event.key === "Escape") {
      closeThisVisitModal();
    }
  };

  // На случай повторного открытия удаляем
  // старый обработчик ESC этой модалки
  if (
    window.__visitModalEscHandler
  ) {
    document.removeEventListener(
      "keydown",
      window.__visitModalEscHandler
    );
  }

  window.__visitModalEscHandler =
    handleEscClose;

  document.addEventListener(
    "keydown",
    handleEscClose
  );

  const allCloseElements =
    modal.querySelectorAll(
      [
        ".close",
        ".btn-close",
        "[data-close]",
        ".cancel-btn",
        "#btnCancelVisit",
        ".pugVisitClose",
      ].join(", ")
    );

  allCloseElements.forEach((button) => {
    button.onclick = (event) => {
      event.preventDefault();
      event.stopPropagation();

      closeThisVisitModal();
    };
  });

  // Закрытие по клику на затемнение,
  // но не по клику внутри формы
  modal.onclick = (event) => {
    if (event.target === modal) {
      closeThisVisitModal();
      return;
    }

    const closeTarget =
      event.target.closest(
        [
          ".close-modal",
          ".pugVisitClose",
          "[data-close]",
          "#btnCancelVisit",
        ].join(", ")
      );

    if (closeTarget) {
      event.preventDefault();
      event.stopPropagation();

      closeThisVisitModal();
    }
  };

  // После сохранения не накапливаем
  // повторные submit-обработчики
  const openedPetId =
    petId
      ? String(petId)
      : null;

  const form =
    modal.querySelector("form");

  if (form) {
    form.onsubmit = () => {
      setTimeout(() => {
        closeThisVisitModal();

        if (
          openedPetId &&
          typeof renderVisits === "function"
        ) {
          renderVisits(openedPetId);
        }
      }, 250);
    };
  }

  // Открытие модального окна
  modal.style.cssText = "";
  modal.style.display = "flex";

  modal.classList.add("open");

  modal.setAttribute(
    "aria-hidden",
    "false"
  );

  document.body.classList.add(
    "medcardModalIsOpen"
  );
}
// =========================
// PATIENT UI — Управление карточкой животного
// =========================
// subdivision
function initPatientUI() {
  $("#btnBackOwner")
    ?.addEventListener(
      "click",
      () => {
        if (
          state.selectedOwnerId
        ) {
          openOwner(
            state.selectedOwnerId
          );
        } else {
          setHash(
            "owners"
          );
        }
      }
    );


  $("#btnAddVisit")
    ?.addEventListener(
      "click",
      () => {
        const pet =
          state.selectedPet;

        if (!pet) {
          showSettingsMessage(
            translateInterfaceText(
              "calendar.detail.no.patient.selected"
            )
          );

          return;
        }

        openVisitModalForCreate(
          pet
        );
      }
    );


  $("#visitsList")
    ?.addEventListener(
      "click",
      async (event) => {
        const deleteButton =
          event.target.closest(
            "[data-del-visit]"
          );

        if (deleteButton) {
          event.preventDefault();
          event.stopPropagation();

          const visitId =
            deleteButton.dataset
              .delVisit;

          if (!visitId) return;

          openDeleteModal(
            `
              <b>
                ${escapeHtml(
                  translateInterfaceText(
                    "patients.card.visits.deleteVisit"
                  )
                )}
              </b>

              <br><br>

              ${escapeHtml(
                translateInterfaceText(
                  "patients.card.visits.deleteText"
                )
              )}
            `,
            async () => {
              try {
                const deleted =
                  await deleteVisitApi(
                    visitId
                  );

                if (!deleted) {
                  showSettingsMessage(
                    translateInterfaceText(
                      "patients.card.visits.deleteFailed"
                    )
                  );

                  return;
                }

                if (
                  state.selectedPetId
                ) {
                  await renderVisits(
                    state.selectedPetId
                  );
                }
              } catch (error) {
                console.error(
                  "Patient visit deletion failed:",
                  error
                );

                showSettingsMessage(
                  translateInterfaceText(
                    "patients.card.visits.deleteFailed"
                  )
                );
              }
            }
          );

          return;
        }


        const editButton =
          event.target.closest(
            "[data-edit-visit]"
          );

        if (editButton) {
          event.preventDefault();
          event.stopPropagation();

          const visitId =
            editButton.dataset
              .editVisit;

          if (visitId) {
            await openVisitModalForEdit(
              visitId
            );
          }

          return;
        }


        const item =
          event.target.closest(
            ".item"
          );

        if (!item) return;

        const visitId =
          item.dataset.openVisit;

        if (visitId) {
          openVisit(
            visitId
          );
        }
      }
    );


  if (
    !state.visitFilesUiBound &&
    typeof initVisitFilesUI ===
      "function"
  ) {
    initVisitFilesUI();
  }
}


function initVisitFilesUI() {
  if (
    state.visitFilesUiBound
  ) {
    return;
  }


  Object.assign(
    SETTINGS_INTERFACE_TEXT,
    {
      "Спочатку відкрийте візит, щоб прикріпити файли.": {
        en: "Open a visit first to attach files.",
        de: "Öffnen Sie zuerst einen Besuch, um Dateien anzuhängen.",
        pl: "Najpierw otwórz wizytę, aby dołączyć pliki.",
      },

      "Не вдалося завантажити файли.": {
        en: "Could not upload the files.",
        de: "Die Dateien konnten nicht hochgeladen werden.",
        pl: "Nie udało się przesłać plików.",
      },

      "Сервер не повернув файли.": {
        en: "The server did not return the uploaded files.",
        de: "Der Server hat die hochgeladenen Dateien nicht zurückgegeben.",
        pl: "Serwer nie zwrócił przesłanych plików.",
      },
    }
  );


  document.addEventListener(
    "change",
    async (event) => {
      const input =
        event.target?.closest
          ? event.target.closest(
              "#visitFiles"
            )
          : null;

      if (!input) return;


      try {
        const visitId =
          state.selectedVisitId;

        if (!visitId) {
          showSettingsMessage(
            getSettingsInterfaceText(
              "Спочатку відкрийте візит, щоб прикріпити файли."
            )
          );

          return;
        }

        const chosen =
          Array.from(
            input.files ||
            []
          );

        if (!chosen.length) {
          return;
        }


        const formData =
          new FormData();

        chosen.forEach(
          (file) => {
            formData.append(
              "files",
              file
            );
          }
        );


        const response =
          await fetch(
            "/api/upload",
            {
              method:
                "POST",

              credentials:
                "include",

              body:
                formData,
            }
          );

        const responseText =
          await response.text();

        let json = null;

        try {
          json =
            responseText
              ? JSON.parse(
                  responseText
                )
              : null;
        } catch {
          json = null;
        }


        if (
          !response.ok ||
          json?.ok !== true
        ) {
          throw new Error(
            json?.error ||
            getSettingsInterfaceText(
              "Не вдалося завантажити файли."
            )
          );
        }


        const savedMeta =
          Array.isArray(
            json.files
          )
            ? json.files
            : (
                Array.isArray(
                  json.data
                )
                  ? json.data
                  : []
              );

        if (
          !savedMeta.length
        ) {
          throw new Error(
            getSettingsInterfaceText(
              "Сервер не повернув файли."
            )
          );
        }


        upsertFilesFromServerMeta(
          savedMeta
        );

        const fileIds =
          savedMeta
            .map(
              (file) =>
                file?.stored_name
                  ? fileIdFromStored(
                      file.stored_name
                    )
                  : null
            )
            .filter(
              Boolean
            );


        try {
          linkFilesToVisit(
            visitId,
            fileIds
          );

          if (
            typeof renderVisitFiles ===
            "function"
          ) {
            renderVisitFiles(
              visitId
            );
          }
        } catch (error) {
          console.warn(
            "Local file attachment failed:",
            error
          );
        }
      } catch (error) {
        console.error(
          "Visit file upload failed:",
          error
        );

        showSettingsMessage(
          getSettingsSafeErrorText(
            error,
            "Не вдалося завантажити файли."
          )
        );

        if (
          state.selectedVisitId &&
          typeof renderVisitFiles ===
            "function"
        ) {
          renderVisitFiles(
            state.selectedVisitId
          );
        }
      } finally {
        input.value = "";
      }
    }
  );


  state.visitFilesUiBound =
    true;
}
