function visitModalHasChanges() {
  const modal =
    $("#visitModal");

  if (!modal) {
    return false;
  }

  const initialState =
    modal.dataset.initialState ||
    "";

  return (
    JSON.stringify(
      getVisitModalState()
    ) !==
    initialState
  );
}

function requestCloseVisitModal() {
  const modal =
    $("#visitModal");

  if (
    !modal ||
    !modal.classList.contains(
      "open"
    )
  ) {
    return;
  }

  if (
    !visitModalHasChanges()
  ) {
    closeVisitModal();
    return;
  }

  openDeleteModal(
    (
      translateInterfaceText("calendar.detail.appointment.changes.have.not.been.saved.yet")
    ),
    () => {
      closeVisitModal();
    },
    "unsaved"
  );
}

