// Функция инициализации настроек: темы, язык

const DEFAULT_CLINIC_PROFILE = {
  id: "",
  name: "Ветеринарна клініка",
  subtitle: "Ветеринарна клініка",
  logo_url: "",
  phone: "",
  address: "",
  website: "",
  document_accent_color: "#9346E8",
  doctor_signature_url: "",
  clinic_stamp_url: "",
  document_footer: "Коли важливо — ми поруч.",
};

function getClinicProfile() {
  return {
    ...DEFAULT_CLINIC_PROFILE,
    ...(state.clinicProfile || {}),
  };
}

async function loadClinicProfileApi() {
  try {
    const response = await fetch(
      "/api/organization/profile",
      {
        method: "GET",
        credentials: "include",
        headers: {
          Accept: "application/json",
          ...getOrgHeaders(),
        },
      }
    );

    const text = await response.text();

    let json = null;

    try {
      json = text ? JSON.parse(text) : null;
    } catch {
      json = null;
    }

    if (!response.ok || !json?.ok) {
      throw new Error(
        json?.error ||
        `Помилка завантаження профілю клініки HTTP ${response.status}`
      );
    }

    const profile = {
      ...DEFAULT_CLINIC_PROFILE,
      ...(json.data || {}),
    };

    state.clinicProfile = profile;

    return profile;
  } catch (error) {
    console.error("loadClinicProfileApi failed:", error);

    state.clinicProfile = {
      ...DEFAULT_CLINIC_PROFILE,
      name:
        state.me?.clinic_name ||
        sessionStorage.getItem("pug_active_clinic_name") ||
        DEFAULT_CLINIC_PROFILE.name,
    };

    return state.clinicProfile;
  }
}

async function saveClinicProfileApi(
  payload = {}
) {
  Object.assign(
    SETTINGS_INTERFACE_TEXT,
    {
      "Не вдалося зберегти налаштування клініки.": {
        en: "Could not save the clinic settings.",
        de: "Die Klinikeinstellungen konnten nicht gespeichert werden.",
        pl: "Nie udało się zapisać ustawień kliniki.",
      },
    }
  );

  try {
    const response =
      await fetch(
        "/api/organization/profile",
        {
          method: "PUT",

          credentials:
            "include",

          headers: {
            "Content-Type":
              "application/json",

            Accept:
              "application/json",

            ...getOrgHeaders(),
          },

          body:
            JSON.stringify(
              payload
            ),
        }
      );

    const text =
      await response.text();

    let json = null;

    try {
      json =
        text
          ? JSON.parse(text)
          : null;
    } catch {
      json = null;
    }

    if (
      !response.ok ||
      !json?.ok
    ) {
      throw new Error(
        json?.error ||
        `Clinic profile HTTP ${response.status}`
      );
    }

    state.clinicProfile = {
      ...DEFAULT_CLINIC_PROFILE,
      ...(json.data || {}),
    };

    if (state.me) {
      state.me.clinic_name =
        state.clinicProfile.name ||
        state.me.clinic_name;
    }

    sessionStorage.setItem(
      "pug_active_clinic_name",
      state.clinicProfile.name ||
      getSettingsInterfaceText(
        "Клініка"
      )
    );

    return state.clinicProfile;
  } catch (error) {
    console.error(
      "saveClinicProfileApi failed:",
      error
    );

    showSettingsMessage(
      getSettingsSafeErrorText(
        error,
        "Не вдалося зберегти налаштування клініки."
      )
    );

    return null;
  }
}


async function uploadClinicBrandFile(
  file
) {
  Object.assign(
    SETTINGS_INTERFACE_TEXT,
    {
      "Файл не вибрано": {
        en: "No file selected",
        de: "Keine Datei ausgewählt",
        pl: "Nie wybrano pliku",
      },

      "Дозволені лише PNG, JPG або WEBP": {
        en: "Only PNG, JPG or WEBP files are allowed",
        de: "Nur PNG-, JPG- oder WEBP-Dateien sind erlaubt",
        pl: "Dozwolone są tylko pliki PNG, JPG lub WEBP",
      },

      "Максимальний розмір файлу — 5 МБ": {
        en: "Maximum file size is 5 MB",
        de: "Die maximale Dateigröße beträgt 5 MB",
        pl: "Maksymalny rozmiar pliku to 5 MB",
      },

      "Не вдалося завантажити файл.": {
        en: "Could not upload the file.",
        de: "Die Datei konnte nicht hochgeladen werden.",
        pl: "Nie udało się przesłać pliku.",
      },

      "Сервер не повернув завантажений файл": {
        en: "The server did not return the uploaded file",
        de: "Der Server hat die hochgeladene Datei nicht zurückgegeben",
        pl: "Serwer nie zwrócił przesłanego pliku",
      },

      "Сервер не повернув адресу файлу": {
        en: "The server did not return the file URL",
        de: "Der Server hat keine Datei-URL zurückgegeben",
        pl: "Serwer nie zwrócił adresu pliku",
      },
    }
  );


  if (!file) {
    throw new Error(
      getSettingsInterfaceText(
        "Файл не вибрано"
      )
    );
  }

  const allowedTypes = [
    "image/png",
    "image/jpeg",
    "image/webp",
  ];

  if (
    !allowedTypes.includes(
      file.type
    )
  ) {
    throw new Error(
      getSettingsInterfaceText(
        "Дозволені лише PNG, JPG або WEBP"
      )
    );
  }

  if (
    file.size >
    5 * 1024 * 1024
  ) {
    throw new Error(
      getSettingsInterfaceText(
        "Максимальний розмір файлу — 5 МБ"
      )
    );
  }


  const formData =
    new FormData();

  formData.append(
    "files",
    file
  );

  const response =
    await fetch(
      "/api/upload",
      {
        method: "POST",

        credentials:
          "include",

        headers: {
          ...getOrgHeaders(),
        },

        body:
          formData,
      }
    );

  const text =
    await response.text();

  let json = null;

  try {
    json =
      text
        ? JSON.parse(text)
        : null;
  } catch {
    json = null;
  }

  if (
    !response.ok ||
    !json?.ok
  ) {
    throw new Error(
      json?.error ||
      getSettingsInterfaceText(
        "Не вдалося завантажити файл."
      )
    );
  }


  const uploaded =
    json.files?.[0] ||
    json.data?.[0] ||
    json.data ||
    null;

  if (!uploaded) {
    throw new Error(
      getSettingsInterfaceText(
        "Сервер не повернув завантажений файл"
      )
    );
  }

  const rawUrl =
    uploaded.url ||
    uploaded.path ||
    uploaded.href ||
    uploaded.file_url ||
    "";

  if (!rawUrl) {
    throw new Error(
      getSettingsInterfaceText(
        "Сервер не повернув адресу файлу"
      )
    );
  }

  return new URL(
    rawUrl,
    window.location.origin
  ).toString();
}
