const AUDIT_FILTER_ACTIONS =
  Object.keys(
    AUDIT_ACTION_LABELS
  );


function normalizeAuditText(
  value
) {
  return String(value || "")
    .replace(/\s+/g, " ")
    .trim();
}


function getAuditInterfaceText(
  sourceText
) {
  const language =
    getInterfaceLanguage();

  const normalizedSource =
    normalizeAuditText(
      sourceText
    );

  const entry =
    Object.entries(
      AUDIT_INTERFACE_TEXT
    ).find(
      ([
        ukrainian,
        translations,
      ]) =>
        [
          ukrainian,
          ...Object.values(
            translations
          ),
        ].some(
          (value) =>
            normalizeAuditText(
              value
            ) ===
            normalizedSource
        )
    );

  if (!entry) {
    return String(
      sourceText ||
      ""
    );
  }

  const [
    ukrainian,
    translations,
  ] = entry;

  return language === "uk"
    ? ukrainian
    : (
        translations[language] ||
        ukrainian
      );
}


function getAuditActionLabel(
  action
) {
  const cleanAction =
    String(action || "")
      .trim();

  const sourceLabel =
    AUDIT_ACTION_LABELS[
      cleanAction
    ];

  return sourceLabel
    ? getAuditInterfaceText(
        sourceLabel
      )
    : (
        cleanAction ||
        getAuditInterfaceText(
          "Подія"
        )
      );
}


function getAuditRoleLabel(
  role
) {
  const value =
    String(role || "")
      .trim()
      .toLowerCase();

  const roles = {
    owner:
      "Власник",

    admin:
      "Адміністратор",

    vet:
      "Ветеринар",

    veterinarian:
      "Ветеринар",

    assistant:
      "Асистент",

    staff:
      "Працівник",

    employee:
      "Працівник",

    system:
      "Система",
  };

  return getAuditInterfaceText(
    roles[value] ||
    role ||
    "Система"
  );
}


function getAuditStructuredText(
  value
) {
  const original =
    String(value || "")
      .trim();

  if (!original) {
    return "";
  }

  const directlyTranslated =
    getAuditInterfaceText(
      original
    );

  if (
    directlyTranslated !==
    original
  ) {
    return directlyTranslated;
  }

  const prefixes = [
    "Візит пацієнта",
    "Оплата візиту",
    "Витрата",
    "Клініка",
    "Послуга",
    "Препарат",
    "Звіт",
  ];

  const matchedPrefix =
    prefixes.find(
      (prefix) =>
        original === prefix ||
        original.startsWith(
          `${prefix} `
        )
    );

  if (!matchedPrefix) {
    return original;
  }

  return (
    getAuditInterfaceText(
      matchedPrefix
    ) +
    original.slice(
      matchedPrefix.length
    )
  );
}


function formatAuditDate(
  value
) {
  if (!value) {
    return "—";
  }

  const date =
    new Date(value);

  if (
    Number.isNaN(
      date.getTime()
    )
  ) {
    return String(value);
  }

  return date.toLocaleString(
    getCalendarLocale(),
    {
      dateStyle: "medium",
      timeStyle: "short",
    }
  );
}


function renderAuditJson(
  value
) {
  if (
    value == null ||
    (
      typeof value ===
        "object" &&
      Object.keys(value)
        .length === 0
    )
  ) {
    return "—";
  }

  try {
    return escapeHtml(
      JSON.stringify(
        value,
        null,
        2
      )
    );
  } catch {
    return escapeHtml(
      String(value)
    );
  }
}


function getAuditPaginationText(
  start,
  end,
  total
) {
  const locale =
    getCalendarLocale();

  const startText =
    Number(start || 0)
      .toLocaleString(
        locale
      );

  const endText =
    Number(end || 0)
      .toLocaleString(
        locale
      );

  const totalText =
    Number(total || 0)
      .toLocaleString(
        locale
      );

  const language =
    getInterfaceLanguage();

  if (language === "en") {
    return (
      `Showing ${startText}–` +
      `${endText} of ${totalText}`
    );
  }

  if (language === "de") {
    return (
      `${startText}–${endText} ` +
      `von ${totalText} angezeigt`
    );
  }

  if (language === "pl") {
    return (
      `Wyświetlono ${startText}–` +
      `${endText} z ${totalText}`
    );
  }

  return (
    `Показано ${startText}–` +
    `${endText} із ${totalText}`
  );
}


async function loadAuditEventsApi(
  filters = {}
) {
  const params =
    new URLSearchParams();

  params.set(
    "limit",
    String(
      AUDIT_EVENTS_PAGE_SIZE
    )
  );

  params.set(
    "offset",
    String(
      Math.max(
        0,
        Number(
          filters.offset
        ) ||
        0
      )
    )
  );

  [
    "action",
    "actor_name",
    "date_from",
    "date_to",
  ].forEach(
    (key) => {
      const value =
        String(
          filters[key] ||
          ""
        ).trim();

      if (value) {
        params.set(
          key,
          value
        );
      }
    }
  );

  const response =
    await fetch(
      `/api/audit-events?${params.toString()}`,
      {
        method: "GET",
        credentials:
          "include",

        headers: {
          Accept:
            "application/json",

          ...getOrgHeaders(),
        },
      }
    );

  const text =
    await response.text();

  let json = null;

  try {
    json = text
      ? JSON.parse(text)
      : null;
  } catch {}

  if (
    !response.ok ||
    json?.ok !== true
  ) {
    throw new Error(
      json?.error ||
      getAuditInterfaceText(
        "Не вдалося завантажити журнал дій."
      )
    );
  }

  return (
    json.data ||
    {
      events: [],
      total: 0,
      limit:
        AUDIT_EVENTS_PAGE_SIZE,
      offset: 0,
    }
  );
}


function renderAuditEventsResult(
  page,
  data
) {
  const results =
    page.querySelector(
      "#auditEventsResult"
    );

  const pagination =
    page.querySelector(
      "#auditEventsPagination"
    );

  if (
    !results ||
    !pagination
  ) {
    return;
  }

  const events =
    Array.isArray(
      data?.events
    )
      ? data.events
      : [];

  const total =
    Math.max(
      0,
      Number(
        data?.total
      ) ||
      0
    );

  const offset =
    Math.max(
      0,
      Number(
        data?.offset
      ) ||
      0
    );

  const limit =
    Math.max(
      1,
      Number(
        data?.limit
      ) ||
      AUDIT_EVENTS_PAGE_SIZE
    );

  if (!events.length) {
    results.innerHTML = `
      <div class="auditEventsEmpty">
        <span>🛡️</span>

        <strong>
          ${escapeHtml(
            getAuditInterfaceText(
              "Подій не знайдено"
            )
          )}
        </strong>

        <p>
          ${escapeHtml(
            getAuditInterfaceText(
              "Спробуйте змінити фільтри або виконайте нову дію у CRM."
            )
          )}
        </p>
      </div>
    `;
  } else {
    const dateLabel =
      getAuditInterfaceText(
        "Дата"
      );

    const userLabel =
      getAuditInterfaceText(
        "Користувач"
      );

    const actionLabel =
      getAuditInterfaceText(
        "Дія"
      );

    const objectLabel =
      getAuditInterfaceText(
        "Обʼєкт"
      );

    const detailsLabel =
      getAuditInterfaceText(
        "Деталі"
      );

    results.innerHTML = `
      <div class="auditEventsTableWrap">
        <table class="auditEventsTable">
          <thead>
            <tr>
              <th>
                ${escapeHtml(
                  dateLabel
                )}
              </th>

              <th>
                ${escapeHtml(
                  userLabel
                )}
              </th>

              <th>
                ${escapeHtml(
                  actionLabel
                )}
              </th>

              <th>
                ${escapeHtml(
                  objectLabel
                )}
              </th>

              <th>
                ${escapeHtml(
                  detailsLabel
                )}
              </th>
            </tr>
          </thead>

          <tbody>
            ${
              events
                .map(
                  (event) => {
                    const actorName =
                      event.actor_name ||
                      getAuditInterfaceText(
                        "Система"
                      );

                    const entityLabel =
                      getAuditStructuredText(
                        event.entity_label ||
                        event.entity_type ||
                        "—"
                      );

                    const summary =
                      getAuditStructuredText(
                        event.summary ||
                        getAuditInterfaceText(
                          "Без опису"
                        )
                      );

                    return `
                      <tr>
                        <td
                          data-label="${escapeHtml(
                            dateLabel
                          )}"
                        >
                          <time>
                            ${escapeHtml(
                              formatAuditDate(
                                event.created_at
                              )
                            )}
                          </time>
                        </td>

                        <td
                          data-label="${escapeHtml(
                            userLabel
                          )}"
                        >
                          <strong>
                            ${escapeHtml(
                              actorName
                            )}
                          </strong>

                          <small>
                            ${escapeHtml(
                              getAuditRoleLabel(
                                event.actor_role
                              )
                            )}
                          </small>
                        </td>

                        <td
                          data-label="${escapeHtml(
                            actionLabel
                          )}"
                        >
                          <span class="auditActionBadge">
                            ${escapeHtml(
                              getAuditActionLabel(
                                event.action
                              )
                            )}
                          </span>

                          <small>
                            ${escapeHtml(
                              event.action ||
                              "—"
                            )}
                          </small>
                        </td>

                        <td
                          data-label="${escapeHtml(
                            objectLabel
                          )}"
                        >
                          <strong>
                            ${escapeHtml(
                              entityLabel
                            )}
                          </strong>

                          <small>
                            ${escapeHtml(
                              event.entity_id ||
                              "—"
                            )}
                          </small>
                        </td>

                        <td
                          data-label="${escapeHtml(
                            detailsLabel
                          )}"
                        >
                          <details class="auditEventDetails">
                            <summary>
                              ${escapeHtml(
                                getAuditInterfaceText(
                                  "Переглянути"
                                )
                              )}
                            </summary>

                            <div>
                              <p>
                                ${escapeHtml(
                                  summary
                                )}
                              </p>

                              <label>
                                ${escapeHtml(
                                  getAuditInterfaceText(
                                    "До"
                                  )
                                )}
                              </label>

                              <pre>${renderAuditJson(
                                event.before_data
                              )}</pre>

                              <label>
                                ${escapeHtml(
                                  getAuditInterfaceText(
                                    "Після"
                                  )
                                )}
                              </label>

                              <pre>${renderAuditJson(
                                event.after_data
                              )}</pre>

                              <label>
                                ${escapeHtml(
                                  getAuditInterfaceText(
                                    "Метадані"
                                  )
                                )}
                              </label>

                              <pre>${renderAuditJson(
                                event.metadata
                              )}</pre>

                              <footer>
                                IP:
                                ${escapeHtml(
                                  event.ip_address ||
                                  "—"
                                )}
                              </footer>
                            </div>
                          </details>
                        </td>
                      </tr>
                    `;
                  }
                )
                .join("")
            }
          </tbody>
        </table>
      </div>
    `;
  }

  const start =
    total &&
    events.length
      ? offset + 1
      : 0;

  const end =
    offset +
    events.length;

  pagination.innerHTML = `
    <span>
      ${escapeHtml(
        getAuditPaginationText(
          start,
          end,
          total
        )
      )}
    </span>

    <div>
      <button
        type="button"
        id="auditEventsPrevious"
        ${
          offset <= 0
            ? "disabled"
            : ""
        }
      >
        ${escapeHtml(
          getAuditInterfaceText(
            "← Назад"
          )
        )}
      </button>

      <button
        type="button"
        id="auditEventsNext"
        ${
          offset + limit >=
          total
            ? "disabled"
            : ""
        }
      >
        ${escapeHtml(
          getAuditInterfaceText(
            "Далі →"
          )
        )}
      </button>
    </div>
  `;
}
