function normalizeSettingsText(
  value
) {
  return String(value || "")
    .replace(/\s+/g, " ")
    .trim();
}


function getSettingsInterfaceText(
  sourceText
) {
  const language =
    getInterfaceLanguage();

  const normalizedSource =
    normalizeSettingsText(
      sourceText
    );

  const entry =
    Object.entries(
      SETTINGS_INTERFACE_TEXT
    ).find(
      ([
        ukrainian,
        translations,
      ]) =>
        [
          ukrainian,
          ...Object.values(
            translations
          ),
        ].some(
          (value) =>
            normalizeSettingsText(
              value
            ) ===
            normalizedSource
        )
    );

  if (!entry) {
    return String(
      sourceText ||
      ""
    );
  }

  const [
    ukrainian,
    translations,
  ] = entry;

  return language === "uk"
    ? ukrainian
    : (
        translations[language] ||
        ukrainian
      );
}


function formatSettingsDate(
  value,
  options = {}
) {
  if (!value) {
    return "—";
  }

  const date =
    new Date(value);

  if (
    Number.isNaN(
      date.getTime()
    )
  ) {
    return String(value);
  }

  return new Intl.DateTimeFormat(
    getCalendarLocale(),
    options
  ).format(date);
}


function getSettingsSubscriptionStatusText(
  status
) {
  const labels = {
    active:
      "Активна",

    expiring:
      "Закінчується",

    expired:
      "Термін минув",

    paused:
      "Призупинена",

    trial:
      "Тестовий період",

    unconfigured:
      "Не налаштована",
  };

  return getSettingsInterfaceText(
    labels[status] ||
    "Не налаштована"
  );
}


function getSettingsAccessUntilText(
  dateText
) {
  const language =
    getInterfaceLanguage();

  if (language === "en") {
    return `Access until ${dateText}`;
  }

  if (language === "de") {
    return `Zugang bis ${dateText}`;
  }

  if (language === "pl") {
    return `Dostęp do ${dateText}`;
  }

  return `Доступ до ${dateText}`;
}


function getSettingsDaysRemainingText(
  days
) {
  const value =
    Number(days || 0)
      .toLocaleString(
        getCalendarLocale()
      );

  const language =
    getInterfaceLanguage();

  if (language === "en") {
    return `${value} days remaining`;
  }

  if (language === "de") {
    return `${value} Tage verbleibend`;
  }

  if (language === "pl") {
    return `Pozostało dni: ${value}`;
  }

  return `${value} дн. залишилось`;
}


function renderPlatformClinicsList(
  container,
  clinics = []
) {
  if (!container) return;

  if (!clinics.length) {
    container.innerHTML = `
      <div class="platformClinicEmpty">
        ${escapeHtml(
          getSettingsInterfaceText(
            "Клінік ще немає."
          )
        )}
      </div>
    `;

    return;
  }

  container.innerHTML =
    clinics
      .map(
        (clinic) => {
          const subscription =
            clinic.subscription ||
            {};

          const subscriptionStatus =
            subscription.status ||
            "unconfigured";

          const subscriptionLabel =
            getSettingsSubscriptionStatusText(
              subscriptionStatus
            );

          const accessLabel =
            subscription
              .last_access_day
              ? formatSettingsDate(
                  `${subscription.last_access_day}T12:00:00`,
                  {
                    day: "2-digit",
                    month: "2-digit",
                    year: "numeric",
                  }
                )
              : "—";

          const createdAt =
            clinic.created_at
              ? formatSettingsDate(
                  clinic.created_at,
                  {
                    day: "2-digit",
                    month: "short",
                    year: "numeric",
                  }
                )
              : "—";

          const clinicName =
            clinic.name ||
            getSettingsInterfaceText(
              "Клініка"
            );

          const ownerName =
            clinic.owner
              ? (
                  clinic.owner
                    .display_name ||
                  getSettingsInterfaceText(
                    "Власник"
                  )
                )
              : "";

          return `
            <article class="platformClinicItem">
              <div
                class="platformClinicMark"
                data-clinic-theme="${escapeHtml(
                  clinic.theme ||
                  "purple"
                )}"
              >
                🏥
              </div>

              <div class="platformClinicMeta">
                <strong>
                  ${escapeHtml(
                    clinicName
                  )}
                </strong>

                <span>
                  ${
                    clinic.owner
                      ? (
                          `${escapeHtml(
                            ownerName
                          )} · ` +
                          `${escapeHtml(
                            clinic.owner
                              .username ||
                            "—"
                          )}`
                        )
                      : escapeHtml(
                          getSettingsInterfaceText(
                            "Власника не знайдено"
                          )
                        )
                  }
                </span>
              </div>

              <div class="platformClinicState">
                <strong>
                  ${escapeHtml(
                    createdAt
                  )}
                </strong>

                <span
                  class="${
                    clinic.owner
                      ?.is_active ===
                    false
                      ? "inactive"
                      : ""
                  }"
                >
                  ${escapeHtml(
                    getSettingsInterfaceText(
                      clinic.owner
                        ?.is_active ===
                      false
                        ? "Доступ вимкнено"
                        : "Активна"
                    )
                  )}
                </span>
              </div>

              <div class="platformSubscriptionRow">
                <div>
                  <span
                    class="
                      platformSubscriptionBadge
                      ${escapeHtml(
                        subscriptionStatus
                      )}
                    "
                  >
                    ${escapeHtml(
                      subscriptionLabel
                    )}
                  </span>

                  <strong>
                    ${escapeHtml(
                      subscription
                        .last_access_day
                        ? getSettingsAccessUntilText(
                            accessLabel
                          )
                        : getSettingsInterfaceText(
                            "Період ще не задано"
                          )
                    )}
                  </strong>

                  <small>
                    ${escapeHtml(
                      subscription
                        .days_remaining !=
                      null
                        ? getSettingsDaysRemainingText(
                            subscription
                              .days_remaining
                          )
                        : getSettingsInterfaceText(
                            "Ручне керування"
                          )
                    )}
                  </small>
                </div>

                <div class="platformSubscriptionActions">
                  <button
                    type="button"
                    data-subscription-extend="${escapeHtml(
                      String(
                        clinic.id
                      )
                    )}"
                    data-clinic-name="${escapeHtml(
                      clinicName
                    )}"
                  >
                    ${escapeHtml(
                      getSettingsInterfaceText(
                        "+1 місяць"
                      )
                    )}
                  </button>

                  <button
                    type="button"
                    data-subscription-edit="${escapeHtml(
                      String(
                        clinic.id
                      )
                    )}"
                  >
                    ${escapeHtml(
                      getSettingsInterfaceText(
                        "Керувати"
                      )
                    )}
                  </button>
                </div>
              </div>

              <form
                class="platformSubscriptionEditor"
                data-subscription-editor="${escapeHtml(
                  String(
                    clinic.id
                  )
                )}"
                hidden
              >
                <label>
                  <span>
                    ${escapeHtml(
                      getSettingsInterfaceText(
                        "Початок"
                      )
                    )}
                  </span>

                  <input
                    type="date"
                    name="access_starts_on"
                    value="${escapeHtml(
                      subscription
                        .access_starts_on ||
                      ""
                    )}"
                    required
                  >
                </label>

                <label>
                  <span>
                    ${escapeHtml(
                      getSettingsInterfaceText(
                        "Кінець періоду"
                      )
                    )}
                  </span>

                  <input
                    type="date"
                    name="access_ends_on"
                    value="${escapeHtml(
                      subscription
                        .access_ends_on ||
                      ""
                    )}"
                    required
                  >
                </label>

                <label>
                  <span>
                    ${escapeHtml(
                      getSettingsInterfaceText(
                        "Ціна за місяць, ₴"
                      )
                    )}
                  </span>

                  <input
                    type="number"
                    min="0"
                    step="0.01"
                    name="monthly_price"
                    value="${escapeHtml(
                      subscription
                        .monthly_price ??
                      ""
                    )}"
                    placeholder="0"
                  >
                </label>

                <label>
                  <span>
                    ${escapeHtml(
                      getSettingsInterfaceText(
                        "Отримано, ₴"
                      )
                    )}
                  </span>

                  <input
                    type="number"
                    min="0"
                    step="0.01"
                    name="amount"
                    placeholder="${escapeHtml(
                      getSettingsInterfaceText(
                        "Необов’язково"
                      )
                    )}"
                  >
                </label>

                <label class="wide">
                  <span>
                    ${escapeHtml(
                      getSettingsInterfaceText(
                        "Коментар"
                      )
                    )}
                  </span>

                  <input
                    type="text"
                    maxlength="500"
                    name="note"
                    value="${escapeHtml(
                      subscription.note ||
                      ""
                    )}"
                    placeholder="${escapeHtml(
                      getSettingsInterfaceText(
                        "Наприклад, оплата готівкою"
                      )
                    )}"
                  >
                </label>

                <p>
                  ${escapeHtml(
                    getSettingsInterfaceText(
                      "Кінцева дата не включається: період до 01.09 діє по 31.08 включно."
                    )
                  )}
                </p>

                <div class="platformSubscriptionEditorActions">
                  <button type="submit">
                    ${escapeHtml(
                      getSettingsInterfaceText(
                        "Зберегти період"
                      )
                    )}
                  </button>

                  <button
                    type="button"
                    data-subscription-state="${escapeHtml(
                      String(
                        clinic.id
                      )
                    )}"
                    data-next-action="${
                      subscription
                        .stored_status ===
                      "paused"
                        ? "resume"
                        : "pause"
                    }"
                  >
                    ${escapeHtml(
                      getSettingsInterfaceText(
                        subscription
                          .stored_status ===
                        "paused"
                          ? "Відновити"
                          : "Призупинити"
                      )
                    )}
                  </button>

                  <button
                    type="button"
                    data-subscription-history="${escapeHtml(
                      String(
                        clinic.id
                      )
                    )}"
                  >
                    ${escapeHtml(
                      getSettingsInterfaceText(
                        "Історія"
                      )
                    )}
                  </button>
                </div>

                <div
                  class="platformSubscriptionHistory"
                  data-subscription-history-box="${escapeHtml(
                    String(
                      clinic.id
                    )
                  )}"
                  hidden
                ></div>
              </form>
            </article>
          `;
        }
      )
      .join("");
}

