function getSettingsExtendMessage(
  clinicName
) {
  const language =
    getInterfaceLanguage();

  if (language === "en") {
    return `Add one month of access for “${clinicName}”?`;
  }

  if (language === "de") {
    return `Einen Monat Zugang für „${clinicName}“ hinzufügen?`;
  }

  if (language === "pl") {
    return `Dodać jeden miesiąc dostępu dla „${clinicName}”?`;
  }

  return `Додати один місяць доступу для «${clinicName}»?`;
}


function getSettingsSafeErrorText(
  error,
  fallback
) {
  const sourceMessage =
    normalizeSettingsText(
      error?.message
    );

  if (!sourceMessage) {
    return getSettingsInterfaceText(
      fallback
    );
  }

  const translatedMessage =
    getSettingsInterfaceText(
      sourceMessage
    );

  if (
    getInterfaceLanguage() !== "uk" &&
    translatedMessage === sourceMessage
  ) {
    return getSettingsInterfaceText(
      fallback
    );
  }

  return translatedMessage;
}


function showSettingsMessage(
  message
) {
  openDeleteModal(
    escapeHtml(message),
    null,
    "info"
  );
}


function openSettingsConfirmation(
  message,
  confirmText,
  callback,
  danger = false
) {
  openDeleteModal(
    escapeHtml(message),
    callback
  );

  const modal =
    document.getElementById(
      "deleteModal"
    );

  const title =
    modal?.querySelector("h2");

  const icon =
    modal?.querySelector(
      ".deleteIcon"
    );

  const confirmButton =
    document.getElementById(
      "deleteConfirm"
    );

  if (title) {
    title.textContent =
      getSettingsInterfaceText(
        "Підтвердження"
      );
  }

  if (icon) {
    icon.textContent =
      danger ? "!" : "✓";
  }

  if (confirmButton) {
    confirmButton.textContent =
      confirmText;

    confirmButton.classList.remove(
      "primary",
      "btnDanger"
    );

    confirmButton.classList.add(
      danger
        ? "btnDanger"
        : "primary"
    );
  }
}


function getSettingsHistoryActionText(
  action
) {
  const labels = {
    extended: "Продовжено",
    period_set: "Період змінено",
    paused: "Призупинено",
    resumed: "Відновлено",
  };

  return getSettingsInterfaceText(
    labels[action] ||
    action ||
    "—"
  );
}


async function bindPlatformSubscriptionControls(
  list,
  refreshList
) {
  list
    .querySelectorAll(
      "[data-subscription-edit]"
    )
    .forEach((button) => {
      button.addEventListener(
        "click",
        () => {
          const editor =
            list.querySelector(
              `[data-subscription-editor="${CSS.escape(
                button.dataset.subscriptionEdit
              )}"]`
            );

          if (editor) {
            editor.hidden =
              !editor.hidden;
          }
        }
      );
    });


  list
    .querySelectorAll(
      "[data-subscription-extend]"
    )
    .forEach((button) => {
      button.addEventListener(
        "click",
        () => {
          const clinicName =
            button.dataset.clinicName ||
            "—";

          openSettingsConfirmation(
            getSettingsExtendMessage(
              clinicName
            ),
            getSettingsInterfaceText(
              "Додати місяць"
            ),
            async () => {
              button.disabled = true;

              button.textContent =
                getSettingsInterfaceText(
                  "Додаємо…"
                );

              try {
                await platformClinicsRequest(
                  `/${encodeURIComponent(
                    button.dataset.subscriptionExtend
                  )}/subscription`,
                  {
                    method: "POST",

                    body:
                      JSON.stringify({
                        action: "extend",
                        months: 1,
                      }),
                  }
                );

                await refreshList();
              } catch (error) {
                console.error(
                  "Subscription extension failed:",
                  error
                );

                showSettingsMessage(
                  getSettingsSafeErrorText(
                    error,
                    "Не вдалося продовжити підписку."
                  )
                );

                button.disabled = false;

                button.textContent =
                  getSettingsInterfaceText(
                    "+1 місяць"
                  );
              }
            }
          );
        }
      );
    });


  list
    .querySelectorAll(
      ".platformSubscriptionEditor"
    )
    .forEach((form) => {
      const orgId =
        form.dataset.subscriptionEditor;

      form.addEventListener(
        "submit",
        async (event) => {
          event.preventDefault();

          const submit =
            form.querySelector(
              'button[type="submit"]'
            );

          const data =
            new FormData(form);

          if (submit) {
            submit.disabled = true;

            submit.textContent =
              getSettingsInterfaceText(
                "Зберігаємо…"
              );
          }

          try {
            await platformClinicsRequest(
              `/${encodeURIComponent(
                orgId
              )}/subscription`,
              {
                method: "POST",

                body:
                  JSON.stringify({
                    action:
                      "set_period",

                    access_starts_on:
                      data.get(
                        "access_starts_on"
                      ),

                    access_ends_on:
                      data.get(
                        "access_ends_on"
                      ),

                    monthly_price:
                      data.get(
                        "monthly_price"
                      ),

                    amount:
                      data.get(
                        "amount"
                      ),

                    note:
                      data.get(
                        "note"
                      ),
                  }),
              }
            );

            await refreshList();
          } catch (error) {
            console.error(
              "Subscription period save failed:",
              error
            );

            showSettingsMessage(
              getSettingsSafeErrorText(
                error,
                "Не вдалося зберегти період."
              )
            );

            if (submit) {
              submit.disabled = false;

              submit.textContent =
                getSettingsInterfaceText(
                  "Зберегти період"
                );
            }
          }
        }
      );
    });


  list
    .querySelectorAll(
      "[data-subscription-state]"
    )
    .forEach((button) => {
      button.addEventListener(
        "click",
        () => {
          const action =
            button.dataset.nextAction;

          const isPause =
            action === "pause";

          const question =
            isPause
              ? "Призупинити підписку? CRM поки не буде заблокована."
              : "Відновити підписку?";

          const confirmText =
            isPause
              ? "Призупинити"
              : "Відновити";

          openSettingsConfirmation(
            getSettingsInterfaceText(
              question
            ),
            getSettingsInterfaceText(
              confirmText
            ),
            async () => {
              const originalText =
                button.textContent;

              button.disabled = true;

              try {
                await platformClinicsRequest(
                  `/${encodeURIComponent(
                    button.dataset.subscriptionState
                  )}/subscription`,
                  {
                    method: "POST",

                    body:
                      JSON.stringify({
                        action,
                      }),
                  }
                );

                await refreshList();
              } catch (error) {
                console.error(
                  "Subscription status change failed:",
                  error
                );

                showSettingsMessage(
                  getSettingsSafeErrorText(
                    error,
                    "Не вдалося змінити стан підписки."
                  )
                );

                button.disabled = false;

                button.textContent =
                  originalText;
              }
            },
            isPause
          );
        }
      );
    });


  list
    .querySelectorAll(
      "[data-subscription-history]"
    )
    .forEach((button) => {
      button.addEventListener(
        "click",
        async () => {
          const orgId =
            button.dataset.subscriptionHistory;

          const box =
            list.querySelector(
              `[data-subscription-history-box="${CSS.escape(
                orgId
              )}"]`
            );

          if (!box) return;

          if (!box.hidden) {
            box.hidden = true;
            return;
          }

          box.hidden = false;

          box.textContent =
            getSettingsInterfaceText(
              "Завантажуємо історію…"
            );

          try {
            const data =
              await platformClinicsRequest(
                `/${encodeURIComponent(
                  orgId
                )}/subscription/history`
              );

            const events =
              Array.isArray(
                data.events
              )
                ? data.events
                : [];

            box.innerHTML =
              events.length
                ? events
                    .map((item) => {
                      const amount =
                        Number(
                          item.amount
                        );

                      const details =
                        item.amount != null &&
                        Number.isFinite(
                          amount
                        )
                          ? (
                              amount.toLocaleString(
                                getCalendarLocale()
                              ) + " ₴"
                            )
                          : (
                              item.note ||
                              getSettingsInterfaceText(
                                "Без коментаря"
                              )
                            );

                      return `
                        <div>
                          <strong>
                            ${escapeHtml(
                              getSettingsHistoryActionText(
                                item.action
                              )
                            )}
                          </strong>

                          <span>
                            ${escapeHtml(
                              formatSettingsDate(
                                item.created_at,
                                {
                                  dateStyle:
                                    "medium",

                                  timeStyle:
                                    "short",
                                }
                              )
                            )}
                          </span>

                          <small>
                            ${escapeHtml(
                              details
                            )}
                          </small>
                        </div>
                      `;
                    })
                    .join("")
                : getSettingsInterfaceText(
                    "Історія ще порожня."
                  );
          } catch (error) {
            console.error(
              "Subscription history loading failed:",
              error
            );

            box.textContent =
              getSettingsSafeErrorText(
                error,
                "Не вдалося завантажити історію."
              );
          }
        }
      );
    });
}
