function getSettingsCredentialsCopyText(
  created,
  ownerUsername
) {
  const clinicName =
    created.clinic_name ||
    getSettingsInterfaceText(
      "Клініка"
    );

  const username =
    created.owner_username ||
    ownerUsername ||
    "—";

  const temporaryPassword =
    created.temporary_password ||
    "—";

  return [
    `${
      getSettingsInterfaceText(
        "Клініка"
      )
    }: ${clinicName}`,

    `${
      getSettingsInterfaceText(
        "Логін"
      )
    }: ${username}`,

    `${
      getSettingsInterfaceText(
        "Тимчасовий пароль"
      )
    }: ${temporaryPassword}`,
  ].join("\n");
}


async function bindPlatformClinicUI(
  page
) {
  const form =
    page.querySelector(
      "#platformClinicCreateForm"
    );

  const list =
    page.querySelector(
      "#platformClinicsList"
    );

  const counter =
    page.querySelector(
      "#platformClinicsCounter"
    );

  const resultCard =
    page.querySelector(
      "#platformClinicCredentials"
    );

  if (!form || !list) {
    return;
  }


  const refreshList =
    async () => {
      list.innerHTML = `
        <div class="platformClinicEmpty">
          ${escapeHtml(
            getSettingsInterfaceText(
              "Завантажуємо клініки…"
            )
          )}
        </div>
      `;

      try {
        const data =
          await platformClinicsRequest();

        const clinics =
          Array.isArray(
            data.clinics
          )
            ? data.clinics
            : [];

        renderPlatformClinicsList(
          list,
          clinics
        );

        await bindPlatformSubscriptionControls(
          list,
          refreshList
        );

        if (counter) {
          counter.textContent =
            Number(
              data.total ??
              clinics.length
            ).toLocaleString(
              getCalendarLocale()
            );
        }
      } catch (error) {
        console.error(
          "Platform clinics loading failed:",
          error
        );

        list.innerHTML = `
          <div class="platformClinicEmpty error">
            ${escapeHtml(
              getSettingsSafeErrorText(
                error,
                "Не вдалося завантажити клініки."
              )
            )}
          </div>
        `;
      }
    };


  form.addEventListener(
    "submit",
    async (event) => {
      event.preventDefault();

      const submitButton =
        form.querySelector(
          'button[type="submit"]'
        );

      const status =
        form.querySelector(
          "#platformClinicCreateStatus"
        );

      const formData =
        new FormData(form);

      const ownerUsername =
        String(
          formData.get(
            "owner_username"
          ) ||
          ""
        )
          .trim()
          .toLowerCase();

      if (status) {
        status.textContent = "";

        status.classList.remove(
          "error"
        );
      }

      if (submitButton) {
        submitButton.disabled = true;

        submitButton.textContent =
          getSettingsInterfaceText(
            "Створюємо клініку…"
          );
      }

      try {
        const created =
          await platformClinicsRequest(
            "",
            {
              method: "POST",

              body:
                JSON.stringify({
                  name:
                    formData.get(
                      "name"
                    ),

                  subtitle:
                    formData.get(
                      "subtitle"
                    ),

                  phone:
                    formData.get(
                      "phone"
                    ),

                  address:
                    formData.get(
                      "address"
                    ),

                  website:
                    formData.get(
                      "website"
                    ),

                  theme:
                    formData.get(
                      "theme"
                    ),

                  owner_display_name:
                    formData.get(
                      "owner_display_name"
                    ),

                  owner_username:
                    ownerUsername,
                }),
            }
          );


        if (resultCard) {
          resultCard.hidden = false;

          resultCard.dataset.copyText =
            getSettingsCredentialsCopyText(
              created,
              ownerUsername
            );

          resultCard.innerHTML = `
            <div>
              <span>
                ${escapeHtml(
                  getSettingsInterfaceText(
                    "Доступ готовий"
                  )
                )}
              </span>

              <strong>
                ${escapeHtml(
                  created.clinic_name ||
                  getSettingsInterfaceText(
                    "Клініка"
                  )
                )}
              </strong>

              <p>
                ${escapeHtml(
                  getSettingsInterfaceText(
                    "Пароль показується лише зараз. Власник змінить його під час першого входу."
                  )
                )}
              </p>
            </div>

            <dl>
              <div>
                <dt>
                  ${escapeHtml(
                    getSettingsInterfaceText(
                      "Логін"
                    )
                  )}
                </dt>

                <dd>
                  ${escapeHtml(
                    created.owner_username ||
                    ownerUsername ||
                    "—"
                  )}
                </dd>
              </div>

              <div>
                <dt>
                  ${escapeHtml(
                    getSettingsInterfaceText(
                      "Тимчасовий пароль"
                    )
                  )}
                </dt>

                <dd>
                  ${escapeHtml(
                    created.temporary_password ||
                    "—"
                  )}
                </dd>
              </div>
            </dl>

            <button
              class="platformCopyCredentialsButton"
              type="button"
            >
              ${escapeHtml(
                getSettingsInterfaceText(
                  "Скопіювати доступ"
                )
              )}
            </button>
          `;


          resultCard
            .querySelector(
              ".platformCopyCredentialsButton"
            )
            ?.addEventListener(
              "click",
              async (
                copyEvent
              ) => {
                const button =
                  copyEvent.currentTarget;

                try {
                  await navigator
                    .clipboard
                    .writeText(
                      resultCard
                        .dataset
                        .copyText ||
                      ""
                    );

                  button.textContent =
                    getSettingsInterfaceText(
                      "Скопійовано ✓"
                    );
                } catch (error) {
                  console.error(
                    "Credentials copying failed:",
                    error
                  );

                  showSettingsMessage(
                    getSettingsInterfaceText(
                      "Не вдалося скопіювати дані доступу."
                    )
                  );
                }
              }
            );


          resultCard.scrollIntoView({
            behavior: "smooth",
            block: "nearest",
          });
        }


        form.reset();

        const themeField =
          form.querySelector(
            '[name="theme"]'
          );

        if (themeField) {
          themeField.value =
            "purple";
        }

        if (status) {
          status.textContent =
            getSettingsInterfaceText(
              "Клініку створено повністю"
            );
        }

        await refreshList();
      } catch (error) {
        console.error(
          "Platform clinic creation failed:",
          error
        );

        if (status) {
          status.textContent =
            getSettingsSafeErrorText(
              error,
              "Не вдалося створити клініку."
            );

          status.classList.add(
            "error"
          );
        }
      } finally {
        if (submitButton) {
          submitButton.disabled = false;

          submitButton.textContent =
            getSettingsInterfaceText(
              "Створити клініку"
            );
        }
      }
    }
  );


  await refreshList();
}


function getSettingsSubscriptionTitle(
  status
) {
  const labels = {
    active:
      "Підписка активна",

    expiring:
      "Підписка скоро завершується",

    expired:
      "Термін підписки минув",

    paused:
      "Підписку призупинено",

    trial:
      "Тестовий період",

    unconfigured:
      "Період ще не налаштовано",
  };

  return getSettingsInterfaceText(
    labels[status] ||
    labels.unconfigured
  );
}


function getSettingsPaidUntilText(
  dateText
) {
  const language =
    getInterfaceLanguage();

  if (language === "en") {
    return `Access is paid through ${dateText}, inclusive.`;
  }

  if (language === "de") {
    return `Der Zugang ist bis einschließlich ${dateText} bezahlt.`;
  }

  if (language === "pl") {
    return `Dostęp jest opłacony do ${dateText} włącznie.`;
  }

  return `Доступ оплачено до ${dateText} включно.`;
}
async function renderOwnerSubscriptionStatus(
  page
) {
  const container =
    page.querySelector(
      "#ownerSubscriptionStatus"
    );

  if (!container) {
    return;
  }

  try {
    const response =
      await fetch(
        "/api/subscription",
        {
          credentials:
            "include",

          cache:
            "no-store",

          headers: {
            Accept:
              "application/json",
          },
        }
      );

    let payload = null;

    try {
      payload =
        await response.json();
    } catch {
      payload = null;
    }

    if (
      !response.ok ||
      payload?.ok !== true
    ) {
      throw new Error(
        payload?.error ||
        "Не вдалося завантажити підписку."
      );
    }


    const subscription =
      payload.data ||
      {};

    const status =
      subscription.status ||
      "unconfigured";

    const lastDay =
      subscription.last_access_day
        ? formatSettingsDate(
            `${subscription.last_access_day}T12:00:00`,
            {
              day:
                "numeric",

              month:
                "long",

              year:
                "numeric",
            }
          )
        : null;

    const daysRemaining =
      subscription.days_remaining !=
      null
        ? Number(
            subscription.days_remaining
          ).toLocaleString(
            getCalendarLocale()
          )
        : "—";


    container.className =
      `ownerSubscriptionStatus ${status}`;

    container.innerHTML = `
      <div class="ownerSubscriptionIcon">
        🗓️
      </div>

      <div>
        <span>
          ${escapeHtml(
            getSettingsInterfaceText(
              "ДОСТУП ДО DOC.PUG CRM"
            )
          )}
        </span>

        <strong>
          ${escapeHtml(
            getSettingsSubscriptionTitle(
              status
            )
          )}
        </strong>

        <p>
          ${escapeHtml(
            lastDay
              ? getSettingsPaidUntilText(
                  lastDay
                )
              : getSettingsInterfaceText(
                  "Власник платформи ще не вказав оплачений період. CRM продовжує працювати."
                )
          )}
        </p>
      </div>

      <div class="ownerSubscriptionDays">
        <strong>
          ${escapeHtml(
            daysRemaining
          )}
        </strong>

        <span>
          ${escapeHtml(
            getSettingsInterfaceText(
              "днів залишилось"
            )
          )}
        </span>
      </div>
    `;
  } catch (error) {
    console.error(
      "Owner subscription loading failed:",
      error
    );

    container.className =
      "ownerSubscriptionStatus unconfigured";

    container.textContent =
      getSettingsSafeErrorText(
        error,
        "Не вдалося завантажити підписку."
      );
  }
}
