function bindPersonalSettingsUI(page) {
  Object.assign(
    SETTINGS_INTERFACE_TEXT,
    {
      "Не вдалося зберегти тему.": {
        en: "Could not save the theme.",
        de: "Das Design konnte nicht gespeichert werden.",
        pl: "Nie udało się zapisać motywu.",
      },

      "Тему збережено для клініки": {
        en: "Theme saved for the clinic",
        de: "Design für die Klinik gespeichert",
        pl: "Motyw zapisany dla kliniki",
      },
    }
  );


  const savedTheme =
    LS.get(
      "docpug_clinic_theme",
      "purple"
    );

  let selectedTheme =
    document.body.dataset.theme ||
    savedTheme;


  page
    .querySelectorAll(
      "[data-theme-set]"
    )
    .forEach((button) => {
      const theme =
        button.dataset.themeSet;

      button.classList.toggle(
        "active",
        theme === selectedTheme
      );

      button.addEventListener(
        "click",
        () => {
          selectedTheme = theme;

          document.body.dataset.theme =
            theme;

          LS.set(
            "docpug_clinic_theme",
            theme
          );

          page
            .querySelectorAll(
              "[data-theme-set]"
            )
            .forEach((item) => {
              item.classList.remove(
                "active"
              );
            });

          button.classList.add(
            "active"
          );
        }
      );
    });


  const saveThemeButton =
    page.querySelector(
      "#saveClinicThemeButton"
    );

  const saveThemeStatus =
    page.querySelector(
      "#clinicThemeSaveStatus"
    );


  saveThemeButton?.addEventListener(
    "click",
    async () => {
      saveThemeButton.disabled =
        true;

      saveThemeButton.textContent =
        getSettingsInterfaceText(
          "Зберігаємо…"
        );

      if (saveThemeStatus) {
        saveThemeStatus.textContent =
          "";

        saveThemeStatus.classList.remove(
          "error"
        );
      }

      try {
        const response =
          await fetch(
            "/api/organization/theme",
            {
              method: "PUT",

              credentials:
                "include",

              headers: {
                "Content-Type":
                  "application/json",

                Accept:
                  "application/json",
              },

              body:
                JSON.stringify({
                  theme:
                    selectedTheme,
                }),
            }
          );

        const payload =
          await response.json();

        if (
          !response.ok ||
          !payload?.ok
        ) {
          throw new Error(
            payload?.error ||
            "Не вдалося зберегти тему."
          );
        }

        const persistedTheme =
          payload.data?.theme ||
          selectedTheme;

        document.body.dataset.theme =
          persistedTheme;

        LS.set(
          "docpug_clinic_theme",
          persistedTheme
        );

        if (saveThemeStatus) {
          saveThemeStatus.textContent =
            getSettingsInterfaceText(
              "Тему збережено для клініки"
            );
        }
      } catch (error) {
        console.error(
          "Clinic theme save failed:",
          error
        );

        if (saveThemeStatus) {
          saveThemeStatus.textContent =
            getSettingsSafeErrorText(
              error,
              "Не вдалося зберегти тему."
            );

          saveThemeStatus.classList.add(
            "error"
          );
        }
      } finally {
        saveThemeButton.disabled =
          false;

        saveThemeButton.textContent =
          getSettingsInterfaceText(
            "Зберегти тему"
          );
      }
    }
  );


  const languageSelect =
    page.querySelector(
      "#systemLanguageSelect"
    );

  if (languageSelect) {
    languageSelect.value =
      getInterfaceLanguage();

    languageSelect.addEventListener(
      "change",
      () => {
        const selectedLanguage =
          String(
            languageSelect.value ||
            "uk"
          )
            .trim()
            .toLowerCase();

        LS.set(
          "docpug_clinic_lang",
          selectedLanguage
        );

        document.documentElement.lang =
          selectedLanguage;

        window.location.reload();
      }
    );
  }
}


function bindSettingsLogoutUI(page) {
  Object.assign(
    SETTINGS_INTERFACE_TEXT,
    {
      "Ви завершите поточну сесію та повернетеся на сторінку входу.": {
        en: "You will end the current session and return to the sign-in page.",
        de: "Sie beenden die aktuelle Sitzung und kehren zur Anmeldeseite zurück.",
        pl: "Zakończysz bieżącą sesję i wrócisz do strony logowania.",
      },

      "Вихід…": {
        en: "Logging out…",
        de: "Abmeldung läuft…",
        pl: "Wylogowywanie…",
      },

      "Не вдалося завершити сесію. Спробуйте ще раз.": {
        en: "Could not end the session. Please try again.",
        de: "Die Sitzung konnte nicht beendet werden. Bitte versuchen Sie es erneut.",
        pl: "Nie udało się zakończyć sesji. Spróbuj ponownie.",
      },
    }
  );


  const oldLogoutButton =
    page.querySelector(
      "#btnClinicLogout"
    ) ||
    document.getElementById(
      "btn-logout"
    );

  if (!oldLogoutButton) {
    return;
  }

  const logoutButton =
    oldLogoutButton.cloneNode(
      true
    );

  oldLogoutButton.replaceWith(
    logoutButton
  );


  logoutButton.addEventListener(
    "click",
    (event) => {
      event.preventDefault();
      event.stopPropagation();

      openSettingsConfirmation(
        getSettingsInterfaceText(
          "Ви завершите поточну сесію та повернетеся на сторінку входу."
        ),
        getSettingsInterfaceText(
          "Вийти з акаунта"
        ),
        async () => {
          const originalText =
            logoutButton.textContent;

          logoutButton.disabled =
            true;

          logoutButton.textContent =
            getSettingsInterfaceText(
              "Вихід…"
            );

          try {
            const response =
              await fetch(
                "/api/logout",
                {
                  method:
                    "POST",

                  credentials:
                    "include",

                  cache:
                    "no-store",

                  headers: {
                    Accept:
                      "application/json",
                  },
                }
              );

            const text =
              await response.text();

            let json = null;

            try {
              json =
                text
                  ? JSON.parse(
                      text
                    )
                  : null;
            } catch {
              json = null;
            }

            if (
              !response.ok ||
              json?.ok !== true
            ) {
              throw new Error(
                json?.error ||
                `Logout HTTP ${response.status}`
              );
            }

            state.me = null;

            state.clinicProfile =
              null;

            [
              "pug_active_org_id",
              "pug_active_username",
              "pug_active_display_name",
              "pug_active_role",
              "pug_active_clinic_name",
            ].forEach((key) => {
              sessionStorage.removeItem(
                key
              );
            });

            window.location.replace(
              "/?logged_out=1"
            );
          } catch (error) {
            console.error(
              "Logout failed:",
              error
            );

            showSettingsMessage(
              getSettingsSafeErrorText(
                error,
                "Не вдалося завершити сесію. Спробуйте ще раз."
              )
            );

            logoutButton.disabled =
              false;

            logoutButton.textContent =
              originalText;
          }
        }
      );
    }
  );
}
