// VISIT FILES — Отрисовка списка файлов приёма
// =========================
function renderVisitFiles(
  visitId
) {
  Object.assign(
    SETTINGS_INTERFACE_TEXT,
    {
      "Поки файлів немає.": {
        en: "No files yet.",
        de: "Noch keine Dateien vorhanden.",
        pl: "Nie ma jeszcze plików.",
      },

      "Файл": {
        en: "File",
        de: "Datei",
        pl: "Plik",
      },

      "Відкрити": {
        en: "Open",
        de: "Öffnen",
        pl: "Otwórz",
      },

      "Відв’язати": {
        en: "Detach",
        de: "Verknüpfung lösen",
        pl: "Odłącz",
      },

      "байт": {
        en: "bytes",
        de: "Byte",
        pl: "bajtów",
      },
    }
  );


  const wrap =
    document.getElementById(
      "visitFilesList"
    );

  if (!wrap) return;

  const ui =
    (source) =>
      escapeHtml(
        getSettingsInterfaceText(
          source
        )
      );


  const storedFiles =
    LS.get(
      FILES_KEY,
      []
    );

  const allFiles =
    Array.isArray(
      storedFiles
    )
      ? storedFiles
      : [];

  const byId =
    new Map(
      allFiles.map(
        (file) => [
          String(
            file.id
          ),
          file,
        ]
      )
    );

  const ids =
    getFileIdsForVisit(
      visitId
    );


  if (!ids.length) {
    wrap.innerHTML = `
      <div class="hint">
        ${ui(
          "Поки файлів немає."
        )}
      </div>
    `;

    wrap.onclick = null;

    return;
  }


  wrap.innerHTML =
    ids
      .map((id) => {
        const file =
          byId.get(
            String(id)
          );

        if (!file) {
          return "";
        }

        const url =
          file.url ||
          (
            file.stored_name
              ? `/uploads/${file.stored_name}`
              : "#"
          );

        const name =
          file.name ||
          file.stored_name ||
          getSettingsInterfaceText(
            "Файл"
          );

        const size =
          Number(
            file.size
          );

        const sizeText =
          file.size &&
          Number.isFinite(
            size
          )
            ? (
                size.toLocaleString(
                  getCalendarLocale()
                ) +
                " " +
                getSettingsInterfaceText(
                  "байт"
                )
              )
            : "";


        return `
          <div class="fileRow">
            <div class="fileMain">
              <div class="fileName">
                ${escapeHtml(
                  name
                )}
              </div>

              <div class="fileMeta">
                ${escapeHtml(
                  file.type || ""
                )}

                ${
                  sizeText
                    ? "• " +
                      escapeHtml(
                        sizeText
                      )
                    : ""
                }
              </div>
            </div>

            <div class="fileActions">
              <a
                class="miniBtn"
                href="${escapeHtml(
                  url
                )}"
                target="_blank"
                rel="noopener"
              >
                ${ui(
                  "Відкрити"
                )}
              </a>

              <button
                type="button"
                class="miniBtn danger"
                data-detach-file="${escapeHtml(
                  String(id)
                )}"
              >
                ${ui(
                  "Відв’язати"
                )}
              </button>
            </div>
          </div>
        `;
      })
      .join("");


  wrap.onclick =
    (event) => {
      const button =
        event.target.closest(
          "[data-detach-file]"
        );

      if (!button) return;

      event.preventDefault();

      const fileId =
        button.dataset
          .detachFile;

      if (!fileId) return;

      detachFileFromVisit(
        visitId,
        fileId
      );

      renderVisitFiles(
        visitId
      );
    };
}


async function updateStaffApi(
  staffId,
  payload
) {
  Object.assign(
    SETTINGS_INTERFACE_TEXT,
    {
      "Не вдалося оновити дані співробітника.": {
        en: "Could not update the employee’s details.",
        de: "Die Mitarbeiterdaten konnten nicht aktualisiert werden.",
        pl: "Nie udało się zaktualizować danych pracownika.",
      },
    }
  );


  try {
    const response =
      await fetch(
        `/api/staff/${encodeURIComponent(
          staffId
        )}`,
        {
          method: "PUT",

          credentials:
            "include",

          headers: {
            "Content-Type":
              "application/json",

            Accept:
              "application/json",

            ...getOrgHeaders(),
          },

          body:
            JSON.stringify(
              payload || {}
            ),
        }
      );

    const responseText =
      await response.text();

    let json = null;

    try {
      json =
        responseText
          ? JSON.parse(
              responseText
            )
          : null;
    } catch {
      json = null;
    }


    if (
      !response.ok ||
      json?.ok !== true
    ) {
      throw new Error(
        json?.error ||
        `Staff update HTTP ${response.status}`
      );
    }

    return json.data ||
      null;
  } catch (error) {
    console.error(
      "Staff update failed:",
      error
    );

    showSettingsMessage(
      getSettingsSafeErrorText(
        error,
        "Не вдалося оновити дані співробітника."
      )
    );

    return null;
  }
}
async function renderStaffSpecsBox(
  selectedIds = []
) {
  Object.assign(
    TEAM_INTERFACE_TEXT,
    {
      "Напрям": {
        en: "Specialization",
        de: "Fachgebiet",
        pl: "Specjalizacja",
      },

      "Оберіть напрями": {
        en: "Select specializations",
        de: "Fachgebiete auswählen",
        pl: "Wybierz specjalizacje",
      },

      "Спочатку додайте напрями клініки вище.": {
        en: "Add clinic specializations above first.",
        de: "Fügen Sie zuerst oben die Fachgebiete der Klinik hinzu.",
        pl: "Najpierw dodaj powyżej specjalizacje kliniki.",
      },
    }
  );


  const box =
    $("#staffSpecsBox");

  if (!box) return;

  const loaded =
    await loadSpecializationsApi();

  const specs =
    Array.isArray(
      loaded
    )
      ? loaded
      : [];

  const selected =
    new Set(
      (
        Array.isArray(
          selectedIds
        )
          ? selectedIds
          : []
      ).map(
        String
      )
    );


  box.innerHTML =
    specs.length
      ? specs
          .map((spec) => {
            const name =
              spec.name ||
              getTeamInterfaceText(
                "Напрям"
              );

            return `
              <label class="staffSpecializationOption">
                <input
                  type="checkbox"
                  data-staff-spec
                  data-staff-spec-name="${escapeHtml(
                    name
                  )}"
                  value="${escapeHtml(
                    String(
                      spec.id
                    )
                  )}"
                  ${
                    selected.has(
                      String(
                        spec.id
                      )
                    )
                      ? "checked"
                      : ""
                  }
                >

                <span
                  class="staffSpecDot"
                  style="background:${escapeHtml(
                    spec.color ||
                    "#7C5CFF"
                  )}"
                ></span>

                <span
                  class="staffSpecializationOptionName"
                  data-team-content
                >
                  ${escapeHtml(
                    name
                  )}
                </span>

                <span class="staffSpecializationCheckmark">
                  ✓
                </span>
              </label>
            `;
          })
          .join("")
      : `
        <div class="hint">
          ${escapeHtml(
            getTeamInterfaceText(
              "Спочатку додайте напрями клініки вище."
            )
          )}
        </div>
      `;


  const toggle =
    $("#staffSpecializationToggle");

  const select =
    $("#staffSpecializationSelect");


  const updateSummary =
    () => {
      const summary =
        $("#staffSpecializationSummary");

      if (!summary) return;

      const checked =
        Array.from(
          box.querySelectorAll(
            "[data-staff-spec]:checked"
          )
        );

      summary.innerHTML =
        checked.length
          ? checked
              .map((input) => {
                const option =
                  input.closest(
                    ".staffSpecializationOption"
                  );

                const name =
                  input.dataset
                    .staffSpecName ||
                  getTeamInterfaceText(
                    "Напрям"
                  );

                const color =
                  option
                    ?.querySelector(
                      ".staffSpecDot"
                    )
                    ?.style
                    ?.background ||
                  "#7C5CFF";

                return `
                  <span
                    class="staffSpecializationChip"
                    data-team-content
                    style="--specialization-color:${escapeHtml(
                      color
                    )}"
                  >
                    ${escapeHtml(
                      name
                    )}
                  </span>
                `;
              })
              .join("")
          : `
            <span class="staffSpecializationPlaceholder">
              ${escapeHtml(
                getTeamInterfaceText(
                  "Оберіть напрями"
                )
              )}
            </span>
          `;
    };


  const setOpen =
    (isOpen) => {
      box.hidden =
        !isOpen;

      box.setAttribute(
        "aria-hidden",
        String(
          !isOpen
        )
      );

      toggle?.setAttribute(
        "aria-expanded",
        String(
          isOpen
        )
      );

      select?.classList.toggle(
        "open",
        isOpen
      );
    };


  if (toggle) {
    toggle.onclick =
      () => {
        setOpen(
          box.hidden
        );
      };
  }


  box.onchange =
    () => {
      updateSummary();

      setOpen(
        false
      );

      toggle?.focus();
    };


  setOpen(
    false
  );

  updateSummary();
}


