function clearOwnerFieldError(
  input
) {
  if (!input) {
    return;
  }

  const field =
    input.closest(
      ".pugVisitField"
    );

  field?.classList.remove(
    "has-error"
  );

  field
    ?.querySelector(
      ".pugOwnerFieldError"
    )
    ?.remove();

  input.removeAttribute(
    "aria-invalid"
  );
}

function clearOwnerFormErrors() {
  document
    .querySelectorAll(
      "#ownerModal .pugVisitInput"
    )
    .forEach(
      clearOwnerFieldError
    );
}

function showOwnerSaveError(
  error = null
) {
  showCrmNotice({
    icon: "⚠️",

    title:
      translateInterfaceText(
        "owners.form.saveErrorTitle"
      ),

    text:
      calendarErrorMessage(
        error,
        translateInterfaceText(
          "owners.form.saveError"
        )
      ),
  });
}

function showOwnerFieldError(
  selector,
  translationKey
) {
  clearOwnerFormErrors();

  const input =
    document.querySelector(
      selector
    );

  const field =
    input?.closest(
      ".pugVisitField"
    );

  if (!input || !field) {
    return;
  }

  const error =
    document.createElement(
      "small"
    );

  error.className =
    "pugOwnerFieldError";

  error.textContent =
    translateInterfaceText(
      translationKey
    );

  field.classList.add(
    "has-error"
  );

  field.appendChild(
    error
  );

  input.setAttribute(
    "aria-invalid",
    "true"
  );

  input.focus();
}

document
  .querySelectorAll(
    "#ownerModal .pugVisitInput"
  )
  .forEach((input) => {
    input.addEventListener(
      "input",
      () => {
        clearOwnerFieldError(
          input
        );
      }
    );
  });


